
window.CHAPTER_DATA[1] = "<section class=\"chapter-section\" id=\"c11c-ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Chemistry &bull; Chapter 1</div>\n      <h2>Some Basic Concepts of Chemistry</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 36 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:white; padding:20px; border-radius:12px; border:1px solid #e2e8f0; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\"><path d=\"M10 2v7.31M14 2v7.31M8.5 2h7M14 9.31a6.5 6.5 0 1 1-4 0\"/></svg>\n      Stoichiometric Mechanics: The Universal Mole Road Map &amp; Limiting Reagent Balance\n    </h3>\n    <svg viewBox=\"0 0 780 230\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Panel 1: The Mole Road Map -->\n      <rect x=\"15\" y=\"15\" width=\"375\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"35\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">1. Universal Mole Interconversion Map:</text>\n\n      <!-- Center Node: MOLES (n) -->\n      <circle cx=\"200\" cy=\"125\" r=\"32\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2.5\"/>\n      <text x=\"180\" y=\"122\" font-size=\"11\" font-weight=\"900\" fill=\"#065f46\">MOLES</text>\n      <text x=\"193\" y=\"136\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#047857\">(n)</text>\n\n      <!-- Top Node: Particles / Molecules -->\n      <rect x=\"150\" y=\"48\" width=\"100\" height=\"26\" rx=\"5\" fill=\"#f0fdf4\" stroke=\"#86efac\"/>\n      <text x=\"162\" y=\"65\" font-size=\"9\" font-weight=\"bold\" fill=\"#166534\">Number (N)</text>\n      <line x1=\"200\" y1=\"74\" x2=\"200\" y2=\"93\" stroke=\"#059669\" stroke-width=\"1.8\"/>\n      <text x=\"206\" y=\"86\" font-size=\"7.5\" fill=\"#475569\">&times; N_A / &divide; N_A</text>\n\n      <!-- Left Node: Mass (g) -->\n      <rect x=\"35\" y=\"112\" width=\"85\" height=\"26\" rx=\"5\" fill=\"#eff6ff\" stroke=\"#bfdbfe\"/>\n      <text x=\"47\" y=\"129\" font-size=\"9\" font-weight=\"bold\" fill=\"#1e40af\">Mass (w, g)</text>\n      <line x1=\"120\" y1=\"125\" x2=\"168\" y2=\"125\" stroke=\"#2563eb\" stroke-width=\"1.8\"/>\n      <text x=\"126\" y=\"118\" font-size=\"7.5\" fill=\"#475569\">&divide; M</text>\n      <text x=\"126\" y=\"138\" font-size=\"7.5\" fill=\"#475569\">&times; M</text>\n\n      <!-- Right Node: Volume at STP (L) -->\n      <rect x=\"275\" y=\"112\" width=\"100\" height=\"26\" rx=\"5\" fill=\"#fdf4ff\" stroke=\"#f0abfc\"/>\n      <text x=\"283\" y=\"129\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#86198f\">Gas Vol (STP, L)</text>\n      <line x1=\"232\" y1=\"125\" x2=\"275\" y2=\"125\" stroke=\"#c026d3\" stroke-width=\"1.8\"/>\n      <text x=\"238\" y=\"118\" font-size=\"7.5\" fill=\"#475569\">&times; 22.4L</text>\n      <text x=\"238\" y=\"138\" font-size=\"7.5\" fill=\"#475569\">&divide; 22.4L</text>\n\n      <!-- Bottom Node: Molarity (M) -->\n      <rect x=\"150\" y=\"175\" width=\"100\" height=\"26\" rx=\"5\" fill=\"#fff7ed\" stroke=\"#fed7aa\"/>\n      <text x=\"162\" y=\"192\" font-size=\"9\" font-weight=\"bold\" fill=\"#9a3412\">Molarity (M)</text>\n      <line x1=\"200\" y1=\"157\" x2=\"200\" y2=\"175\" stroke=\"#ea580c\" stroke-width=\"1.8\"/>\n      <text x=\"206\" y=\"169\" font-size=\"7.5\" fill=\"#475569\">M = n / V(L)</text>\n\n      <!-- Panel 2: Limiting Reagent & Chemical Stoichiometry -->\n      <rect x=\"405\" y=\"15\" width=\"360\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">2. Limiting Reagent &amp; Stoichiometric Balance:</text>\n\n      <!-- Reaction Scheme: aA + bB -> cC -->\n      <rect x=\"425\" y=\"52\" width=\"320\" height=\"34\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#a7f3d0\"/>\n      <text x=\"445\" y=\"73\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#065f46\">a A + b B &longrightarrow; c C + d D (Stoichiometric Ratio)</text>\n\n      <!-- Visual comparison boxes -->\n      <rect x=\"430\" y=\"98\" width=\"145\" height=\"100\" rx=\"6\" fill=\"#fff\" stroke=\"#e2e8f0\"/>\n      <text x=\"440\" y=\"116\" font-size=\"9\" font-weight=\"bold\" fill=\"#b91c1c\">Limiting Reagent:</text>\n      <text x=\"440\" y=\"133\" font-size=\"8\" fill=\"#334155\">&bull; Smallest (Moles / coeff)</text>\n      <text x=\"440\" y=\"149\" font-size=\"8\" fill=\"#334155\">&bull; Completely consumed</text>\n      <text x=\"440\" y=\"165\" font-size=\"8\" font-weight=\"bold\" fill=\"#b91c1c\">&bull; Dictates Product Mass</text>\n      <text x=\"440\" y=\"181\" font-size=\"7.5\" fill=\"#64748b\">&bull; Reaction halts when zero</text>\n\n      <rect x=\"590\" y=\"98\" width=\"160\" height=\"100\" rx=\"6\" fill=\"#fff\" stroke=\"#e2e8f0\"/>\n      <text x=\"600\" y=\"116\" font-size=\"9\" font-weight=\"bold\" fill=\"#047857\">Excess Reagent:</text>\n      <text x=\"600\" y=\"133\" font-size=\"8\" fill=\"#334155\">&bull; Larger (Moles / coeff)</text>\n      <text x=\"600\" y=\"149\" font-size=\"8\" fill=\"#334155\">&bull; Portion left unreacted</text>\n      <text x=\"600\" y=\"165\" font-size=\"8\" font-weight=\"bold\" fill=\"#047857\">&bull; Remaining = Initial - Used</text>\n      <text x=\"600\" y=\"181\" font-size=\"7.5\" fill=\"#64748b\">&bull; Safe surplus in reactions</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1.1 to 1.36: Laws of Chemical Combination, Dalton's Theory, Mole Concept, Stoichiometry, Limiting Reagent &amp; Solution Concentration Units</div>\n\n  <!-- c11c-ch1-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q1')\">\n      <div class=\"q-num\">Question 1.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the molar mass of the following:<br>(i) $\\text{H}_2\\text{O}$<br>(ii) $\\text{CO}_2$<br>(iii) $\\text{CH}_4$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Using standard atomic masses: $\\text{H} = 1.008\\text{ u}$, $\\text{C} = 12.011\\text{ u}$, $\\text{O} = 16.00\\text{ u}$.<br><br>\n    <b>(i) Water ($\\text{H}_2\\text{O}$):</b><br>\n    $$\\text{Molar mass} = 2 \\times (\\text{Atomic mass of H}) + 1 \\times (\\text{Atomic mass of O})$$<br>\n    $$\\text{Molar mass} = 2(1.008\\text{ u}) + 16.00\\text{ u} = 2.016 + 16.00 = \\mathbf{18.016\\text{ g mol}^{-1} \\approx 18.02\\text{ g mol}^{-1}}$$<br><br>\n    <b>(ii) Carbon dioxide ($\\text{CO}_2$):</b><br>\n    $$\\text{Molar mass} = 1 \\times (\\text{Atomic mass of C}) + 2 \\times (\\text{Atomic mass of O})$$<br>\n    $$\\text{Molar mass} = 12.011\\text{ u} + 2(16.00\\text{ u}) = 12.011 + 32.00 = \\mathbf{44.011\\text{ g mol}^{-1} \\approx 44.01\\text{ g mol}^{-1}}$$<br><br>\n    <b>(iii) Methane ($\\text{CH}_4$):</b><br>\n    $$\\text{Molar mass} = 1 \\times (\\text{Atomic mass of C}) + 4 \\times (\\text{Atomic mass of H})$$<br>\n    $$\\text{Molar mass} = 12.011\\text{ u} + 4(1.008\\text{ u}) = 12.011 + 4.032 = \\mathbf{16.043\\text{ g mol}^{-1} \\approx 16.04\\text{ g mol}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; 18.02\\text{ g/mol},\\; (ii)\\; 44.01\\text{ g/mol},\\; (iii)\\; 16.04\\text{ g/mol.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Calculation of molar mass of $\\text{H}_2\\text{O} = 18.02\\text{ g/mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Calculation of molar mass of $\\text{CO}_2 = 44.01\\text{ g/mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Calculation of molar mass of $\\text{CH}_4 = 16.04\\text{ g/mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q2')\">\n      <div class=\"q-num\">Question 1.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the mass percentage of different elements present in sodium sulphate ($\\text{Na}_2\\text{SO}_4$).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Molar mass of Sodium Sulphate ($\\text{Na}_2\\text{SO}_4$):</b><br>\n    Atomic masses: $\\text{Na} = 22.99\\text{ g/mol}$, $\\text{S} = 32.06\\text{ g/mol}$, $\\text{O} = 16.00\\text{ g/mol}$.<br>\n    $$M(\\text{Na}_2\\text{SO}_4) = 2(22.99) + 32.06 + 4(16.00) = 45.98 + 32.06 + 64.00 = \\mathbf{142.04\\text{ g mol}^{-1} \\approx 142.06\\text{ g mol}^{-1}}$$<br><br>\n    <b>2. Mass percentage formula:</b><br>\n    $$\\text{Mass } \\% \\text{ of element} = \\frac{\\text{Mass of that element in 1 mol compound}}{\\text{Molar mass of compound}} \\times 100$$<br><br>\n    • **Mass percentage of Sodium ($\\text{Na}$):**<br>\n    $$\\%\\text{Na} = \\frac{45.98\\text{ g}}{142.04\\text{ g}} \\times 100 = \\mathbf{32.37\\%}$$<br><br>\n    • **Mass percentage of Sulphur ($\\text{S}$):**<br>\n    $$\\%\\text{S} = \\frac{32.06\\text{ g}}{142.04\\text{ g}} \\times 100 = \\mathbf{22.57\\%}$$<br><br>\n    • **Mass percentage of Oxygen ($\\text{O}$):**<br>\n    $$\\%\\text{O} = \\frac{64.00\\text{ g}}{142.04\\text{ g}} \\times 100 = \\mathbf{45.06\\%}$$<br><br>\n    $$\\mathbf{\\text{Results: Sodium = } 32.37\\%,\\; \\text{Sulphur = } 22.57\\%,\\; \\text{Oxygen = } 45.06\\% \\; (\\Sigma = 100.0\\%).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of molar mass of $\\text{Na}_2\\text{SO}_4 = 142.04\\text{ g/mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation of mass % of $\\text{Na} = 32.37\\%$ and $\\text{S} = 22.57\\%$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation of mass % of $\\text{O} = 45.06\\%$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q3')\">\n      <div class=\"q-num\">Question 1.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Determine the empirical formula of an oxide of iron which has $69.9\\%$ iron and $30.1\\%$ dioxygen by mass.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mass percentage of Iron ($\\text{Fe}$) = $69.9\\%$<br>\n    • Mass percentage of Oxygen ($\\text{O}$) = $30.1\\%$<br>\n    • Atomic mass of $\\text{Fe} = 55.85\\text{ g mol}^{-1}$, Atomic mass of $\\text{O} = 16.00\\text{ g mol}^{-1}$.<br><br>\n    <b>Tabular Calculation for Empirical Formula:</b><br>\n    <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.85rem;\">\n      <thead>\n        <tr style=\"background:#f1f5f9; text-align:left; border-bottom:2px solid #cbd5e1;\">\n          <th style=\"padding:8px;\">Element</th>\n          <th style=\"padding:8px;\">Mass %</th>\n          <th style=\"padding:8px;\">Atomic Mass</th>\n          <th style=\"padding:8px;\">Moles (Mass / At. Mass)</th>\n          <th style=\"padding:8px;\">Molar Ratio (Divide by min)</th>\n          <th style=\"padding:8px;\">Simplest Whole No. Ratio</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>$\\text{Fe}$</b></td>\n          <td style=\"padding:8px;\">$69.9$</td>\n          <td style=\"padding:8px;\">$55.85$</td>\n          <td style=\"padding:8px;\">$\\frac{69.9}{55.85} = 1.2515$</td>\n          <td style=\"padding:8px;\">$\\frac{1.2515}{1.2515} = 1.00$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$1 \\times 2 = 2$</td>\n        </tr>\n        <tr>\n          <td style=\"padding:8px;\"><b>$\\text{O}$</b></td>\n          <td style=\"padding:8px;\">$30.1$</td>\n          <td style=\"padding:8px;\">$16.00$</td>\n          <td style=\"padding:8px;\">$\\frac{30.1}{16.00} = 1.8812$</td>\n          <td style=\"padding:8px;\">$\\frac{1.8812}{1.2515} = 1.503 \\approx 1.5$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$1.5 \\times 2 = 3$</td>\n        </tr>\n      </tbody>\n    </table>\n    $$\\mathbf{\\text{The empirical formula of the iron oxide is } \\text{Fe}_2\\text{O}_3\\text{ (Ferric oxide / Iron(III) oxide).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating moles of $\\text{Fe} = 1.25$ and moles of $\\text{O} = 1.88$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding atomic molar ratio $\\text{Fe} : \\text{O} = 1 : 1.5$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying by 2 to obtain whole-number ratio $\\text{Fe}_2\\text{O}_3$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q4')\">\n      <div class=\"q-num\">Question 1.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the amount of carbon dioxide that could be produced when:<br>(i) $1\\text{ mole}$ of carbon is burnt in air.<br>(ii) $1\\text{ mole}$ of carbon is burnt in $16\\text{ g}$ of dioxygen.<br>(iii) $2\\text{ moles}$ of carbon are burnt in $16\\text{ g}$ of dioxygen.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Balanced chemical combustion equation:<br>\n    $$\\text{C}(s) + \\text{O}_2(g) \\longrightarrow \\text{CO}_2(g)$$<br>\n    Stoichiometry: $1\\text{ mol C } (12\\text{ g}) + 1\\text{ mol } \\text{O}_2\\text{ } (32\\text{ g}) \\longrightarrow 1\\text{ mol } \\text{CO}_2\\text{ } (44\\text{ g})$.<br><br>\n    <b>(i) $1\\text{ mole}$ of carbon burnt in air (excess $\\text{O}_2$):</b><br>\n    Carbon is completely consumed: $1\\text{ mol of C}$ produces $1\\text{ mol of } \\text{CO}_2$.<br>\n    $$\\text{Amount of } \\text{CO}_2 = 1 \\times 44\\text{ g} = \\mathbf{44\\text{ g}}$$<br><br>\n    <b>(ii) $1\\text{ mole}$ of carbon burnt in $16\\text{ g}$ of dioxygen:</b><br>\n    • Moles of $\\text{O}_2$ provided: $n(\\text{O}_2) = \\frac{16\\text{ g}}{32\\text{ g mol}^{-1}} = 0.5\\text{ mol}$.<br>\n    • $1\\text{ mol}$ of carbon requires $1\\text{ mol}$ of $\\text{O}_2$. Since only $0.5\\text{ mol}$ of $\\text{O}_2$ is available, **dioxygen ($\\text{O}_2$) is the limiting reagent**.<br>\n    • $0.5\\text{ mol of } \\text{O}_2$ produces $0.5\\text{ mol of } \\text{CO}_2$:<br>\n    $$\\text{Amount of } \\text{CO}_2 = 0.5 \\times 44\\text{ g} = \\mathbf{22\\text{ g}}$$<br><br>\n    <b>(iii) $2\\text{ moles}$ of carbon burnt in $16\\text{ g}$ of dioxygen:</b><br>\n    • Again, moles of $\\text{O}_2 = \\frac{16}{32} = 0.5\\text{ mol}$.<br>\n    • $\\text{O}_2$ remains the limiting reagent (carbon is in large excess).<br>\n    • Amount of $\\text{CO}_2$ formed depends solely on $\\text{O}_2$ consumed:<br>\n    $$\\text{Amount of } \\text{CO}_2 = 0.5 \\times 44\\text{ g} = \\mathbf{22\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; 44\\text{ g of } \\text{CO}_2,\\; (ii)\\; 22\\text{ g of } \\text{CO}_2,\\; (iii)\\; 22\\text{ g of } \\text{CO}_2.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Full stoichiometric calculation: $1\\text{ mol } \\text{CO}_2 = 44\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Identifying $\\text{O}_2$ as limiting reagent and finding $22\\text{ g } \\text{CO}_2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Identifying limiting reagent with excess carbon and finding $22\\text{ g } \\text{CO}_2$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q5')\">\n      <div class=\"q-num\">Question 1.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the mass of sodium acetate ($\\text{CH}_3\\text{COONa}$) required to make $500\\text{ mL}$ of $0.375\\text{ molar}$ aqueous solution. Molar mass of sodium acetate is $82.0245\\text{ g mol}^{-1}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Molarity of solution $M = 0.375\\text{ M} = 0.375\\text{ mol L}^{-1}$<br>\n    • Volume of solution $V = 500\\text{ mL} = 0.500\\text{ L}$<br>\n    • Molar mass of $\\text{CH}_3\\text{COONa}$ = $82.0245\\text{ g mol}^{-1}$<br><br>\n    <b>1. Formula for Molarity:</b><br>\n    $$\\text{Molarity } (M) = \\frac{\\text{Moles of solute } (n)}{\\text{Volume of solution in litres } (V)}$$<br>\n    $$n = M \\times V = (0.375\\text{ mol L}^{-1}) \\times (0.500\\text{ L}) = \\mathbf{0.1875\\text{ mol}}$$<br><br>\n    <b>2. Mass of sodium acetate required ($m$):</b><br>\n    $$m = n \\times \\text{Molar mass} = (0.1875\\text{ mol}) \\times (82.0245\\text{ g mol}^{-1})$$<br>\n    $$m = 15.37959\\text{ g} \\approx \\mathbf{15.38\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{The mass of sodium acetate required is approximately } 15.38\\text{ g.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Molarity relation and calculating moles required: $n = 0.1875\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating required mass: $m = 0.1875 \\times 82.0245 = 15.38\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q6')\">\n      <div class=\"q-num\">Question 1.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the concentration of nitric acid in moles per litre in a sample which has a density, $1.41\\text{ g mL}^{-1}$ and the mass per cent of nitric acid in it being $69\\%$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Density of nitric acid sample $d = 1.41\\text{ g mL}^{-1}$<br>\n    • Mass percentage of $\\text{HNO}_3$ = $69\\%$<br>\n    • Molar mass of $\\text{HNO}_3 = 1.008 + 14.007 + 3(16.00) = \\mathbf{63.015\\text{ g mol}^{-1} \\approx 63.0\\text{ g mol}^{-1}}$<br><br>\n    <b>Method 1: Direct Concept (Basis: $1\\text{ L} = 1000\\text{ mL}$ of solution):</b><br>\n    1. Mass of $1000\\text{ mL}$ of solution:<br>\n    $$\\text{Mass} = V \\times d = 1000\\text{ mL} \\times 1.41\\text{ g mL}^{-1} = \\mathbf{1410\\text{ g}}$$<br><br>\n    2. Mass of pure $\\text{HNO}_3$ present in $1000\\text{ mL}$ of solution:<br>\n    $$\\text{Mass of } \\text{HNO}_3 = 1410\\text{ g} \\times \\frac{69}{100} = \\mathbf{972.9\\text{ g}}$$<br><br>\n    3. Moles of $\\text{HNO}_3$ in $1\\text{ L}$ (Molarity):<br>\n    $$\\text{Molarity } (M) = \\frac{\\text{Mass of } \\text{HNO}_3}{\\text{Molar mass}} = \\frac{972.9\\text{ g}}{63.015\\text{ g mol}^{-1}} = \\mathbf{15.439\\text{ mol L}^{-1} \\approx 15.44\\text{ M}}$$<br><br>\n    <i>Shortcut check formula:</i> $M = \\frac{\\% \\times d \\times 10}{M_w} = \\frac{69 \\times 1.41 \\times 10}{63.015} = \\frac{972.9}{63.015} = \\mathbf{15.44\\text{ M}}$.<br><br>\n    $$\\mathbf{\\text{The concentration of nitric acid is } 15.44\\text{ mol L}^{-1} \\text{ (or } 15.44\\text{ M}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating mass of $1\\text{ L}$ solution $= 1410\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating mass of $\\text{HNO}_3 = 972.9\\text{ g}$ from $69\\%$ mass percentage</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating molarity $M = 972.9 / 63 = 15.44\\text{ mol L}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q7')\">\n      <div class=\"q-num\">Question 1.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How much copper can be obtained from $100\\text{ g}$ of copper sulphate ($\\text{CuSO}_4$)? (Atomic mass of $\\text{Cu} = 63.5\\text{ u}$, $\\text{S} = 32.0\\text{ u}$, $\\text{O} = 16.0\\text{ u}$).\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Molar mass of Copper Sulphate ($\\text{CuSO}_4$):</b><br>\n    $$M(\\text{CuSO}_4) = 63.5 + 32.0 + 4(16.0) = 63.5 + 32.0 + 64.0 = \\mathbf{159.5\\text{ g mol}^{-1}}$$<br><br>\n    <b>2. Stoichiometric proportion:</b><br>\n    In $1\\text{ mole } (159.5\\text{ g})$ of $\\text{CuSO}_4$, there is $1\\text{ mole } (63.5\\text{ g})$ of copper ($\\text{Cu}$).<br><br>\n    $$\\text{Mass of copper in } 100\\text{ g of } \\text{CuSO}_4 = \\frac{63.5\\text{ g}}{159.5\\text{ g}} \\times 100\\text{ g}$$<br>\n    $$\\text{Mass of copper} = \\frac{6350}{159.5} = \\mathbf{39.81\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{Approximately } 39.81\\text{ g of copper can be obtained from } 100\\text{ g of copper sulphate.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of molar mass of $\\text{CuSO}_4 = 159.5\\text{ g/mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stoichiometric ratio evaluation yielding $39.81\\text{ g of Cu}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q8')\">\n      <div class=\"q-num\">Question 1.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Determine the molecular formula of an oxide of iron in which the mass per cent of iron and oxygen are $69.9$ and $30.1$ respectively. Given that the molar mass of the oxide is $159.69\\text{ g mol}^{-1}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    From Question 1.3:<br>\n    • Empirical formula calculated from $69.9\\% \\text{ Fe}$ and $30.1\\% \\text{ O}$ is: $\\mathbf{\\text{Fe}_2\\text{O}_3}$.<br><br>\n    <b>1. Empirical Formula Mass of $\\text{Fe}_2\\text{O}_3$:</b><br>\n    $$\\text{Empirical formula mass} = 2(55.85) + 3(16.00) = 111.70 + 48.00 = \\mathbf{159.70\\text{ g mol}^{-1}}$$<br><br>\n    <b>2. Ratio factor ($n$):</b><br>\n    $$n = \\frac{\\text{Molar mass}}{\\text{Empirical formula mass}} = \\frac{159.69\\text{ g mol}^{-1}}{159.70\\text{ g mol}^{-1}} \\approx \\mathbf{1}$$<br><br>\n    <b>3. Molecular Formula:</b><br>\n    $$\\text{Molecular formula} = n \\times (\\text{Empirical formula}) = 1 \\times (\\text{Fe}_2\\text{O}_3) = \\mathbf{\\text{Fe}_2\\text{O}_3}$$<br><br>\n    $$\\mathbf{\\text{The molecular formula of the iron oxide is } \\text{Fe}_2\\text{O}_3\\text{.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating empirical formula mass of $\\text{Fe}_2\\text{O}_3 = 159.7\\text{ g/mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating $n = 1$ and concluding molecular formula is $\\text{Fe}_2\\text{O}_3$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q9')\">\n      <div class=\"q-num\">Question 1.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the atomic mass (average) of chlorine using the following data:<br>• $^{35}\\text{Cl}$: Natural Abundance = $75.77\\%$, Molar Mass = $34.9689\\text{ u}$<br>• $^{37}\\text{Cl}$: Natural Abundance = $24.23\\%$, Molar Mass = $36.9659\\text{ u}$\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Formula for Fractional Average Atomic Mass:</b><br>\n    $$\\text{Average Atomic Mass} = \\sum (\\text{Fractional Abundance} \\times \\text{Isotopic Mass})$$<br><br>\n    $$\\text{Average Atomic Mass} = \\left(\\frac{75.77}{100} \\times 34.9689\\text{ u}\\right) + \\left(\\frac{24.23}{100} \\times 36.9659\\text{ u}\\right)$$<br>\n    $$\\text{Average Atomic Mass} = (0.7577 \\times 34.9689) + (0.2423 \\times 36.9659)$$<br>\n    $$\\text{Average Atomic Mass} = 26.4959\\text{ u} + 8.9568\\text{ u} = \\mathbf{35.4527\\text{ u} \\approx 35.45\\text{ u}}$$<br><br>\n    $$\\mathbf{\\text{The average atomic mass of naturally occurring chlorine is } 35.45\\text{ u.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up weighted isotopic average equation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate numerical evaluation yielding $35.45\\text{ u}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q10')\">\n      <div class=\"q-num\">Question 1.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In three moles of ethane ($\\text{C}_2\\text{H}_6$), calculate the following:<br>(i) Number of moles of carbon atoms.<br>(ii) Number of moles of hydrogen atoms.<br>(iii) Number of molecules of ethane.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: $3\\text{ moles of ethane } (\\text{C}_2\\text{H}_6)$.<br>\n    $1\\text{ molecule of } \\text{C}_2\\text{H}_6$ contains $2\\text{ atoms of C}$ and $6\\text{ atoms of H}$.<br>\n    Therefore, $1\\text{ mole of } \\text{C}_2\\text{H}_6$ contains $2\\text{ moles of C atoms}$ and $6\\text{ moles of H atoms}$.<br><br>\n    <b>(i) Number of moles of carbon atoms:</b><br>\n    $$\\text{Moles of C} = 3 \\times 2 = \\mathbf{6\\text{ moles of C atoms}}$$<br><br>\n    <b>(ii) Number of moles of hydrogen atoms:</b><br>\n    $$\\text{Moles of H} = 3 \\times 6 = \\mathbf{18\\text{ moles of H atoms}}$$<br><br>\n    <b>(iii) Number of molecules of ethane:</b><br>\n    $$\\text{Molecules} = \\text{Moles} \\times N_A = 3 \\times (6.022 \\times 10^{23}) = \\mathbf{1.8066 \\times 10^{24}\\text{ molecules} \\approx 1.81 \\times 10^{24}\\text{ molecules}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; 6\\text{ moles C},\\; (ii)\\; 18\\text{ moles H},\\; (iii)\\; 1.81 \\times 10^{24}\\text{ molecules of ethane.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Moles of carbon atoms $= 6\\text{ moles}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Moles of hydrogen atoms $= 18\\text{ moles}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Molecules of ethane $= 1.81 \\times 10^{24}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q11')\">\n      <div class=\"q-num\">Question 1.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the concentration of sugar ($\\text{C}_{12}\\text{H}_{22}\\text{O}_{11}$) in $\\text{mol L}^{-1}$ if its $20\\text{ g}$ are dissolved in enough water to make a final volume up to $2\\text{ L}$?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mass of sugar (solute) $w = 20\\text{ g}$<br>\n    • Final volume of solution $V = 2\\text{ L}$<br>\n    • Molar mass of sucrose ($\\text{C}_{12}\\text{H}_{22}\\text{O}_{11}$):<br>\n    $$M = 12(12.011) + 22(1.008) + 11(16.00) = 144.13 + 22.18 + 176.00 = \\mathbf{342.3\\text{ g mol}^{-1}}$$<br><br>\n    <b>1. Moles of sugar ($n$):</b><br>\n    $$n = \\frac{w}{M} = \\frac{20\\text{ g}}{342.3\\text{ g mol}^{-1}} = \\mathbf{0.05843\\text{ mol}}$$<br><br>\n    <b>2. Molar Concentration (Molarity $M$):</b><br>\n    $$\\text{Molarity } (M) = \\frac{n}{V} = \\frac{0.05843\\text{ mol}}{2\\text{ L}} = \\mathbf{0.02921\\text{ mol L}^{-1} \\approx 0.0292\\text{ M}}$$<br><br>\n    $$\\mathbf{\\text{The concentration of sugar in the solution is } 0.0292\\text{ mol L}^{-1} \\text{ (or } 2.92 \\times 10^{-2}\\text{ M}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of moles of sucrose $n = 20 / 342.3 = 0.0584\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating molarity $M = 0.0584 / 2 = 0.0292\\text{ mol L}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q12')\">\n      <div class=\"q-num\">Question 1.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If the density of methanol is $0.793\\text{ kg L}^{-1}$, what is its volume needed for making $2.5\\text{ L}$ of its $0.25\\text{ M}$ solution?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Target solution volume $V_2 = 2.5\\text{ L}$<br>\n    • Target molarity $M_2 = 0.25\\text{ M} = 0.25\\text{ mol L}^{-1}$<br>\n    • Density of pure methanol $\\rho = 0.793\\text{ kg L}^{-1} = 793\\text{ g L}^{-1}$<br>\n    • Molar mass of methanol ($\\text{CH}_3\\text{OH}$): $M_w = 12.01 + 4(1.008) + 16.00 = \\mathbf{32.04\\text{ g mol}^{-1}}$<br><br>\n    <b>1. Molarity of Pure Methanol ($M_1$):</b><br>\n    In $1\\text{ L}$ of pure methanol, there are $793\\text{ g}$ of $\\text{CH}_3\\text{OH}$.<br>\n    $$M_1 = \\frac{793\\text{ g}}{32.04\\text{ g mol}^{-1}} = \\mathbf{24.75\\text{ mol L}^{-1} = 24.75\\text{ M}}$$<br><br>\n    <b>2. Applying Dilution Law:</b><br>\n    $$M_1 V_1 = M_2 V_2$$<br>\n    $$(24.75\\text{ M}) \\times V_1 = (0.25\\text{ M}) \\times (2.5\\text{ L})$$<br>\n    $$V_1 = \\frac{0.625}{24.75} = \\mathbf{0.02525\\text{ L} = 25.25\\text{ mL} \\approx 25.3\\text{ mL}}$$<br><br>\n    $$\\mathbf{\\text{The volume of methanol needed is } 25.25\\text{ mL (or } 0.02525\\text{ L}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Determining molarity of pure methanol $M_1 = 793 / 32.04 = 24.75\\text{ M}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying dilution formula $M_1 V_1 = M_2 V_2$ to find $V_1 = 25.25\\text{ mL}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q13')\">\n      <div class=\"q-num\">Question 1.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Pressure is determined as force per unit area of the surface. The S.I. unit of pressure, pascal is as shown below: $1\\text{ Pa} = 1\\text{ N m}^{-2}$. If mass of air at sea level is $1034\\text{ g cm}^{-2}$, calculate the pressure in pascal.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mass per unit area $\\frac{m}{A} = 1034\\text{ g cm}^{-2}$<br>\n    • Convert to SI units ($\\text{kg m}^{-2}$):<br>\n    $$1034\\text{ g cm}^{-2} = \\frac{1034 \\times 10^{-3}\\text{ kg}}{10^{-4}\\text{ m}^2} = 1034 \\times 10 = \\mathbf{10340\\text{ kg m}^{-2}}$$<br>\n    • Acceleration due to gravity $g = 9.8\\text{ m s}^{-2}$<br><br>\n    <b>Calculation of Atmospheric Pressure ($P$):</b><br>\n    $$P = \\frac{F}{A} = \\frac{m g}{A} = \\left(\\frac{m}{A}\\right) \\times g$$<br>\n    $$P = (10340\\text{ kg m}^{-2}) \\times (9.8\\text{ m s}^{-2}) = \\mathbf{101332\\text{ N m}^{-2} = 1.01332 \\times 10^5\\text{ Pa}}$$<br><br>\n    $$\\mathbf{\\text{The pressure at sea level is } 1.01332 \\times 10^5\\text{ Pa (or } 1.013 \\times 10^5\\text{ Pa}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Unit conversion of mass per unit area to $10340\\text{ kg m}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating pressure $P = (m/A)g = 1.01332 \\times 10^5\\text{ Pa}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q14')\">\n      <div class=\"q-num\">Question 1.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the SI unit of mass? How is it defined?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. SI Unit of Mass:</b><br>\n    The SI base unit of mass is the **kilogram** (symbol: $\\mathbf{kg}$).<br><br>\n    <b>2. Modern Definition (CGPM 2019 Revision):</b><br>\n    The kilogram is defined by taking the fixed numerical value of the **Planck constant $h$** to be $6.62607015 \\times 10^{-34}$ when expressed in the unit $\\text{J s}$, which is equal to $\\text{kg m}^2\\text{ s}^{-1}$, where the metre and the second are defined in terms of the speed of light $c$ and the hyperfine transition frequency of caesium-133 $\\Delta \\nu_{\\text{Cs}}$.<br><br>\n    <i>Historical Note: Prior to May 20, 2019, the kilogram was defined as the mass of the international prototype of the kilogram (a cylinder of platinum-iridium alloy kept at the International Bureau of Weights and Measures at Sèvres, near Paris).</i>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Stating the SI unit of mass is kilogram (kg)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurately quoting the modern definition in terms of Planck constant $h$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q15')\">\n      <div class=\"q-num\">Question 1.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match the following prefixes with their multiples:<br>Prefixes: (i) micro, (ii) deca, (iii) mega, (iv) giga, (v) femto<br>Multiples: $10^6, 10^9, 10^{-6}, 10^{-15}, 10$\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Matching Prefixes with Standard Metric Multiples:</b><br><br>\n    <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.85rem;\">\n      <thead>\n        <tr style=\"background:#f1f5f9; text-align:left; border-bottom:2px solid #cbd5e1;\">\n          <th style=\"padding:8px;\">Prefix</th>\n          <th style=\"padding:8px;\">Symbol</th>\n          <th style=\"padding:8px;\">Multiple</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>(i) micro</b></td>\n          <td style=\"padding:8px;\">$\\mu$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$10^{-6}$</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>(ii) deca</b></td>\n          <td style=\"padding:8px;\">$\\text{da}$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$10$ (or $10^1$)</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>(iii) mega</b></td>\n          <td style=\"padding:8px;\">$\\text{M}$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$10^6$</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>(iv) giga</b></td>\n          <td style=\"padding:8px;\">$\\text{G}$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$10^9$</td>\n        </tr>\n        <tr>\n          <td style=\"padding:8px;\"><b>(v) femto</b></td>\n          <td style=\"padding:8px;\">$\\text{f}$</td>\n          <td style=\"padding:8px; font-weight:bold; color:#059669;\">$10^{-15}$</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Matching micro $\\to 10^{-6}$ and deca $\\to 10$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Matching mega $\\to 10^6$ and giga $\\to 10^9$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Matching femto $\\to 10^{-15}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q16')\">\n      <div class=\"q-num\">Question 1.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What do you mean by significant figures?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Definition:</b><br>\n    <b>Significant figures</b> are meaningful digits in a measured or calculated quantity which are known with certainty plus one final digit that is uncertain or estimated.<br><br>\n    <b>Key Principles:</b><br>\n    • The uncertainty in any experimental measurement is indicated by stating the number of significant figures.<br>\n    • For example, if a mass is recorded as $11.2\\text{ g}$, the digits '1' and '1' are completely certain, while the digit '2' is uncertain (with an inherent uncertainty of $\\pm 0.1\\text{ g}$). The measurement contains $3$ significant figures.<br>\n    • All non-zero digits are significant.<br>\n    • Zeros preceding the first non-zero digit are not significant (they merely indicate the decimal point).<br>\n    • Zeros between two non-zero digits are always significant.<br>\n    • Terminal zeros at the end of a number after a decimal point are significant.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Formal definition: certain digits plus one uncertain digit</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Example illustrating measurement precision and rules</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q17')\">\n      <div class=\"q-num\">Question 1.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A sample of drinking water was found to be severely contaminated with chloroform ($\\text{CHCl}_3$), supposed to be a carcinogen. The level of contamination was $15\\text{ ppm}$ (by mass):<br>(i) Express this in percent by mass.<br>(ii) Determine the molality of chloroform in the water sample.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Contamination level = $15\\text{ ppm}$ (parts per million by mass).<br>\n    • This means there are $15\\text{ g}$ of $\\text{CHCl}_3$ in $10^6\\text{ g}$ of solution.<br>\n    • Molar mass of $\\text{CHCl}_3 = 12.01 + 1.008 + 3(35.45) = 12.01 + 1.008 + 106.35 = \\mathbf{119.37\\text{ g mol}^{-1} \\approx 119.4\\text{ g mol}^{-1}}$.<br><br>\n    <b>(i) Percent by Mass:</b><br>\n    $$\\text{Mass } \\% = \\frac{\\text{Mass of } \\text{CHCl}_3}{\\text{Total mass of solution}} \\times 100$$<br>\n    $$\\text{Mass } \\% = \\frac{15\\text{ g}}{10^6\\text{ g}} \\times 100 = 15 \\times 10^{-4}\\% = \\mathbf{1.5 \\times 10^{-3}\\%}$$$$<br><br>\n    <b>(ii) Molality ($m$):</b><br>\n    • Mass of solute $\\text{CHCl}_3 = 15\\text{ g}$.<br>\n    • Mass of solvent (water) $= 10^6\\text{ g} - 15\\text{ g} \\approx 10^6\\text{ g} = 1000\\text{ kg}$.<br>\n    • Moles of $\\text{CHCl}_3$ ($n$):<br>\n    $$n = \\frac{15\\text{ g}}{119.37\\text{ g mol}^{-1}} = \\mathbf{0.12566\\text{ mol}}$$<br>\n    • Molality ($m$):<br>\n    $$m = \\frac{\\text{Moles of solute}}{\\text{Mass of solvent in kg}} = \\frac{0.12566\\text{ mol}}{1000\\text{ kg}} = \\mathbf{1.257 \\times 10^{-4}\\text{ m} \\approx 1.26 \\times 10^{-4}\\text{ mol kg}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; 1.5 \\times 10^{-3}\\%\\text{ by mass},\\; (ii)\\; 1.26 \\times 10^{-4}\\text{ m.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Converting 15 ppm to mass percentage: $1.5 \\times 10^{-3}\\%$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Calculating moles of chloroform $n = 0.1257\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating molality $m = 1.26 \\times 10^{-4}\\text{ mol kg}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q18')\">\n      <div class=\"q-num\">Question 1.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Express the following in scientific notation:<br>(i) $0.0048$<br>(ii) $234,000$<br>(iii) $8008$<br>(iv) $500.0$<br>(v) $6.0012$\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Scientific notation has the standard format $N \\times 10^n$, where $1 \\le N < 10$ and $n$ is an integer.<br><br>\n    • **(i) $0.0048$:** Move decimal 3 places to the right:<br>\n    $$0.0048 = \\mathbf{4.8 \\times 10^{-3}}$$<br><br>\n    • **(ii) $234,000$:** Move decimal 5 places to the left:<br>\n    $$234,000 = \\mathbf{2.34 \\times 10^5}$$<br><br>\n    • **(iii) $8008$:** Move decimal 3 places to the left:<br>\n    $$8008 = \\mathbf{8.008 \\times 10^3}$$<br><br>\n    • **(iv) $500.0$:** Move decimal 2 places to the left, retaining significant terminal zero:<br>\n    $$500.0 = \\mathbf{5.000 \\times 10^2}$$<br><br>\n    • **(v) $6.0012$:** Already in proper scientific range ($1 \\le N < 10$):<br>\n    $$6.0012 = \\mathbf{6.0012 \\times 10^0}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) $4.8 \\times 10^{-3}$ and (ii) $2.34 \\times 10^5$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) $8.008 \\times 10^3$ and (iv) $5.000 \\times 10^2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(v) $6.0012 \\times 10^0$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q19')\">\n      <div class=\"q-num\">Question 1.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How many significant figures are present in the following?<br>(i) $0.0025$<br>(ii) $208$<br>(iii) $5005$<br>(iv) $126,000$<br>(v) $500.0$<br>(vi) $2.0034$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Analysis using standard rules for significant figures:</b><br><br>\n    • **(i) $0.0025$:** **$2$ significant figures.** Leading zeros before '2' are place-holders and non-significant; '2' and '5' are significant.<br><br>\n    • **(ii) $208$:** **$3$ significant figures.** The zero is trapped between two non-zero digits.<br><br>\n    • **(iii) $5005$:** **$4$ significant figures.** Both zeros are trapped between two non-zero digits.<br><br>\n    • **(iv) $126,000$:** **$3$ significant figures.** Terminal zeros in a whole number without a decimal point are non-significant (in scientific notation: $1.26 \\times 10^5$).<br><br>\n    • **(v) $500.0$:** **$4$ significant figures.** Terminal zeros after a decimal point are explicitly significant.<br><br>\n    • **(vi) $2.0034$:** **$5$ significant figures.** Zeros trapped between non-zero digits are significant.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) 2 and (ii) 3 significant figures</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) 4 and (iv) 3 significant figures</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(v) 4 and (vi) 5 significant figures</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q20')\">\n      <div class=\"q-num\">Question 1.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Round up the following upto three significant figures:<br>(i) $34.216$<br>(ii) $10.4107$<br>(iii) $0.04597$<br>(iv) $2808$\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Rules for Rounding Off to Three Significant Figures:</b><br><br>\n    • **(i) $34.216$:** The fourth digit is $1$ (less than 5). We drop it without changing the third digit.<br>\n    $$\\mathbf{34.2}$$<br><br>\n    • **(ii) $10.4107$:** The fourth digit is $1$ (less than 5). We drop it.<br>\n    $$\\mathbf{10.4}$$<br><br>\n    • **(iii) $0.04597$:** Leading zeros are not significant. The first three significant figures are 4, 5, 9. The fourth digit is $7$ (greater than 5), so we round up $9$ to $10$, which cascades to round $459$ to $460$.<br>\n    $$\\mathbf{0.0460}$$<br><br>\n    • **(iv) $2808$:** The fourth digit is $8$ (greater than 5). Rounding up gives $2810$. In unambiguous scientific notation:<br>\n    $$\\mathbf{2810 \\quad \\text{or} \\quad 2.81 \\times 10^3}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) $34.2$ and (ii) $10.4$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) $0.0460$ and (iv) $2810$ (or $2.81 \\times 10^3$)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q21')\">\n      <div class=\"q-num\">Question 1.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The following data were obtained when dinitrogen and dioxygen react together to form different compounds:<br>• Compound I: Mass of $\\text{N}_2 = 14\\text{ g}$, Mass of $\\text{O}_2 = 16\\text{ g}$<br>• Compound II: Mass of $\\text{N}_2 = 14\\text{ g}$, Mass of $\\text{O}_2 = 32\\text{ g}$<br>• Compound III: Mass of $\\text{N}_2 = 28\\text{ g}$, Mass of $\\text{O}_2 = 32\\text{ g}$<br>• Compound IV: Mass of $\\text{N}_2 = 28\\text{ g}$, Mass of $\\text{O}_2 = 80\\text{ g}$<br>(a) Which law of chemical combination is obeyed by the above experimental data? Give its statement.<br>(b) Fill in the blanks in the following conversions:<br>(i) $1\\text{ km} = \\dots\\dots\\dots\\text{ mm} = \\dots\\dots\\dots\\text{ pm}$<br>(ii) $1\\text{ mg} = \\dots\\dots\\dots\\text{ kg} = \\dots\\dots\\dots\\text{ ng}$<br>(iii) $1\\text{ mL} = \\dots\\dots\\dots\\text{ L} = \\dots\\dots\\dots\\text{ dm}^3$\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(a) Law of Chemical Combination:</b><br>\n    Let us fix the mass of dinitrogen at $14\\text{ g}$ for all four compounds:<br>\n    • In Compound I: $14\\text{ g of } \\text{N}_2$ combines with **$16\\text{ g of } \\text{O}_2$** (ratio $= 16\\text{ g}$).<br>\n    • In Compound II: $14\\text{ g of } \\text{N}_2$ combines with **$32\\text{ g of } \\text{O}_2$** (ratio $= 32\\text{ g}$).<br>\n    • In Compound III: $28\\text{ g of } \\text{N}_2$ combines with $32\\text{ g of } \\text{O}_2 \\implies 14\\text{ g of } \\text{N}_2$ combines with **$16\\text{ g of } \\text{O}_2$**.<br>\n    • In Compound IV: $28\\text{ g of } \\text{N}_2$ combines with $80\\text{ g of } \\text{O}_2 \\implies 14\\text{ g of } \\text{N}_2$ combines with **$40\\text{ g of } \\text{O}_2$**.<br><br>\n    The masses of dioxygen combining with a fixed mass ($14\\text{ g}$) of dinitrogen are in the ratio:<br>\n    $$16 : 32 : 16 : 40 = \\mathbf{2 : 4 : 2 : 5} \\quad \\text{(or } 1 : 2 : 1 : 2.5 \\implies 2 : 4 : 2 : 5\\text{)}$$<br>\n    Since this is a simple whole number ratio, the data obeys the **Law of Multiple Proportions**.<br><br>\n    <i>Statement: \"When two elements combine to form two or more chemical compounds, then the masses of one of the elements which combine with a fixed mass of the other bear a simple whole number ratio to one another.\"</i><br><br>\n    <b>(b) Conversions:</b><br>\n    • **(i)** $1\\text{ km} = 10^3\\text{ m} = 10^3 \\times 10^3\\text{ mm} = \\mathbf{10^6\\text{ mm}}$.<br>\n    $$1\\text{ km} = 10^3\\text{ m} = 10^3 \\times 10^{12}\\text{ pm} = \\mathbf{10^{15}\\text{ pm}}$$<br>\n    • **(ii)** $1\\text{ mg} = 10^{-3}\\text{ g} = 10^{-3} \\times 10^{-3}\\text{ kg} = \\mathbf{10^{-6}\\text{ kg}}$.<br>\n    $$1\\text{ mg} = 10^{-3}\\text{ g} = 10^{-3} \\times 10^9\\text{ ng} = \\mathbf{10^6\\text{ ng}}$$<br>\n    • **(iii)** $1\\text{ mL} = \\mathbf{10^{-3}\\text{ L}}$.<br>\n    Since $1\\text{ L} = 1\\text{ dm}^3$, $1\\text{ mL} = \\mathbf{10^{-3}\\text{ dm}^3}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Fixing $14\\text{ g N}_2$, establishing whole-number ratio $2:4:2:5$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating the Law of Multiple Proportions accurately</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Correct unit conversions (i), (ii), and (iii)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q22')\">\n      <div class=\"q-num\">Question 1.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If the speed of light is $3.00 \\times 10^8\\text{ m s}^{-1}$, calculate the distance covered by light in $2.00\\text{ ns}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Speed of light $c = 3.00 \\times 10^8\\text{ m s}^{-1}$<br>\n    • Time $t = 2.00\\text{ ns} = 2.00 \\times 10^{-9}\\text{ s}$<br><br>\n    <b>Calculation:</b><br>\n    $$\\text{Distance } (d) = \\text{Speed } (c) \\times \\text{Time } (t)$$<br>\n    $$d = (3.00 \\times 10^8\\text{ m s}^{-1}) \\times (2.00 \\times 10^{-9}\\text{ s})$$<br>\n    $$d = 6.00 \\times 10^{-1}\\text{ m} = \\mathbf{0.600\\text{ m} = 60.0\\text{ cm}}$$<br><br>\n    $$\\mathbf{\\text{The distance covered by light in } 2.00\\text{ ns is } 0.600\\text{ m (or } 60.0\\text{ cm}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of nanoseconds $2.00\\text{ ns} = 2.00 \\times 10^{-9}\\text{ s}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating distance $d = c \\times t = 0.600\\text{ m}$ (3 sig figs)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q23 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q23\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q23')\">\n      <div class=\"q-num\">Question 1.23</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In a reaction: $\\text{A} + \\text{B}_2 \\longrightarrow \\text{AB}_2$<br>Identify the limiting reagent, if any, in the following reaction mixtures:<br>(i) $300\\text{ atoms of A} + 200\\text{ molecules of B}$<br>(ii) $2\\text{ mol A} + 3\\text{ mol B}$<br>(iii) $100\\text{ atoms of A} + 100\\text{ molecules of B}$<br>(iv) $5\\text{ mol A} + 2.5\\text{ mol B}$<br>(v) $2.5\\text{ mol A} + 5\\text{ mol B}$\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    From the reaction: $\\text{A} + \\text{B}_2 \\longrightarrow \\text{AB}_2$, the stoichiometric requirement is **$1\\text{ atom (or mole) of A}$ reacts with $1\\text{ molecule (or mole) of } \\text{B}_2$**.<br><br>\n    • **(i) $300\\text{ atoms of A} + 200\\text{ molecules of B}_2$:**<br>\n    $200\\text{ molecules of } \\text{B}_2$ react with only $200\\text{ atoms of A}$, leaving $100\\text{ atoms of A}$ unreacted.<br>\n    $$\\mathbf{\\text{B}_2 \\text{ is the limiting reagent.}}$$<br><br>\n    • **(ii) $2\\text{ mol A} + 3\\text{ mol B}_2$:**<br>\n    $2\\text{ mol of A}$ reacts with $2\\text{ mol of } \\text{B}_2$, leaving $1\\text{ mol of } \\text{B}_2$ in excess.<br>\n    $$\\mathbf{\\text{A is the limiting reagent.}}$$<br><br>\n    • **(iii) $100\\text{ atoms of A} + 100\\text{ molecules of B}_2$:**<br>\n    Both reactants are present in exact stoichiometric proportions. Both are completely consumed.<br>\n    $$\\mathbf{\\text{No limiting reagent (stoichiometric mixture).}}$$<br><br>\n    • **(iv) $5\\text{ mol A} + 2.5\\text{ mol B}_2$:**<br>\n    $2.5\\text{ mol of } \\text{B}_2$ requires only $2.5\\text{ mol of A}$, leaving $2.5\\text{ mol of A}$ unreacted.<br>\n    $$\\mathbf{\\text{B}_2 \\text{ is the limiting reagent.}}$$<br><br>\n    • **(v) $2.5\\text{ mol A} + 5\\text{ mol B}_2$:**<br>\n    $2.5\\text{ mol of A}$ requires $2.5\\text{ mol of } \\text{B}_2$, leaving $2.5\\text{ mol of } \\text{B}_2$ in excess.<br>\n    $$\\mathbf{\\text{A is the limiting reagent.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) $\\text{B}_2$ and (ii) $\\text{A}$ identified with reasoning</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Neither / stoichiometric mixture</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iv) $\\text{B}_2$ and (v) $\\text{A}$ identified with reasoning</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q24 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q24\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q24')\">\n      <div class=\"q-num\">Question 1.24</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Dinitrogen and dihydrogen react with each other to produce ammonia according to the following chemical equation:<br>$$\\text{N}_2(g) + 3\\text{H}_2(g) \\longrightarrow 2\\text{NH}_3(g)$$<br>(i) Calculate the mass of ammonia produced if $2.00 \\times 10^3\\text{ g}$ dinitrogen reacts with $1.00 \\times 10^3\\text{ g}$ of dihydrogen.<br>(ii) Will any of the two reactants remain unreacted?<br>(iii) If yes, which one and what would be its mass?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mass of $\\text{N}_2 = 2.00 \\times 10^3\\text{ g} = 2000\\text{ g}$<br>\n    • Mass of $\\text{H}_2 = 1.00 \\times 10^3\\text{ g} = 1000\\text{ g}$<br>\n    • Molar masses: $\\text{N}_2 = 28.02\\text{ g mol}^{-1}$, $\\text{H}_2 = 2.016\\text{ g mol}^{-1}$, $\\text{NH}_3 = 17.03\\text{ g mol}^{-1}$.<br><br>\n    <b>1. Determining initial moles of reactants:</b><br>\n    $$n(\\text{N}_2) = \\frac{2000\\text{ g}}{28.02\\text{ g mol}^{-1}} = \\mathbf{71.38\\text{ mol}}$$<br>\n    $$n(\\text{H}_2) = \\frac{1000\\text{ g}}{2.016\\text{ g mol}^{-1}} = \\mathbf{496.03\\text{ mol}}$$<br><br>\n    <b>2. Finding Limiting Reagent:</b><br>\n    From stoichiometry, $1\\text{ mol of } \\text{N}_2$ requires $3\\text{ moles of } \\text{H}_2$.<br>\n    Moles of $\\text{H}_2$ required to react with $71.38\\text{ mol of } \\text{N}_2$:<br>\n    $$n(\\text{H}_2)_{\\text{req}} = 3 \\times 71.38 = \\mathbf{214.14\\text{ mol}}$$<br>\n    Since we have $496.03\\text{ mol of } \\text{H}_2$ (far greater than $214.14\\text{ mol}$), **$\\text{N}_2$ is the limiting reagent** and $\\text{H}_2$ is in excess.<br><br>\n    <b>(i) Mass of Ammonia Produced:</b><br>\n    From equation: $1\\text{ mol } \\text{N}_2 \\to 2\\text{ mol } \\text{NH}_3$.<br>\n    $$n(\\text{NH}_3) = 2 \\times 71.38 = 142.76\\text{ mol}$$<br>\n    $$\\text{Mass of } \\text{NH}_3 = 142.76\\text{ mol} \\times 17.03\\text{ g mol}^{-1} = \\mathbf{2431.2\\text{ g} = 2.43 \\times 10^3\\text{ g} = 2.43\\text{ kg}}$$<br><br>\n    <b>(ii) Will any reactant remain unreacted?</b><br>\n    $$\\mathbf{\\text{Yes, dihydrogen (}\\text{H}_2\\text{) will remain unreacted.}}$$<br><br>\n    <b>(iii) Mass of unreacted dihydrogen:</b><br>\n    • Unreacted moles of $\\text{H}_2$: $496.03 - 214.14 = 281.89\\text{ mol}$.<br>\n    • Mass of remaining $\\text{H}_2$:<br>\n    $$\\text{Mass of unreacted } \\text{H}_2 = 281.89\\text{ mol} \\times 2.016\\text{ g mol}^{-1} = \\mathbf{568.29\\text{ g} \\approx 568\\text{ g} = 5.68 \\times 10^2\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; 2.43 \\times 10^3\\text{ g } \\text{NH}_3,\\; (ii)\\; \\text{Yes (}\\text{H}_2\\text{)},\\; (iii)\\; 568\\text{ g of } \\text{H}_2\\text{ remaining.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating moles of $\\text{N}_2$ and $\\text{H}_2$, and identifying $\\text{N}_2$ as limiting reagent</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Calculation of mass of $\\text{NH}_3$ produced $= 2.43 \\times 10^3\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Identifying $\\text{H}_2$ as unreacted reactant</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Calculation of mass of unreacted $\\text{H}_2 = 568\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q25 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q25\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q25')\">\n      <div class=\"q-num\">Question 1.25</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How are $0.50\\text{ mol } \\text{Na}_2\\text{CO}_3$ and $0.50\\text{ M } \\text{Na}_2\\text{CO}_3$ different?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Molar mass of sodium carbonate ($\\text{Na}_2\\text{CO}_3$) = $2(23.0) + 12.0 + 3(16.0) = \\mathbf{106\\text{ g mol}^{-1}}$.<br><br>\n    <b>1. $0.50\\text{ mol } \\text{Na}_2\\text{CO}_3$:</b><br>\n    • Represents an **amount of substance** (a definite mass / quantity of matter).<br>\n    • Mass of $0.50\\text{ mol}$: $\\text{Mass} = 0.50\\text{ mol} \\times 106\\text{ g mol}^{-1} = \\mathbf{53\\text{ g of } \\text{Na}_2\\text{CO}_3}$.<br>\n    • It is independent of the volume of solvent.<br><br>\n    <b>2. $0.50\\text{ M } \\text{Na}_2\\text{CO}_3$:</b><br>\n    • Represents a **molar concentration** of an aqueous solution.<br>\n    • It means that $0.50\\text{ mole } (53\\text{ g})$ of $\\text{Na}_2\\text{CO}_3$ is dissolved in enough water such that the **total volume of solution is exactly $1\\text{ litre}$** ($1000\\text{ mL}$).<br><br>\n    $$\\mathbf{\\text{Difference: } 0.50\\text{ mol is a mass (53 g), whereas } 0.50\\text{ M is a concentration (53 g per litre of solution).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of $0.50\\text{ mol}$ as amount of matter (53 g)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of $0.50\\text{ M}$ as concentration (0.50 mol/L of solution)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q26 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q26\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q26')\">\n      <div class=\"q-num\">Question 1.26</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If $10\\text{ volumes}$ of dihydrogen gas react with $5\\text{ volumes}$ of dioxygen gas, how many volumes of water vapour would be produced?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Balanced equation of combining gaseous volumes (Gay-Lussac's Law of Gaseous Volumes):<br>\n    $$2\\text{H}_2(g) + \\text{O}_2(g) \\longrightarrow 2\\text{H}_2\\text{O}(g)$$<br>\n    Under identical conditions of temperature and pressure:<br>\n    $$2\\text{ volumes of } \\text{H}_2 + 1\\text{ volume of } \\text{O}_2 \\longrightarrow 2\\text{ volumes of } \\text{H}_2\\text{O}(g)$$<br><br>\n    Given:<br>\n    • Volume of $\\text{H}_2 = 10\\text{ volumes}$<br>\n    • Volume of $\\text{O}_2 = 5\\text{ volumes}$<br><br>\n    Ratio check: $\\frac{10\\text{ volumes } \\text{H}_2}{5\\text{ volumes } \\text{O}_2} = \\frac{2}{1}$, which exactly matches the stoichiometric ratio (neither reactant is in excess).<br>\n    Therefore, the volume of water vapour produced is:<br>\n    $$\\text{Volume of } \\text{H}_2\\text{O}(g) = 10\\text{ volumes}$$<br><br>\n    $$\\mathbf{\\text{Exactly } 10\\text{ volumes of water vapour will be produced.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Gay-Lussac reaction volume ratio $2 : 1 : 2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Deducing that 10 volumes of water vapour are produced</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q27 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q27\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q27')\">\n      <div class=\"q-num\">Question 1.27</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Convert the following into basic units:<br>(i) $28.7\\text{ pm}$<br>(ii) $15.15\\text{ pm}$<br>(iii) $25365\\text{ mg}$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Basic SI unit of length is **metre** ($\\text{m}$), and basic SI unit of mass is **kilogram** ($\\text{kg}$).<br><br>\n    • **(i) $28.7\\text{ pm}$:**<br>\n    Since $1\\text{ pm} = 10^{-12}\\text{ m}$:<br>\n    $$28.7\\text{ pm} = 28.7 \\times 10^{-12}\\text{ m} = \\mathbf{2.87 \\times 10^{-11}\\text{ m}}$$<br><br>\n    • **(ii) $15.15\\text{ pm}$:**<br>\n    $$15.15\\text{ pm} = 15.15 \\times 10^{-12}\\text{ m} = \\mathbf{1.515 \\times 10^{-11}\\text{ m}}$$<br><br>\n    • **(iii) $25365\\text{ mg}$:**<br>\n    Since $1\\text{ mg} = 10^{-3}\\text{ g} = 10^{-6}\\text{ kg}$:<br>\n    $$25365\\text{ mg} = 25365 \\times 10^{-6}\\text{ kg} = \\mathbf{2.5365 \\times 10^{-2}\\text{ kg} = 0.025365\\text{ kg}}$$<br><br>\n    $$\\mathbf{\\text{Results: } (i)\\; 2.87 \\times 10^{-11}\\text{ m},\\; (ii)\\; 1.515 \\times 10^{-11}\\text{ m},\\; (iii)\\; 2.5365 \\times 10^{-2}\\text{ kg.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Conversion to metres: $2.87 \\times 10^{-11}\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Conversion to metres: $1.515 \\times 10^{-11}\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Conversion to kilograms: $2.5365 \\times 10^{-2}\\text{ kg}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q28 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q28\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q28')\">\n      <div class=\"q-num\">Question 1.28</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which one of the following will have the largest number of atoms?<br>(i) $1\\text{ g Au }(s)$<br>(ii) $1\\text{ g Na }(s)$<br>(iii) $1\\text{ g Li }(s)$<br>(iv) $1\\text{ g of } \\text{Cl}_2(g)$\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>General Formula:</b><br>\n    $$\\text{Number of atoms} = \\left(\\frac{\\text{Mass}}{\\text{Molar mass}}\\right) \\times N_A \\times (\\text{Atomicity})$$<br><br>\n    • **(i) $1\\text{ g of Au}(s)$** (Molar mass $\\text{Au} = 197\\text{ g mol}^{-1}$):<br>\n    $$\\text{Atoms} = \\frac{1}{197} \\times N_A = \\mathbf{0.00508 \\times N_A\\text{ atoms}}$$<br><br>\n    • **(ii) $1\\text{ g of Na}(s)$** (Molar mass $\\text{Na} = 23\\text{ g mol}^{-1}$):<br>\n    $$\\text{Atoms} = \\frac{1}{23} \\times N_A = \\mathbf{0.04348 \\times N_A\\text{ atoms}}$$<br><br>\n    • **(iii) $1\\text{ g of Li}(s)$** (Molar mass $\\text{Li} = 7\\text{ g mol}^{-1}$):<br>\n    $$\\text{Atoms} = \\frac{1}{7} \\times N_A = \\mathbf{0.14286 \\times N_A\\text{ atoms}}$$<br><br>\n    • **(iv) $1\\text{ g of } \\text{Cl}_2(g)$** (Molar mass $\\text{Cl}_2 = 71\\text{ g mol}^{-1}$, Atomicity = 2):<br>\n    $$\\text{Atoms} = \\frac{1}{71} \\times N_A \\times 2 = \\frac{2}{71} \\times N_A = \\mathbf{0.02817 \\times N_A\\text{ atoms}}$$<br><br>\n    Comparing the multipliers: $0.14286 > 0.04348 > 0.02817 > 0.00508$.<br><br>\n    $$\\mathbf{1\\text{ g of Li}(s) \\text{ has the largest number of atoms (}\\approx 8.60 \\times 10^{22}\\text{ atoms).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up mole-to-atom expressions with atomicities for all 4 options</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparing values and concluding $1\\text{ g Li}$ has largest atom count</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q29 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q29\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q29')\">\n      <div class=\"q-num\">Question 1.29</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the molarity of a solution of ethanol in water in which the mole fraction of ethanol is $0.040$ (assume the density of water to be $1.00\\text{ g mL}^{-1}$).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mole fraction of ethanol $\\chi_{\\text{ethanol}} = 0.040$<br>\n    • Mole fraction of water $\\chi_{\\text{water}} = 1 - 0.040 = 0.960$<br>\n    • Density of water $= 1.00\\text{ g mL}^{-1} = 1.00\\text{ kg L}^{-1}$<br><br>\n    <b>1. Basis: $1\\text{ litre}$ of water (solvent):</b><br>\n    • Mass of $1000\\text{ mL}$ water $= 1000\\text{ g}$.<br>\n    • Moles of water ($n_{\\text{water}}$):<br>\n    $$n_{\\text{water}} = \\frac{1000\\text{ g}}{18.016\\text{ g mol}^{-1}} = \\mathbf{55.51\\text{ mol}}$$<br><br>\n    <b>2. Moles of ethanol ($n_{\\text{ethanol}}$):</b><br>\n    From definition of mole fraction:<br>\n    $$\\chi_{\\text{ethanol}} = \\frac{n_{\\text{ethanol}}}{n_{\\text{ethanol}} + n_{\\text{water}}} = 0.040$$<br>\n    $$n_{\\text{ethanol}} = 0.040 \\times (n_{\\text{ethanol}} + 55.51)$$<br>\n    $$n_{\\text{ethanol}} - 0.040\\, n_{\\text{ethanol}} = 0.040 \\times 55.51$$<br>\n    $$0.960\\, n_{\\text{ethanol}} = 2.2204 \\implies n_{\\text{ethanol}} = \\frac{2.2204}{0.960} = \\mathbf{2.313\\text{ mol}}$$<br><br>\n    <b>3. Molarity calculation:</b><br>\n    Since this amount ($2.313\\text{ mol}$) of ethanol is dissolved in approximately $1\\text{ litre}$ of solvent water:<br>\n    $$\\text{Molarity} \\approx \\mathbf{2.31\\text{ mol L}^{-1} = 2.31\\text{ M}}$$<br><br>\n    $$\\mathbf{\\text{The molarity of the ethanol solution is } 2.31\\text{ M.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Determining moles of water in 1 L $= 55.5\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up mole fraction relation and solving for $n_{\\text{ethanol}} = 2.31\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final molarity statement $2.31\\text{ mol L}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q30 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q30\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q30')\">\n      <div class=\"q-num\">Question 1.30</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What will be the mass of one $^{12}\\text{C}$ atom in $\\text{g}$?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    By definition of Avogadro's constant and molar mass:<br>\n    • $1\\text{ mole of } ^{12}\\text{C atoms}$ has a mass of exactly $12.000\\text{ g}$.<br>\n    • $1\\text{ mole}$ contains $N_A = 6.02214 \\times 10^{23}\\text{ atoms}$.<br><br>\n    <b>Calculation:</b><br>\n    $$\\text{Mass of } 1\\text{ atom of } ^{12}\\text{C} = \\frac{\\text{Molar mass}}{N_A}$$<br>\n    $$\\text{Mass} = \\frac{12.000\\text{ g}}{6.02214 \\times 10^{23}} = \\mathbf{1.992648 \\times 10^{-23}\\text{ g} \\approx 1.9927 \\times 10^{-23}\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{The mass of one } ^{12}\\text{C atom is } 1.9927 \\times 10^{-23}\\text{ g.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Relating mass of 1 mole to Avogadro constant</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation yielding $1.9927 \\times 10^{-23}\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q31 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q31\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q31')\">\n      <div class=\"q-num\">Question 1.31</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How many significant figures should be present in the answer of the following calculations?<br>(i) $\\frac{0.02856 \\times 298.15 \\times 0.112}{0.5785}$<br>(ii) $5 \\times 5.364$<br>(iii) $0.0125 + 0.7864 + 0.0215$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) $\\frac{0.02856 \\times 298.15 \\times 0.112}{0.5785}$:</b><br>\n    • In multiplication and division, the result must retain as many significant figures as are present in the measurement with the **least number of significant figures**.<br>\n    • Number of sig figs: $0.02856$ (4), $298.15$ (5), $0.112$ (3), $0.5785$ (4).<br>\n    • The term with least significant figures is $0.112$ with **$3$ significant figures**.<br>\n    • **Answer: $3$ significant figures.**<br><br>\n    <b>(ii) $5 \\times 5.364$:</b><br>\n    • The number $5$ is an exact whole integer (exact count) having infinite significant figures ($5.000\\dots$).<br>\n    • The measured quantity is $5.364$, which has **$4$ significant figures**.<br>\n    • **Answer: $4$ significant figures.**<br><br>\n    <b>(iii) $0.0125 + 0.7864 + 0.0215$:</b><br>\n    • In addition and subtraction, the result cannot have more digits to the right of the decimal point than any of the original numbers.<br>\n    • All three terms have $4$ decimal places.<br>\n    • Sum: $0.0125 + 0.7864 + 0.0215 = 0.8204$.<br>\n    • Number of significant figures in $0.8204$ is **$4$**.<br>\n    • **Answer: $4$ significant figures.**<br><br>\n    $$\\mathbf{\\text{Results: } (i)\\; 3,\\; (ii)\\; 4,\\; (iii)\\; 4.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) 3 significant figures (governed by 0.112)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) 4 significant figures (5 is an exact number)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) 4 significant figures (sum $= 0.8204$)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q32 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q32\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q32')\">\n      <div class=\"q-num\">Question 1.32</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Use the data given in the following table to calculate the molar mass of naturally occurring argon isotopes:<br>• $^{36}\\text{Ar}$: Isotopic molar mass = $35.96755\\text{ g mol}^{-1}$, Abundance = $0.337\\%$<br>• $^{38}\\text{Ar}$: Isotopic molar mass = $37.96272\\text{ g mol}^{-1}$, Abundance = $0.063\\%$<br>• $^{40}\\text{Ar}$: Isotopic molar mass = $39.9624\\text{ g mol}^{-1}$, Abundance = $99.600\\%$\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Formula for Molar Mass of Isotopic Mixture:</b><br>\n    $$M(\\text{Ar}) = \\sum (\\text{Fractional abundance} \\times \\text{Molar mass})$$<br><br>\n    $$M(\\text{Ar}) = \\left(\\frac{0.337}{100} \\times 35.96755\\right) + \\left(\\frac{0.063}{100} \\times 37.96272\\right) + \\left(\\frac{99.600}{100} \\times 39.9624\\right)$$<br>\n    $$M(\\text{Ar}) = (0.00337 \\times 35.96755) + (0.00063 \\times 37.96272) + (0.99600 \\times 39.9624)$$<br>\n    $$M(\\text{Ar}) = 0.12121 + 0.02392 + 39.80255$$<br>\n    $$M(\\text{Ar}) = \\mathbf{39.94768\\text{ g mol}^{-1} \\approx 39.948\\text{ g mol}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The molar mass of naturally occurring argon is } 39.948\\text{ g mol}^{-1}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Formulation of fractional abundance weighted sum</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation yielding $39.948\\text{ g mol}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q33 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q33\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q33')\">\n      <div class=\"q-num\">Question 1.33</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the number of atoms in each of the following:<br>(i) $52\\text{ moles of Ar}$<br>(ii) $52\\text{ u of He}$<br>(iii) $52\\text{ g of He}$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) $52\\text{ moles of Ar}$ (monoatomic gas):</b><br>\n    $$1\\text{ mole contains } 6.022 \\times 10^{23}\\text{ atoms}$$<br>\n    $$\\text{Atoms} = 52 \\times (6.022 \\times 10^{23}) = \\mathbf{3.131 \\times 10^{25}\\text{ atoms of Ar}}$$<br><br>\n    <b>(ii) $52\\text{ u of He}$ (atomic mass unit):</b><br>\n    • Atomic mass of $1\\text{ atom of He} = 4\\text{ u}$.<br>\n    $$\\text{Number of atoms} = \\frac{\\text{Total mass in u}}{\\text{Mass of 1 atom in u}} = \\frac{52\\text{ u}}{4\\text{ u}} = \\mathbf{13\\text{ atoms of He}}$$<br><br>\n    <b>(iii) $52\\text{ g of He}$ (gram atomic mass):</b><br>\n    • Molar mass of $\\text{He} = 4.0\\text{ g mol}^{-1}$.<br>\n    • Moles of $\\text{He} = \\frac{52\\text{ g}}{4.0\\text{ g mol}^{-1}} = 13\\text{ moles}$.<br>\n    $$\\text{Number of atoms} = 13 \\times (6.022 \\times 10^{23}) = \\mathbf{7.8286 \\times 10^{24}\\text{ atoms of He} \\approx 7.83 \\times 10^{24}\\text{ atoms}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; 3.131 \\times 10^{25}\\text{ atoms},\\; (ii)\\; 13\\text{ atoms},\\; (iii)\\; 7.83 \\times 10^{24}\\text{ atoms.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) $52\\text{ mol Ar} = 3.131 \\times 10^{25}$ atoms</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) $52\\text{ u He} = 52/4 = 13$ atoms</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) $52\\text{ g He} = 13 \\times N_A = 7.83 \\times 10^{24}$ atoms</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q34 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q34\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q34')\">\n      <div class=\"q-num\">Question 1.34</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A welding fuel gas contains carbon and hydrogen only. Burning a small sample of it in oxygen gives $3.38\\text{ g}$ carbon dioxide, $0.690\\text{ g}$ of water and no other products. A volume of $10.0\\text{ L}$ (measured at S.T.P.) of this welding gas is found to weigh $11.6\\text{ g}$. Calculate:<br>(i) empirical formula,<br>(ii) molar mass of the gas, and<br>(iii) molecular formula.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data from combustion:<br>\n    • Mass of $\\text{CO}_2$ produced = $3.38\\text{ g}$<br>\n    • Mass of $\\text{H}_2\\text{O}$ produced = $0.690\\text{ g}$<br><br>\n    <b>1. (i) Empirical Formula:</b><br>\n    • Mass of Carbon in $3.38\\text{ g } \\text{CO}_2$:<br>\n    $$m_C = 3.38\\text{ g} \\times \\frac{12.011\\text{ g C}}{44.01\\text{ g } \\text{CO}_2} = \\mathbf{0.9224\\text{ g C}}$$<br>\n    • Mass of Hydrogen in $0.690\\text{ g } \\text{H}_2\\text{O}$:<br>\n    $$m_H = 0.690\\text{ g} \\times \\frac{2.016\\text{ g H}}{18.016\\text{ g } \\text{H}_2\\text{O}} = \\mathbf{0.0772\\text{ g H}}$$<br>\n    • Moles of Carbon: $n_C = \\frac{0.9224}{12.011} = 0.0768\\text{ mol}$.<br>\n    • Moles of Hydrogen: $n_H = \\frac{0.0772}{1.008} = 0.0766\\text{ mol}$.<br>\n    • Molar ratio: $n_C : n_H = \\frac{0.0768}{0.0766} : \\frac{0.0766}{0.0766} = \\mathbf{1 : 1}$.<br>\n    $$\\mathbf{\\text{Empirical formula of the gas is } \\text{CH.}}$$<br><br>\n    <b>2. (ii) Molar Mass of the Gas:</b><br>\n    At S.T.P. ($1\\text{ atm}, 273.15\\text{ K}$), $22.4\\text{ L}$ is occupied by $1\\text{ mole}$ of an ideal gas:<br>\n    • $10.0\\text{ L}$ weighs $11.6\\text{ g}$.<br>\n    $$\\text{Molar mass } (M) = \\frac{11.6\\text{ g}}{10.0\\text{ L}} \\times 22.4\\text{ L mol}^{-1} = 1.16 \\times 22.4 = \\mathbf{25.984\\text{ g mol}^{-1} \\approx 26.0\\text{ g mol}^{-1}}$$<br><br>\n    <b>3. (iii) Molecular Formula:</b><br>\n    • Empirical formula mass of $\\text{CH} = 12.01 + 1.008 = 13.018\\text{ g mol}^{-1}$.<br>\n    • Whole number ratio $n = \\frac{\\text{Molar mass}}{\\text{Empirical formula mass}} = \\frac{26.0}{13.018} = \\mathbf{2}$.<br>\n    $$\\text{Molecular formula} = (\\text{CH})_2 = \\mathbf{\\text{C}_2\\text{H}_2 \\quad \\text{(Acetylene / Ethyne)}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } (i)\\; \\text{CH},\\; (ii)\\; 26.0\\text{ g mol}^{-1},\\; (iii)\\; \\text{C}_2\\text{H}_2.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Elemental mass and mole calculations yielding empirical formula $\\text{CH}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) STP molar volume relation yielding molar mass $= 26.0\\text{ g mol}^{-1}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Deducing $n = 2$ and molecular formula $\\text{C}_2\\text{H}_2$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q35 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q35\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q35')\">\n      <div class=\"q-num\">Question 1.35</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calcium carbonate reacts with aqueous $\\text{HCl}$ to give $\\text{CaCl}_2$ and $\\text{CO}_2$ according to the reaction:<br>$$\\text{CaCO}_3(s) + 2\\text{HCl}(aq) \\longrightarrow \\text{CaCl}_2(aq) + \\text{CO}_2(g) + \\text{H}_2\\text{O}(l)$$<br>What mass of $\\text{CaCO}_3$ is required to react completely with $25\\text{ mL}$ of $0.75\\text{ M HCl}$?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Molarity of $\\text{HCl}$ = $0.75\\text{ M} = 0.75\\text{ mol L}^{-1}$<br>\n    • Volume of $\\text{HCl} = 25\\text{ mL} = 0.025\\text{ L}$<br>\n    • Molar mass of $\\text{CaCO}_3 = 40.08 + 12.01 + 3(16.00) = \\mathbf{100.09\\text{ g mol}^{-1} \\approx 100\\text{ g mol}^{-1}}$<br><br>\n    <b>1. Moles of $\\text{HCl}$ available:</b><br>\n    $$n(\\text{HCl}) = M \\times V = (0.75\\text{ mol L}^{-1}) \\times (0.025\\text{ L}) = \\mathbf{0.01875\\text{ mol}}$$<br><br>\n    <b>2. Stoichiometry:</b><br>\n    From the balanced chemical equation, $2\\text{ moles of } \\text{HCl}$ react completely with $1\\text{ mole of } \\text{CaCO}_3$.<br>\n    $$n(\\text{CaCO}_3) = \\frac{n(\\text{HCl})}{2} = \\frac{0.01875\\text{ mol}}{2} = \\mathbf{0.009375\\text{ mol}}$$<br><br>\n    <b>3. Required Mass of $\\text{CaCO}_3$:</b><br>\n    $$\\text{Mass} = n(\\text{CaCO}_3) \\times \\text{Molar mass} = (0.009375\\text{ mol}) \\times (100.09\\text{ g mol}^{-1})$$<br>\n    $$\\text{Mass} = 0.9383\\text{ g} \\approx \\mathbf{0.94\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{The mass of } \\text{CaCO}_3 \\text{ required is approximately } 0.94\\text{ g (or } 0.938\\text{ g}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating moles of $\\text{HCl} = 0.01875\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stoichiometric mole conversion $n(\\text{CaCO}_3) = n(\\text{HCl})/2 = 0.009375\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating required mass $= 0.938\\text{ g} \\approx 0.94\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch1-q36 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch1-q36\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch1-q36')\">\n      <div class=\"q-num\">Question 1.36</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Chlorine is prepared in the laboratory by treating manganese dioxide ($\\text{MnO}_2$) with aqueous hydrochloric acid according to the reaction:<br>$$4\\text{HCl}(aq) + \\text{MnO}_2(s) \\longrightarrow 2\\text{H}_2\\text{O}(l) + \\text{MnCl}_2(aq) + \\text{Cl}_2(g)$$<br>How many grams of $\\text{HCl}$ react with $5.0\\text{ g}$ of manganese dioxide? (Atomic mass of $\\text{Mn} = 54.94\\text{ u}$, $\\text{O} = 16.00\\text{ u}$, $\\text{Cl} = 35.45\\text{ u}$, $\\text{H} = 1.008\\text{ u}$).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mass of $\\text{MnO}_2 = 5.0\\text{ g}$<br>\n    • Molar mass of $\\text{MnO}_2 = 54.94 + 2(16.00) = 54.94 + 32.00 = \\mathbf{86.94\\text{ g mol}^{-1}}$<br>\n    • Molar mass of $\\text{HCl} = 1.008 + 35.45 = \\mathbf{36.46\\text{ g mol}^{-1}}$<br><br>\n    <b>1. Moles of $\\text{MnO}_2$:</b><br>\n    $$n(\\text{MnO}_2) = \\frac{5.0\\text{ g}}{86.94\\text{ g mol}^{-1}} = \\mathbf{0.05751\\text{ mol}}$$<br><br>\n    <b>2. Stoichiometry:</b><br>\n    From the balanced chemical equation, $1\\text{ mole of } \\text{MnO}_2$ reacts with $4\\text{ moles of } \\text{HCl}$.<br>\n    $$n(\\text{HCl})_{\\text{required}} = 4 \\times n(\\text{MnO}_2) = 4 \\times 0.05751 = \\mathbf{0.23004\\text{ mol}}$$<br><br>\n    <b>3. Mass of $\\text{HCl}$ required:</b><br>\n    $$\\text{Mass of } \\text{HCl} = n(\\text{HCl}) \\times \\text{Molar mass of } \\text{HCl}$$<br>\n    $$\\text{Mass of } \\text{HCl} = (0.23004\\text{ mol}) \\times (36.46\\text{ g mol}^{-1}) = \\mathbf{8.387\\text{ g} \\approx 8.40\\text{ g}}$$<br><br>\n    $$\\mathbf{\\text{Approximately } 8.40\\text{ g of } \\text{HCl} \\text{ reacts with } 5.0\\text{ g of manganese dioxide.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating molar mass of $\\text{MnO}_2 = 86.94\\text{ g/mol}$ and moles $= 0.0575\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying 4:1 stoichiometric ratio: $n(\\text{HCl}) = 0.230\\text{ mol}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating mass of $\\text{HCl} = 0.230 \\times 36.46 = 8.40\\text{ g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <a href=\"../ncert-solutions-class-11-chemistry.html\" class=\"ch-nav-btn prev\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; text-decoration:none; color:#334155;\">← Class 11 Chemistry Hub</a>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#059669; color:white; font-weight:700; cursor:pointer;\">Next: Chapter 2 (Structure of Atom) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[2] = "<section class=\"chapter-section\" id=\"c11c-ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Chemistry &bull; Chapter 2</div>\n      <h2>Structure of Atom</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 67 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:white; padding:20px; border-radius:12px; border:1px solid #e2e8f0; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 2v2M12 20v2M2 12h2M20 12h2\"/></svg>\n      Quantum Architecture: Bohr Hydrogen Spectral Series &amp; Orbital Quantum Subshells\n    </h3>\n    <svg viewBox=\"0 0 780 250\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Panel 1: Bohr Energy Level Ladder & Spectral Series Transitions -->\n      <rect x=\"15\" y=\"15\" width=\"410\" height=\"220\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"30\" y=\"36\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#0f172a\">1. Hydrogen Energy Levels &amp; Spectral Transitions ($E_n = -13.6/n^2\\text{ eV}$):</text>\n\n      <!-- Energy Levels (Lines) -->\n      <!-- n = 1 -->\n      <line x1=\"40\" y1=\"205\" x2=\"400\" y2=\"205\" stroke=\"#047857\" stroke-width=\"2.2\"/>\n      <text x=\"405\" y=\"209\" font-size=\"9\" font-weight=\"bold\" fill=\"#047857\">n=1 (-13.6 eV)</text>\n\n      <!-- n = 2 -->\n      <line x1=\"40\" y1=\"145\" x2=\"400\" y2=\"145\" stroke=\"#2563eb\" stroke-width=\"1.8\"/>\n      <text x=\"405\" y=\"149\" font-size=\"9\" font-weight=\"bold\" fill=\"#2563eb\">n=2 (-3.4 eV)</text>\n\n      <!-- n = 3 -->\n      <line x1=\"40\" y1=\"105\" x2=\"400\" y2=\"105\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n      <text x=\"405\" y=\"109\" font-size=\"9\" font-weight=\"bold\" fill=\"#d97706\">n=3 (-1.51 eV)</text>\n\n      <!-- n = 4 -->\n      <line x1=\"40\" y1=\"78\" x2=\"400\" y2=\"78\" stroke=\"#9333ea\" stroke-width=\"1.2\"/>\n      <text x=\"405\" y=\"82\" font-size=\"8.5\" fill=\"#9333ea\">n=4 (-0.85 eV)</text>\n\n      <!-- n = 5 & inf -->\n      <line x1=\"40\" y1=\"60\" x2=\"400\" y2=\"60\" stroke=\"#64748b\" stroke-width=\"1\"/>\n      <line x1=\"40\" y1=\"48\" x2=\"400\" y2=\"48\" stroke=\"#94a3b8\" stroke-dasharray=\"2,2\"/>\n      <text x=\"405\" y=\"52\" font-size=\"8\" fill=\"#64748b\">n=&infin; (0.0 eV)</text>\n\n      <!-- Series Transitions (Downward Arrows) -->\n      <!-- Lyman Series (ends at n=1) UV -->\n      <line x1=\"75\" y1=\"145\" x2=\"75\" y2=\"205\" stroke=\"#059669\" stroke-width=\"2\" marker-end=\"url(#arrow)\"/>\n      <line x1=\"95\" y1=\"105\" x2=\"95\" y2=\"205\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <line x1=\"115\" y1=\"78\" x2=\"115\" y2=\"205\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <rect x=\"65\" y=\"215\" width=\"65\" height=\"15\" rx=\"3\" fill=\"#ecfdf5\" stroke=\"#059669\"/>\n      <text x=\"70\" y=\"226\" font-size=\"8\" font-weight=\"bold\" fill=\"#065f46\">Lyman (UV)</text>\n\n      <!-- Balmer Series (ends at n=2) Visible -->\n      <line x1=\"180\" y1=\"105\" x2=\"180\" y2=\"145\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <line x1=\"200\" y1=\"78\" x2=\"200\" y2=\"145\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <line x1=\"220\" y1=\"60\" x2=\"220\" y2=\"145\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <rect x=\"175\" y=\"153\" width=\"75\" height=\"15\" rx=\"3\" fill=\"#eff6ff\" stroke=\"#3b82f6\"/>\n      <text x=\"180\" y=\"164\" font-size=\"8\" font-weight=\"bold\" fill=\"#1e40af\">Balmer (Vis)</text>\n\n      <!-- Paschen Series (ends at n=3) IR -->\n      <line x1=\"285\" y1=\"78\" x2=\"285\" y2=\"105\" stroke=\"#d97706\" stroke-width=\"1.8\"/>\n      <line x1=\"305\" y1=\"60\" x2=\"305\" y2=\"105\" stroke=\"#d97706\" stroke-width=\"1.8\"/>\n      <rect x=\"275\" y=\"112\" width=\"75\" height=\"15\" rx=\"3\" fill=\"#fffbeb\" stroke=\"#f59e0b\"/>\n      <text x=\"280\" y=\"123\" font-size=\"8\" font-weight=\"bold\" fill=\"#92400e\">Paschen (IR)</text>\n\n      <!-- Brackett & Pfund -->\n      <line x1=\"365\" y1=\"60\" x2=\"365\" y2=\"78\" stroke=\"#9333ea\" stroke-width=\"1.8\"/>\n      <rect x=\"355\" y=\"85\" width=\"45\" height=\"13\" rx=\"2\" fill=\"#faf5ff\" stroke=\"#c084fc\"/>\n      <text x=\"358\" y=\"94\" font-size=\"7.5\" fill=\"#6b21a8\">Brackett</text>\n\n      <!-- Panel 2: Quantum Numbers & Aufbau Orbital Energy Rules -->\n      <rect x=\"440\" y=\"15\" width=\"325\" height=\"220\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"455\" y=\"36\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#0f172a\">2. Quantum Numbers &amp; Orbital Fill Rules:</text>\n\n      <!-- 4 Quantum Numbers Table Box -->\n      <rect x=\"455\" y=\"48\" width=\"295\" height=\"92\" rx=\"5\" fill=\"#fff\" stroke=\"#e2e8f0\"/>\n      <text x=\"465\" y=\"65\" font-size=\"9\" font-weight=\"bold\" fill=\"#0f172a\">&bull; Principal (n = 1,2,3...): Shell &amp; Size</text>\n      <text x=\"465\" y=\"83\" font-size=\"9\" font-weight=\"bold\" fill=\"#2563eb\">&bull; Azimuthal (l = 0 to n-1): Shape (s, p, d, f)</text>\n      <text x=\"465\" y=\"101\" font-size=\"9\" font-weight=\"bold\" fill=\"#059669\">&bull; Magnetic (m_l = -l to +l): Orientation (2l+1)</text>\n      <text x=\"465\" y=\"119\" font-size=\"9\" font-weight=\"bold\" fill=\"#d97706\">&bull; Spin (m_s = &plusmn;1/2): Electron Spin Direction</text>\n      <text x=\"465\" y=\"134\" font-size=\"8\" fill=\"#64748b\">Max e&macr; per shell = 2n&sup2; | Max e&macr; per orbital = 2</text>\n\n      <!-- Rules Box: Aufbau + Pauli + Hund -->\n      <rect x=\"455\" y=\"148\" width=\"295\" height=\"78\" rx=\"5\" fill=\"#ecfdf5\" stroke=\"#a7f3d0\"/>\n      <text x=\"465\" y=\"165\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#065f46\">Aufbau Principle (n + l rule):</text>\n      <text x=\"465\" y=\"179\" font-size=\"7.8\" fill=\"#334155\">Orbitals filled in order of increasing (n + l) energy.</text>\n      <text x=\"465\" y=\"194\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#065f46\">Pauli &amp; Hund&#39;s Rule:</text>\n      <text x=\"465\" y=\"208\" font-size=\"7.8\" fill=\"#334155\">No 2 e&macr; same 4 QNs; degenerate orbitals singly filled first with parallel spins.</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 2.1 to 2.67: Subatomic Discovery, Planck's Quantum Theory, Photoelectric Effect, Bohr Model, Hydrogen Spectra, de Broglie Dual Nature, Heisenberg Uncertainty, Quantum Numbers &amp; Electronic Configurations</div>\n\n  <!-- c11c-ch2-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q1')\">\n      <div class=\"q-num\">Question 2.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        (i) Calculate the number of electrons which will together weigh one gram.<br>\n   (ii) Calculate the mass and charge of one mole of electrons.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) Number of electrons that weigh $1\\text{ g}$ ($10^{-3}\\text{ kg}$):</b><br>\n    Mass of a single electron $m_e = 9.10938 \\times 10^{-31}\\text{ kg} = 9.10938 \\times 10^{-28}\\text{ g}$.<br>\n    $$\\text{Number of electrons} = \\frac{1\\text{ g}}{9.10938 \\times 10^{-28}\\text{ g}} = \\mathbf{1.0978 \\times 10^{27}\\text{ electrons} \\approx 1.098 \\times 10^{27}\\text{ electrons}}$$<br><br>\n    <b>(ii) Mass and charge of one mole of electrons:</b><br>\n    Avogadro constant $N_A = 6.02214 \\times 10^{23}\\text{ mol}^{-1}$.<br><br>\n    • **Mass of 1 mole of electrons:**<br>\n    $$\\text{Mass} = N_A \\times m_e = (6.02214 \\times 10^{23}) \\times (9.10938 \\times 10^{-31}\\text{ kg})$$<br>\n    $$\\text{Mass} = 5.4858 \\times 10^{-7}\\text{ kg} = \\mathbf{5.486 \\times 10^{-4}\\text{ g} \\approx 0.5486\\text{ mg}}$$<br><br>\n    • **Charge on 1 mole of electrons (Faraday constant $F$):**<br>\n    Charge on one electron $e = 1.6022 \\times 10^{-19}\\text{ C}$.<br>\n    $$\\text{Total Charge} = N_A \\times e = (6.02214 \\times 10^{23}) \\times (1.6022 \\times 10^{-19}\\text{ C})$$<br>\n    $$\\text{Total Charge} = \\mathbf{96485.3\\text{ C} \\approx 9.649 \\times 10^4\\text{ C (or 1 Faraday)}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (i) } 1.098 \\times 10^{27}\\text{ electrons; (ii) Mass } = 5.486 \\times 10^{-7}\\text{ kg},\\; \\text{Charge } = 9.649 \\times 10^4\\text{ C.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Evaluating number of electrons weighing 1 g = 1.098 x 10^27</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Calculating mass of 1 mole of electrons = 5.486 x 10^-7 kg (0.549 mg)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Calculating total charge on 1 mole of electrons = 96485 C</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q2')\">\n      <div class=\"q-num\">Question 2.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        (i) Calculate the total number of electrons present in one mole of methane.<br>\n   (ii) Find (a) the total number and (b) the total mass of neutrons in $7\\text{ mg}$ of $^{14}\\text{C}$. (Assume that mass of a neutron $= 1.675 \\times 10^{-27}\\text{ kg}$).<br>\n   (iii) Find (a) the total number and (b) the total mass of protons in $34\\text{ mg}$ of $\\text{NH}_3$ at STP. Will the answer change if the temperature and pressure are changed?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) Total number of electrons in 1 mole of methane ($\\text{CH}_4$):</b><br>\n    $1\\text{ molecule of } \\text{CH}_4$ has $6\\text{ (from C)} + 4 \\times 1\\text{ (from H)} = 10\\text{ electrons}$.<br>\n    In $1\\text{ mole of } \\text{CH}_4$:<br>\n    $$\\text{Total electrons} = 10 \\times N_A = 10 \\times 6.022 \\times 10^{23} = \\mathbf{6.022 \\times 10^{24}\\text{ electrons}}$$<br><br>\n    <b>(ii) Neutrons in $7\\text{ mg}$ of $^{14}\\text{C}$ ($Z=6, A=14$):</b><br>\n    Number of neutrons per $^{14}\\text{C}$ atom $= 14 - 6 = 8\\text{ neutrons}$.<br>\n    $$\\text{Moles of } ^{14}\\text{C} = \\frac{7 \\times 10^{-3}\\text{ g}}{14\\text{ g mol}^{-1}} = 0.5 \\times 10^{-3}\\text{ mol} = 5 \\times 10^{-4}\\text{ mol}$$<br>\n    Number of $^{14}\\text{C}$ atoms $= 5 \\times 10^{-4} \\times 6.022 \\times 10^{23} = 3.011 \\times 10^{20}\\text{ atoms}$.<br>\n    (a) Total neutrons $= 8 \\times 3.011 \\times 10^{20} = \\mathbf{2.4088 \\times 10^{21}\\text{ neutrons}}$<br>\n    (b) Total mass $= 2.4088 \\times 10^{21} \\times 1.675 \\times 10^{-27}\\text{ kg} = \\mathbf{4.035 \\times 10^{-6}\\text{ kg} = 4.035\\text{ mg}}$<br><br>\n    <b>(iii) Protons in $34\\text{ mg}$ of $\\text{NH}_3$:</b><br>\n    Molar mass of $\\text{NH}_3 = 14 + 3(1) = 17\\text{ g mol}^{-1}$.<br>\n    Protons per molecule $= 7\\text{ (N)} + 3\\text{ (H)} = 10\\text{ protons}$.<br>\n    $$\\text{Moles of } \\text{NH}_3 = \\frac{34 \\times 10^{-3}\\text{ g}}{17\\text{ g mol}^{-1}} = 2 \\times 10^{-3}\\text{ mol}$$<br>\n    (a) Total protons $= 10 \\times (2 \\times 10^{-3} \\times 6.022 \\times 10^{23}) = \\mathbf{1.2044 \\times 10^{22}\\text{ protons}}$<br>\n    (b) Total mass $= 1.2044 \\times 10^{22} \\times 1.6726 \\times 10^{-27}\\text{ kg} = \\mathbf{2.014 \\times 10^{-5}\\text{ kg} = 20.14\\text{ mg}}$<br>\n    • <b>Effect of changing T and P:</b> **No**, the mass and the number of protons do not change with temperature and pressure because atomic composition depends strictly on mass, not on gas volume.<br><br>\n    $$\\mathbf{\\text{Summary: (i) } 6.022 \\times 10^{24}\\text{; (ii) } 2.409 \\times 10^{21}\\text{, } 4.035\\text{ mg; (iii) } 1.204 \\times 10^{22}\\text{, } 20.14\\text{ mg, No change.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Number of electrons in 1 mol CH4 = 6.022 x 10^24</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Total neutrons = 2.409 x 10^21 and total mass = 4.035 mg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Total protons = 1.204 x 10^22, mass = 20.14 mg, and T/P invariance explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q3')\">\n      <div class=\"q-num\">Question 2.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How many neutrons and protons are there in the following nuclei?<br>\n   $^{13}_6\\text{C},\\; ^{16}_8\\text{O},\\; ^{24}_{12}\\text{Mg},\\; ^{56}_{26}\\text{Fe},\\; ^{88}_{38}\\text{Sr}$.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Using the standard nuclear notation $^{A}_{Z}\\text{X}$ where:<br>\n    • Atomic number $Z = \\text{Number of protons}$<br>\n    • Mass number $A = \\text{Protons} + \\text{Neutrons}$<br>\n    • Number of neutrons $N = A - Z$.<br><br>\n    <b>1. Carbon ($^{13}_6\\text{C}$):</b><br>\n    Protons $= Z = \\mathbf{6}$, Neutrons $= 13 - 6 = \\mathbf{7}$.<br><br>\n    <b>2. Oxygen ($^{16}_8\\text{O}$):</b><br>\n    Protons $= Z = \\mathbf{8}$, Neutrons $= 16 - 8 = \\mathbf{8}$.<br><br>\n    <b>3. Magnesium ($^{24}_{12}\\text{Mg}$):</b><br>\n    Protons $= Z = \\mathbf{12}$, Neutrons $= 24 - 12 = \\mathbf{12}$.<br><br>\n    <b>4. Iron ($^{56}_{26}\\text{Fe}$):</b><br>\n    Protons $= Z = \\mathbf{26}$, Neutrons $= 56 - 26 = \\mathbf{30}$.<br><br>\n    <b>5. Strontium ($^{88}_{38}\\text{Sr}$):</b><br>\n    Protons $= Z = \\mathbf{38}$, Neutrons $= 88 - 38 = \\mathbf{50}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct determination of protons & neutrons for C-13 and O-16</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct determination of protons & neutrons for Mg-24 and Fe-56</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct determination of protons & neutrons for Sr-88</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q4')\">\n      <div class=\"q-num\">Question 2.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write the complete symbol for the atom with the given atomic number ($Z$) and atomic mass ($A$):<br>\n   (i) $Z = 17, A = 35$<br>\n   (ii) $Z = 92, A = 233$<br>\n   (iii) $Z = 4, A = 9$\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    The standard atomic symbol is written as $^{A}_{Z}\\text{X}$.<br><br>\n    <b>(i) $Z = 17, A = 35$:</b><br>\n    Atomic number $17$ corresponds to Chlorine ($\\text{Cl}$).<br>\n    Symbol: $\\mathbf{^{35}_{17}\\text{Cl}}$<br><br>\n    <b>(ii) $Z = 92, A = 233$:</b><br>\n    Atomic number $92$ corresponds to Uranium ($\\text{U}$).<br>\n    Symbol: $\\mathbf{^{233}_{92}\\text{U}}$<br><br>\n    <b>(iii) $Z = 4, A = 9$:</b><br>\n    Atomic number $4$ corresponds to Beryllium ($\\text{Be}$).<br>\n    Symbol: $\\mathbf{^{9}_{4}\\text{Be}}$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Identification of Cl and complete notation 35_17 Cl</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Identification of U and complete notation 233_92 U</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Identification of Be and complete notation 9_4 Be</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q5')\">\n      <div class=\"q-num\">Question 2.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Yellow light emitted from a sodium lamp has a wavelength ($\\lambda$) of $580\\text{ nm}$. Calculate the frequency ($\\nu$) and wavenumber ($\\bar{\\nu}$) of the yellow light.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Wavelength $\\lambda = 580\\text{ nm} = 580 \\times 10^{-9}\\text{ m} = 5.80 \\times 10^{-7}\\text{ m}$<br>\n    • Speed of light $c = 3.0 \\times 10^8\\text{ m s}^{-1}$<br><br>\n    <b>1. Frequency ($\\nu$):</b><br>\n    $$\\nu = \\frac{c}{\\lambda} = \\frac{3.0 \\times 10^8\\text{ m s}^{-1}}{5.80 \\times 10^{-7}\\text{ m}} = \\mathbf{5.1724 \\times 10^{14}\\text{ s}^{-1} \\approx 5.17 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>2. Wavenumber ($\\bar{\\nu}$):</b><br>\n    $$\\bar{\\nu} = \\frac{1}{\\lambda} = \\frac{1}{5.80 \\times 10^{-7}\\text{ m}} = \\mathbf{1.724 \\times 10^6\\text{ m}^{-1} = 1.724 \\times 10^4\\text{ cm}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The frequency is } 5.17 \\times 10^{14}\\text{ Hz} \\text{ and wavenumber is } 1.724 \\times 10^6\\text{ m}^{-1}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculation of frequency nu = c / lambda = 5.17 x 10^14 Hz</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of wavenumber nu_bar = 1 / lambda = 1.724 x 10^6 m^-1</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q6')\">\n      <div class=\"q-num\">Question 2.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Find energy of each of the photons which<br>\n   (i) correspond to light of frequency $3 \\times 10^{15}\\text{ Hz}$.<br>\n   (ii) have wavelength of $0.50\\text{ \\AA}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Planck's constant $h = 6.626 \\times 10^{-34}\\text{ J s}$, $c = 3.0 \\times 10^8\\text{ m s}^{-1}$.<br><br>\n    <b>(i) Photon with frequency $\\nu = 3 \\times 10^{15}\\text{ Hz}$:</b><br>\n    $$E = h \\nu = (6.626 \\times 10^{-34}\\text{ J s}) \\times (3 \\times 10^{15}\\text{ s}^{-1})$$<br>\n    $$E = \\mathbf{1.9878 \\times 10^{-18}\\text{ J} \\approx 1.99 \\times 10^{-18}\\text{ J}}$$<br><br>\n    <b>(ii) Photon with wavelength $\\lambda = 0.50\\text{ \\AA} = 0.50 \\times 10^{-10}\\text{ m} = 5.0 \\times 10^{-11}\\text{ m}$:</b><br>\n    $$E = \\frac{h c}{\\lambda} = \\frac{(6.626 \\times 10^{-34}\\text{ J s}) \\times (3.0 \\times 10^8\\text{ m s}^{-1})}{5.0 \\times 10^{-11}\\text{ m}}$$<br>\n    $$E = \\frac{1.9878 \\times 10^{-25}}{5.0 \\times 10^{-11}} = \\mathbf{3.9756 \\times 10^{-15}\\text{ J} \\approx 3.98 \\times 10^{-15}\\text{ J}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (i) } 1.99 \\times 10^{-18}\\text{ J};\\; \\text{(ii) } 3.98 \\times 10^{-15}\\text{ J.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) E = h nu calculation yielding 1.99 x 10^-18 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) E = hc / lambda calculation yielding 3.98 x 10^-15 J</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q7')\">\n      <div class=\"q-num\">Question 2.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the wavelength, frequency and wavenumber of a light wave whose period is $2.0 \\times 10^{-10}\\text{ s}$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Time period $T = 2.0 \\times 10^{-10}\\text{ s}$.<br><br>\n    <b>1. Frequency ($\\nu$):</b><br>\n    $$\\nu = \\frac{1}{T} = \\frac{1}{2.0 \\times 10^{-10}\\text{ s}} = \\mathbf{5.0 \\times 10^9\\text{ s}^{-1} = 5.0 \\times 10^9\\text{ Hz}}$$<br><br>\n    <b>2. Wavelength ($\\lambda$):</b><br>\n    $$\\lambda = \\frac{c}{\\nu} = c \\times T = (3.0 \\times 10^8\\text{ m s}^{-1}) \\times (2.0 \\times 10^{-10}\\text{ s}) = \\mathbf{6.0 \\times 10^{-2}\\text{ m} = 0.06\\text{ m} = 6.0\\text{ cm}}$$<br><br>\n    <b>3. Wavenumber ($\\bar{\\nu}$):</b><br>\n    $$\\bar{\\nu} = \\frac{1}{\\lambda} = \\frac{1}{6.0 \\times 10^{-2}\\text{ m}} = \\mathbf{16.66\\text{ m}^{-1} \\approx 16.67\\text{ m}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{Results: Frequency } = 5.0 \\times 10^9\\text{ Hz},\\; \\text{Wavelength } = 6.0 \\times 10^{-2}\\text{ m},\\; \\text{Wavenumber } = 16.67\\text{ m}^{-1}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Frequency evaluation nu = 1/T = 5.0 x 10^9 Hz</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wavelength evaluation lambda = c/nu = 6.0 x 10^-2 m</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wavenumber evaluation nu_bar = 1/lambda = 16.67 m^-1</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q8')\">\n      <div class=\"q-num\">Question 2.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the number of photons of light with a wavelength of $4000\\text{ pm}$ that provide $1\\text{ J}$ of energy?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Wavelength $\\lambda = 4000\\text{ pm} = 4000 \\times 10^{-12}\\text{ m} = 4.0 \\times 10^{-9}\\text{ m}$<br>\n    • Total energy $E_{\\text{total}} = 1\\text{ J}$<br><br>\n    <b>1. Energy of a single photon ($E_p$):</b><br>\n    $$E_p = \\frac{h c}{\\lambda} = \\frac{(6.626 \\times 10^{-34}\\text{ J s}) \\times (3.0 \\times 10^8\\text{ m s}^{-1})}{4.0 \\times 10^{-9}\\text{ m}} = \\mathbf{4.9695 \\times 10^{-17}\\text{ J}}$$<br><br>\n    <b>2. Total number of photons ($N$):</b><br>\n    $$N = \\frac{E_{\\text{total}}}{E_p} = \\frac{1\\text{ J}}{4.9695 \\times 10^{-17}\\text{ J}} = \\mathbf{2.012 \\times 10^{16}\\text{ photons}}$$<br><br>\n    $$\\mathbf{\\text{The required number of photons is } 2.012 \\times 10^{16}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculating energy of one photon Ep = 4.97 x 10^-17 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding number of photons N = E_total / Ep = 2.012 x 10^16</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q9')\">\n      <div class=\"q-num\">Question 2.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A photon of wavelength $4 \\times 10^{-7}\\text{ m}$ strikes on metal surface, the work function of the metal being $2.13\\text{ eV}$. Calculate (i) the energy of the photon (in $\\text{eV}$), (ii) the kinetic energy of the emission, and (iii) the velocity of the photoelectron ($1\\text{ eV} = 1.6020 \\times 10^{-19}\\text{ J}$).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • $\\lambda = 4 \\times 10^{-7}\\text{ m}$<br>\n    • Work function $W_0 = 2.13\\text{ eV}$<br>\n    • $1\\text{ eV} = 1.6020 \\times 10^{-19}\\text{ J}$<br>\n    • Mass of electron $m_e = 9.109 \\times 10^{-31}\\text{ kg}$<br><br>\n    <b>(i) Energy of the photon:</b><br>\n    $$E = \\frac{h c}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{4 \\times 10^{-7}} = 4.9695 \\times 10^{-19}\\text{ J}$$<br>\n    $$E\\text{ (in eV)} = \\frac{4.9695 \\times 10^{-19}\\text{ J}}{1.6020 \\times 10^{-19}\\text{ J eV}^{-1}} = \\mathbf{3.102\\text{ eV} \\approx 3.10\\text{ eV}}$$<br><br>\n    <b>(ii) Kinetic energy of the emitted photoelectron:</b><br>\n    $$\\text{K.E.} = E - W_0 = 3.102\\text{ eV} - 2.13\\text{ eV} = \\mathbf{0.972\\text{ eV} \\approx 0.97\\text{ eV}}$$<br>\n    In Joules: $\\text{K.E.} = 0.972 \\times (1.6020 \\times 10^{-19}\\text{ J}) = \\mathbf{1.557 \\times 10^{-19}\\text{ J}}$<br><br>\n    <b>(iii) Velocity of the photoelectron ($v$):</b><br>\n    $$\\text{K.E.} = \\frac{1}{2} m_e v^2 \\implies v = \\sqrt{\\frac{2 \\times \\text{K.E.}}{m_e}}$$<br>\n    $$v = \\sqrt{\\frac{2 \\times 1.557 \\times 10^{-19}\\text{ J}}{9.109 \\times 10^{-31}\\text{ kg}}} = \\sqrt{3.4186 \\times 10^{11}} = \\mathbf{5.847 \\times 10^5\\text{ m s}^{-1} \\approx 5.85 \\times 10^5\\text{ m s}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (i) } 3.10\\text{ eV};\\; \\text{(ii) } 0.97\\text{ eV } (1.56 \\times 10^{-19}\\text{ J});\\; \\text{(iii) } 5.85 \\times 10^5\\text{ m s}^{-1}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Photon energy in eV = 3.10 eV</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Einstein photoelectric equation K.E. = 0.97 eV (1.56 x 10^-19 J)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Photoelectron velocity v = 5.85 x 10^5 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q10')\">\n      <div class=\"q-num\">Question 2.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Electromagnetic radiation of wavelength $242\\text{ nm}$ is just sufficient to ionise the sodium atom. Calculate the ionisation energy of sodium in $\\text{kJ mol}^{-1}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Threshold wavelength $\\lambda_0 = 242\\text{ nm} = 242 \\times 10^{-9}\\text{ m}$<br>\n    • $h = 6.626 \\times 10^{-34}\\text{ J s}$, $c = 3.0 \\times 10^8\\text{ m s}^{-1}$<br>\n    • $N_A = 6.022 \\times 10^{23}\\text{ mol}^{-1}$<br><br>\n    <b>1. Energy required to ionize one sodium atom ($E_0$):</b><br>\n    $$E_0 = \\frac{h c}{\\lambda_0} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{242 \\times 10^{-9}} = \\mathbf{8.214 \\times 10^{-19}\\text{ J}}$$<br><br>\n    <b>2. Ionisation energy per mole of sodium atoms:</b><br>\n    $$\\text{I.E.} = E_0 \\times N_A = (8.214 \\times 10^{-19}\\text{ J}) \\times (6.022 \\times 10^{23}\\text{ mol}^{-1})$$<br>\n    $$\\text{I.E.} = 494647\\text{ J mol}^{-1} = \\mathbf{494.65\\text{ kJ mol}^{-1} \\approx 494.7\\text{ kJ mol}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The ionisation energy of sodium is } 494.7\\text{ kJ mol}^{-1}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculating threshold energy per atom E0 = 8.214 x 10^-19 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying by Avogadro number to get 494.7 kJ/mol</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q11')\">\n      <div class=\"q-num\">Question 2.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A $25\\text{ watt}$ bulb emits monochromatic yellow light of wavelength of $0.57\\ \\mu\\text{m}$. Calculate the rate of emission of quanta per second.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Power of bulb $P = 25\\text{ W} = 25\\text{ J s}^{-1}$<br>\n    • Wavelength $\\lambda = 0.57\\ \\mu\\text{m} = 0.57 \\times 10^{-6}\\text{ m} = 5.7 \\times 10^{-7}\\text{ m}$<br><br>\n    <b>1. Energy of one quantum of light ($E$):</b><br>\n    $$E = \\frac{h c}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{5.7 \\times 10^{-7}} = \\mathbf{3.4874 \\times 10^{-19}\\text{ J}}$$<br><br>\n    <b>2. Rate of emission of quanta per second ($n$):</b><br>\n    $$n = \\frac{\\text{Energy emitted per second}}{\\text{Energy of one quantum}} = \\frac{25\\text{ J s}^{-1}}{3.4874 \\times 10^{-19}\\text{ J}}$$<br>\n    $$n = \\mathbf{7.1686 \\times 10^{19}\\text{ quanta s}^{-1} \\approx 7.17 \\times 10^{19}\\text{ s}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The bulb emits } 7.17 \\times 10^{19}\\text{ quanta per second.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Energy of single quantum calculation = 3.487 x 10^-19 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rate of emission n = P / E = 7.17 x 10^19 quanta/s</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q12')\">\n      <div class=\"q-num\">Question 2.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Electrons are emitted with zero velocity from a metal surface when it is exposed to radiation of wavelength $6800\\text{ \\AA}$. Calculate threshold frequency ($\\nu_0$) and work function ($W_0$) of the metal.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Electrons emitted with zero velocity ($v = 0 \\implies \\text{K.E.} = 0$).<br>\n    Hence, the incident radiation corresponds exactly to the threshold wavelength: $\\lambda_0 = 6800\\text{ \\AA} = 6800 \\times 10^{-10}\\text{ m} = 6.8 \\times 10^{-7}\\text{ m}$.<br><br>\n    <b>1. Threshold Frequency ($\\nu_0$):</b><br>\n    $$\\nu_0 = \\frac{c}{\\lambda_0} = \\frac{3.0 \\times 10^8\\text{ m s}^{-1}}{6.8 \\times 10^{-7}\\text{ m}} = \\mathbf{4.4118 \\times 10^{14}\\text{ s}^{-1} \\approx 4.41 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>2. Work function ($W_0$):</b><br>\n    $$W_0 = h \\nu_0 = (6.626 \\times 10^{-34}\\text{ J s}) \\times (4.4118 \\times 10^{14}\\text{ s}^{-1}) = \\mathbf{2.923 \\times 10^{-19}\\text{ J}}$$<br>\n    In electron volts: $W_0 = \\frac{2.923 \\times 10^{-19}\\text{ J}}{1.602 \\times 10^{-19}\\text{ J eV}^{-1}} = \\mathbf{1.825\\text{ eV} \\approx 1.83\\text{ eV}}$<br><br>\n    $$\\mathbf{\\text{Threshold frequency } = 4.41 \\times 10^{14}\\text{ Hz},\\; \\text{Work function } = 2.923 \\times 10^{-19}\\text{ J (or } 1.83\\text{ eV}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Threshold frequency evaluation nu_0 = 4.41 x 10^14 Hz</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Work function evaluation W_0 = h nu_0 = 2.923 x 10^-19 J (1.83 eV)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q13')\">\n      <div class=\"q-num\">Question 2.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the wavelength of light emitted when the electron in a hydrogen atom undergoes transition from an energy level with $n = 4$ to an energy level with $n = 2$?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Rydberg formula for hydrogen ($Z = 1$):<br>\n    $$\\bar{\\nu} = \\frac{1}{\\lambda} = R_H \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right)$$<br>\n    where $R_H = 1.09677 \\times 10^7\\text{ m}^{-1}$, $n_1 = 2$, $n_2 = 4$ (Balmer series transition).<br><br>\n    $$\\frac{1}{\\lambda} = (1.09677 \\times 10^7) \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right) = (1.09677 \\times 10^7) \\left(\\frac{1}{4} - \\frac{1}{16}\\right)$$<br>\n    $$\\frac{1}{\\lambda} = (1.09677 \\times 10^7) \\times \\frac{3}{16} = 2.05644 \\times 10^6\\text{ m}^{-1}$$<br>\n    $$\\lambda = \\frac{1}{2.05644 \\times 10^6\\text{ m}^{-1}} = 4.8627 \\times 10^{-7}\\text{ m} = \\mathbf{486.3\\text{ nm} = 4863\\text{ \\AA}}$$<br><br>\n    $$\\mathbf{\\text{The emitted wavelength is } 486.3\\text{ nm (blue-green line of the Balmer series).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Setting up Rydberg equation with n1=2, n2=4</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate evaluation of lambda = 486.3 nm (4863 A)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q14')\">\n      <div class=\"q-num\">Question 2.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How much energy is required to ionise a $\\text{H}$ atom if the electron occupies $n = 5$ orbit? Compare your answer with the ionization enthalpy of $\\text{H}$ atom (energy required to remove the electron from $n = 1$ orbit).\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Bohr energy expression for hydrogen atom:<br>\n    $$E_n = -\\frac{2.18 \\times 10^{-18}}{n^2}\\text{ J atom}^{-1}$$<br><br>\n    <b>1. Ionization energy from $n = 5$ orbit ($\\Delta E_5$):</b><br>\n    Electron is removed to $n = \\infty$ ($E_\\infty = 0$):<br>\n    $$\\Delta E_5 = E_\\infty - E_5 = 0 - \\left(-\\frac{2.18 \\times 10^{-18}}{5^2}\\right) = \\frac{2.18 \\times 10^{-18}}{25} = \\mathbf{8.72 \\times 10^{-20}\\text{ J atom}^{-1}}$$<br><br>\n    <b>2. Ionization energy from $n = 1$ orbit (Ground state I.E.):</b><br>\n    $$\\Delta E_1 = E_\\infty - E_1 = 0 - (-2.18 \\times 10^{-18}) = \\mathbf{2.18 \\times 10^{-18}\\text{ J atom}^{-1}}$$<br><br>\n    <b>3. Comparison:</b><br>\n    $$\\frac{\\Delta E_1}{\\Delta E_5} = \\frac{2.18 \\times 10^{-18}}{8.72 \\times 10^{-20}} = \\mathbf{25\\text{ times}}$$<br>\n    $$\\mathbf{\\text{Energy required from } n=5 \\text{ is } 8.72 \\times 10^{-20}\\text{ J, which is } 25\\text{ times less than the ground state I.E.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculating ionization energy from n=5 orbit = 8.72 x 10^-20 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating ground state ionization energy = 2.18 x 10^-18 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ratio comparison showing Delta E1 is 25 times greater than Delta E5</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q15')\">\n      <div class=\"q-num\">Question 2.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the maximum number of emission lines when the excited electron of a $\\text{H}$ atom in $n = 6$ drops to the ground state?\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Formula for total number of spectral emission lines when electron drops from level $n_2$ to $n_1$ (here $n_2 = 6, n_1 = 1$):<br>\n    $$N = \\frac{(n_2 - n_1)(n_2 - n_1 + 1)}{2} = \\frac{\\Delta n (\\Delta n + 1)}{2}$$<br>\n    Here $\\Delta n = 6 - 1 = 5$:<br>\n    $$N = \\frac{5 \\times (5 + 1)}{2} = \\frac{5 \\times 6}{2} = \\mathbf{15\\text{ emission lines}}$$<br><br>\n    <i>Breakdown by spectral series:</i><br>\n    • Lyman series ($n \\to 1$): $6 \\to 1, 5 \\to 1, 4 \\to 1, 3 \\to 1, 2 \\to 1$ ($5$ lines)<br>\n    • Balmer series ($n \\to 2$): $6 \\to 2, 5 \\to 2, 4 \\to 2, 3 \\to 2$ ($4$ lines)<br>\n    • Paschen series ($n \\to 3$): $6 \\to 3, 5 \\to 3, 4 \\to 3$ ($3$ lines)<br>\n    • Brackett series ($n \\to 4$): $6 \\to 4, 5 \\to 4$ ($2$ lines)<br>\n    • Pfund series ($n \\to 5$): $6 \\to 5$ ($1$ line)<br>\n    $$\\text{Total} = 5 + 4 + 3 + 2 + 1 = \\mathbf{15\\text{ lines}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Formula N = Delta n(Delta n + 1)/2 stated clearly</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation yielding maximum 15 emission lines with series breakdown</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q16')\">\n      <div class=\"q-num\">Question 2.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        (i) The energy associated with the first orbit in the hydrogen atom is $-2.18 \\times 10^{-18}\\text{ J atom}^{-1}$. What is the energy associated with the fifth orbit?<br>\n   (ii) Calculate the radius of Bohr's fifth orbit for hydrogen atom.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) Energy associated with the 5th orbit ($E_5$):</b><br>\n    Bohr energy equation: $E_n = \\frac{E_1}{n^2}$ where $E_1 = -2.18 \\times 10^{-18}\\text{ J atom}^{-1}$.<br>\n    $$E_5 = \\frac{-2.18 \\times 10^{-18}\\text{ J}}{5^2} = \\frac{-2.18 \\times 10^{-18}}{25} = \\mathbf{-8.72 \\times 10^{-20}\\text{ J atom}^{-1}}$$<br><br>\n    <b>(ii) Radius of Bohr's 5th orbit ($r_5$):</b><br>\n    Bohr radius formula: $r_n = a_0 \\frac{n^2}{Z} = 0.0529\\text{ nm} \\times \\frac{n^2}{Z} = 52.9\\text{ pm} \\times n^2$ (for $\\text{H}, Z=1$).<br>\n    $$r_5 = 0.0529 \\times (5)^2 = 0.0529 \\times 25 = \\mathbf{1.3225\\text{ nm} = 1.3225 \\times 10^{-9}\\text{ m} = 1322.5\\text{ pm}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (i) } E_5 = -8.72 \\times 10^{-20}\\text{ J atom}^{-1};\\; \\text{(ii) } r_5 = 1.3225\\text{ nm (or } 1322.5\\text{ pm}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Calculating energy E5 = -8.72 x 10^-20 J atom^-1</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Calculating Bohr radius r5 = 1.3225 nm (1322.5 pm)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q17')\">\n      <div class=\"q-num\">Question 2.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the wavenumber for the longest wavelength transition in the Balmer series of atomic hydrogen.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    In the Balmer series, transitions terminate at $n_1 = 2$.<br>\n    Since $E = \\frac{hc}{\\lambda} = hc\\bar{\\nu}$, the **longest wavelength** corresponds to the **minimum energy transition** ($H_\\alpha$ line), which occurs between the closest adjacent energy levels: $n_2 = 3 \\to n_1 = 2$.<br><br>\n    Applying Rydberg's equation:<br>\n    $$\\bar{\\nu} = R_H \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = (1.09677 \\times 10^7\\text{ m}^{-1}) \\left(\\frac{1}{2^2} - \\frac{1}{3^2}\\right)$$<br>\n    $$\\bar{\\nu} = (1.09677 \\times 10^7) \\left(\\frac{1}{4} - \\frac{1}{9}\\right) = (1.09677 \\times 10^7) \\times \\frac{5}{36}$$<br>\n    $$\\bar{\\nu} = \\frac{5.48385 \\times 10^7}{36} = \\mathbf{1.52329 \\times 10^6\\text{ m}^{-1} \\approx 1.523 \\times 10^4\\text{ cm}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The wavenumber for the longest wavelength transition is } 1.523 \\times 10^6\\text{ m}^{-1}\\; (\\lambda = 656.3\\text{ nm}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Identifying longest wavelength requires n1=2 to n2=3 transition</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation of wavenumber nu_bar = 1.523 x 10^6 m^-1</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q18')\">\n      <div class=\"q-num\">Question 2.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the energy in joules, required to shift the electron of the hydrogen atom from the first Bohr orbit to the fifth Bohr orbit and what is the wavelength of the light emitted when the electron returns to the ground state? The ground state electron energy is $-2.18 \\times 10^{-11}\\text{ ergs}$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Ground state energy $E_1 = -2.18 \\times 10^{-11}\\text{ erg}$.<br>\n    Convert ergs to Joules ($1\\text{ J} = 10^7\\text{ ergs} \\implies 1\\text{ erg} = 10^{-7}\\text{ J}$):<br>\n    $$E_1 = -2.18 \\times 10^{-11} \\times 10^{-7}\\text{ J} = -2.18 \\times 10^{-18}\\text{ J}$$<br><br>\n    <b>1. Energy required for $n = 1 \\to n = 5$ transition ($\\Delta E$):</b><br>\n    $$E_5 = \\frac{E_1}{5^2} = \\frac{-2.18 \\times 10^{-18}\\text{ J}}{25} = -8.72 \\times 10^{-20}\\text{ J}$$<br>\n    $$\\Delta E = E_5 - E_1 = (-8.72 \\times 10^{-20}) - (-2.18 \\times 10^{-18}) = \\mathbf{2.0928 \\times 10^{-18}\\text{ J}}$$<br><br>\n    <b>2. Wavelength of light emitted when returning to ground state ($n = 5 \\to n = 1$):</b><br>\n    $$\\Delta E = \\frac{hc}{\\lambda} \\implies \\lambda = \\frac{hc}{\\Delta E}$$<br>\n    $$\\lambda = \\frac{(6.626 \\times 10^{-34}\\text{ J s}) \\times (3.0 \\times 10^8\\text{ m s}^{-1})}{2.0928 \\times 10^{-18}\\text{ J}} = \\mathbf{9.498 \\times 10^{-8}\\text{ m} = 94.98\\text{ nm} = 95.0\\text{ nm}}$$<br><br>\n    $$\\mathbf{\\text{Energy required } = 2.093 \\times 10^{-18}\\text{ J},\\; \\text{Wavelength emitted } = 94.98\\text{ nm (Lyman series, UV).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Unit conversion of erg to Joules and calculating E5 = -8.72 x 10^-20 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Delta E calculation = 2.093 x 10^-18 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wavelength evaluation lambda = 94.98 nm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q19')\">\n      <div class=\"q-num\">Question 2.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The electron energy in hydrogen atom is given by $E_n = (-2.18 \\times 10^{-18}) / n^2\\text{ J}$. Calculate the energy required to remove an electron completely from the $n = 2$ orbit. What is the longest wavelength of light in $\\text{cm}$ that can be used to cause this transition?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Energy required to remove electron completely from $n = 2$ ($n = 2 \\to n = \\infty$):</b><br>\n    $$E_2 = \\frac{-2.18 \\times 10^{-18}}{2^2} = \\frac{-2.18 \\times 10^{-18}}{4} = -5.45 \\times 10^{-19}\\text{ J}$$<br>\n    $$\\Delta E = E_\\infty - E_2 = 0 - (-5.45 \\times 10^{-19}\\text{ J}) = \\mathbf{5.45 \\times 10^{-19}\\text{ J}}$$<br><br>\n    <b>2. Longest wavelength (threshold wavelength $\\lambda_{\\text{max}}$) in cm:</b><br>\n    $$\\Delta E = \\frac{hc}{\\lambda} \\implies \\lambda = \\frac{hc}{\\Delta E}$$<br>\n    $$\\lambda = \\frac{(6.626 \\times 10^{-34}\\text{ J s}) \\times (3.0 \\times 10^8\\text{ m s}^{-1})}{5.45 \\times 10^{-19}\\text{ J}} = 3.647 \\times 10^{-7}\\text{ m}$$<br>\n    In centimeters ($1\\text{ m} = 10^2\\text{ cm}$):<br>\n    $$\\lambda = 3.647 \\times 10^{-7} \\times 10^2\\text{ cm} = \\mathbf{3.647 \\times 10^{-5}\\text{ cm} \\approx 3.65 \\times 10^{-5}\\text{ cm}}$$<br><br>\n    $$\\mathbf{\\text{Energy required } = 5.45 \\times 10^{-19}\\text{ J},\\; \\text{Longest wavelength } = 3.647 \\times 10^{-5}\\text{ cm.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Ionization energy from n=2 calculation = 5.45 x 10^-19 J</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating wavelength in centimeters = 3.647 x 10^-5 cm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q20')\">\n      <div class=\"q-num\">Question 2.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the wavelength of an electron moving with a velocity of $2.05 \\times 10^7\\text{ m s}^{-1}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Applying de Broglie's relation: $\\lambda = \\frac{h}{m v}$<br>\n    Given Data:<br>\n    • $h = 6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}$<br>\n    • Mass of electron $m_e = 9.10939 \\times 10^{-31}\\text{ kg}$<br>\n    • Velocity $v = 2.05 \\times 10^7\\text{ m s}^{-1}$<br><br>\n    $$\\lambda = \\frac{6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}}{(9.10939 \\times 10^{-31}\\text{ kg}) \\times (2.05 \\times 10^7\\text{ m s}^{-1})}$$<br>\n    $$\\lambda = \\frac{6.626 \\times 10^{-34}}{1.8674 \\times 10^{-23}} = \\mathbf{3.548 \\times 10^{-11}\\text{ m} = 0.03548\\text{ nm} = 35.48\\text{ pm}}$$<br><br>\n    $$\\mathbf{\\text{The de Broglie wavelength of the electron is } 3.548 \\times 10^{-11}\\text{ m (or } 35.48\\text{ pm}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Statement of de Broglie equation lambda = h / mv</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Numerical substitution and accurate answer lambda = 3.548 x 10^-11 m (35.48 pm)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q21')\">\n      <div class=\"q-num\">Question 2.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The mass of an electron is $9.1 \\times 10^{-31}\\text{ kg}$. If its K.E. is $3.0 \\times 10^{-25}\\text{ J}$, calculate its wavelength.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • $m = 9.1 \\times 10^{-31}\\text{ kg}$<br>\n    • $\\text{K.E.} = 3.0 \\times 10^{-25}\\text{ J}$<br><br>\n    <b>1. Velocity from Kinetic Energy:</b><br>\n    $$\\text{K.E.} = \\frac{1}{2} m v^2 \\implies v = \\sqrt{\\frac{2 \\times \\text{K.E.}}{m}}$$<br>\n    $$v = \\sqrt{\\frac{2 \\times 3.0 \\times 10^{-25}\\text{ J}}{9.1 \\times 10^{-31}\\text{ kg}}} = \\sqrt{6.5934 \\times 10^5} = \\mathbf{811.998\\text{ m s}^{-1} \\approx 8.12 \\times 10^2\\text{ m s}^{-1}}$$<br><br>\n    <b>2. de Broglie Wavelength:</b><br>\n    $$\\lambda = \\frac{h}{m v} = \\frac{6.626 \\times 10^{-34}}{(9.1 \\times 10^{-31}) \\times (812)} = \\frac{6.626 \\times 10^{-34}}{7.389 \\times 10^{-28}} = \\mathbf{8.967 \\times 10^{-7}\\text{ m} \\approx 896.7\\text{ nm}}$$<br><br>\n    <i>Direct shortcut formula:</i> $\\lambda = \\frac{h}{\\sqrt{2 m (\\text{K.E.})}} = \\frac{6.626 \\times 10^{-34}}{\\sqrt{2 \\times (9.1 \\times 10^{-31}) \\times (3.0 \\times 10^{-25})}} = \\mathbf{8.967 \\times 10^{-7}\\text{ m}}$.<br><br>\n    $$\\mathbf{\\text{The wavelength of the electron is } 8.967 \\times 10^{-7}\\text{ m (or } 896.7\\text{ nm}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Deriving relation lambda = h / sqrt(2m*KE) or calculating v = 812 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final wavelength calculation lambda = 8.967 x 10^-7 m</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q22')\">\n      <div class=\"q-num\">Question 2.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which of the following are isoelectronic species i.e., those having the same number of electrons?<br>\n   $\\text{Na}^+,\\; \\text{K}^+,\\; \\text{Mg}^{2+},\\; \\text{Ca}^{2+},\\; \\text{S}^{2-},\\; \\text{Ar}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Isoelectronic species have identical numbers of electrons.<br><br>\n    Calculate the total electrons for each species ($e^- = Z - \\text{charge}$):<br>\n    • $\\text{Na}^+$: $Z = 11$, electrons $= 11 - 1 = \\mathbf{10\\text{ e}^-}$<br>\n    • $\\text{Mg}^{2+}$: $Z = 12$, electrons $= 12 - 2 = \\mathbf{10\\text{ e}^-}$<br>\n    • $\\text{K}^+$: $Z = 19$, electrons $= 19 - 1 = \\mathbf{18\\text{ e}^-}$<br>\n    • $\\text{Ca}^{2+}$: $Z = 20$, electrons $= 20 - 2 = \\mathbf{18\\text{ e}^-}$<br>\n    • $\\text{S}^{2-}$: $Z = 16$, electrons $= 16 - (-2) = \\mathbf{18\\text{ e}^-}$<br>\n    • $\\text{Ar}$: $Z = 18$, electrons $= \\mathbf{18\\text{ e}^-}$<br><br>\n    <b>Isoelectronic Groups:</b><br>\n    1. **10-electron group (Isoelectronic with $\\text{Ne}$):** $\\mathbf{\\text{Na}^+ \\text{ and } \\text{Mg}^{2+}}$<br>\n    2. **18-electron group (Isoelectronic with $\\text{Ar}$):** $\\mathbf{\\text{K}^+,\\; \\text{Ca}^{2+},\\; \\text{S}^{2-},\\; \\text{and } \\text{Ar}}$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Electron count determination for each of the 6 species</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Classification into 10-electron group (Na+, Mg2+) and 18-electron group (K+, Ca2+, S2-, Ar)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q23 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q23\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q23')\">\n      <div class=\"q-num\">Question 2.23</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        (i) Write the electronic configurations of the following ions:<br>\n   (a) $\\text{H}^-$, (b) $\\text{Na}^+$, (c) $\\text{O}^{2-}$, (d) $\\text{F}^-$.<br>\n   (ii) What are the atomic numbers of elements whose outermost electrons are represented by (a) $3s^1$, (b) $2p^3$, and (c) $3p^5$?<br>\n   (iii) Which atoms are indicated by the following configurations?<br>\n   (a) $[\\text{He}] 2s^1$, (b) $[\\text{Ne}] 3s^2 3p^3$, (c) $[\\text{Ar}] 4s^2 3d^1$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) Electronic configuration of ions:</b><br>\n    (a) $\\text{H}^-$ ($Z=1, 2\\text{ e}^-$): $\\mathbf{1s^2}$ (Helium configuration)<br>\n    (b) $\\text{Na}^+$ ($Z=11, 10\\text{ e}^-$): $\\mathbf{1s^2 2s^2 2p^6}$ ($[\\text{Ne}]$)<br>\n    (c) $\\text{O}^{2-}$ ($Z=8, 10\\text{ e}^-$): $\\mathbf{1s^2 2s^2 2p^6}$ ($[\\text{Ne}]$)<br>\n    (d) $\\text{F}^-$ ($Z=9, 10\\text{ e}^-$): $\\mathbf{1s^2 2s^2 2p^6}$ ($[\\text{Ne}]$)<br><br>\n    <b>(ii) Atomic numbers corresponding to outermost configurations:</b><br>\n    (a) $3s^1$: Core configuration $1s^2 2s^2 2p^6 3s^1 \\implies \\text{Total electrons} = 11 \\implies \\mathbf{Z = 11\\text{ (Sodium, Na)}}$<br>\n    (b) $2p^3$: Core configuration $1s^2 2s^2 2p^3 \\implies \\text{Total electrons} = 7 \\implies \\mathbf{Z = 7\\text{ (Nitrogen, N)}}$<br>\n    (c) $3p^5$: Core configuration $1s^2 2s^2 2p^6 3s^2 3p^5 \\implies \\text{Total electrons} = 17 \\implies \\mathbf{Z = 17\\text{ (Chlorine, Cl)}}$<br><br>\n    <b>(iii) Atoms indicated by condensed configurations:</b><br>\n    (a) $[\\text{He}] 2s^1$: $2 + 1 = 3\\text{ electrons} \\implies \\mathbf{\\text{Lithium (Li)}}$<br>\n    (b) $[\\text{Ne}] 3s^2 3p^3$: $10 + 2 + 3 = 15\\text{ electrons} \\implies \\mathbf{\\text{Phosphorus (P)}}$<br>\n    (c) $[\\text{Ar}] 4s^2 3d^1$: $18 + 2 + 1 = 21\\text{ electrons} \\implies \\mathbf{\\text{Scandium (Sc)}}$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Electronic configurations of H-, Na+, O2-, F-</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Identifying atomic numbers Z = 11, Z = 7, Z = 17</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Identifying elemental atoms Li, P, and Sc</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q24 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q24\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q24')\">\n      <div class=\"q-num\">Question 2.24</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the lowest value of $n$ that allows $g$ orbitals to exist?\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Subshells correspond to azimuthal quantum number $l$ values:<br>\n    • $s$ subshell: $l = 0$<br>\n    • $p$ subshell: $l = 1$<br>\n    • $d$ subshell: $l = 2$<br>\n    • $f$ subshell: $l = 3$<br>\n    • $g$ subshell: $l = 4$<br><br>\n    According to quantum mechanical rules, $l$ can take integer values from $0$ to $(n - 1)$.<br>\n    Therefore, for $l = 4$ to exist:<br>\n    $$n - 1 \\ge 4 \\implies n \\ge 4 + 1 = 5$$<br>\n    $$\\mathbf{\\text{The lowest value of the principal quantum number } n \\text{ that allows } g \\text{ orbitals to exist is } n = 5.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correlating g orbital with l = 4 and l <= n - 1</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding minimum n = 5</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q25 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q25\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q25')\">\n      <div class=\"q-num\">Question 2.25</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An electron is in one of the $3d$ orbitals. Give the possible values of $n, l$ and $m_l$ for this electron.\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    For a $3d$ orbital:<br>\n    1. Principal quantum number: $\\mathbf{n = 3}$<br>\n    2. Azimuthal quantum number for a $d$-subshell: $\\mathbf{l = 2}$<br>\n    3. Magnetic quantum number $m_l$ takes values from $-l$ to $+l$:<br>\n    $$m_l = -2,\\; -1,\\; 0,\\; +1,\\; +2$$<br>\n    $$\\mathbf{\\text{Possible values: } n = 3,\\; l = 2,\\; m_l \\in \\{-2, -1, 0, +1, +2\\}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Identification of n = 3 and l = 2</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">All 5 permissible values of ml: -2, -1, 0, +1, +2</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q26 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q26\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q26')\">\n      <div class=\"q-num\">Question 2.26</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An atom of an element contains $29$ electrons and $35$ neutrons. Deduce (i) the number of protons and (ii) the electronic configuration of the element.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) Number of protons:</b><br>\n    For a neutral atom, $\\text{Number of protons} = \\text{Number of electrons} = \\mathbf{29}$.<br>\n    Hence, the atomic number $Z = 29$, which represents **Copper ($\\text{Cu}$)**.<br>\n    (Mass number $A = 29 + 35 = 64$, corresponding to $^{64}_{29}\\text{Cu}$).<br><br>\n    <b>(ii) Electronic configuration of Copper ($Z = 29$):</b><br>\n    Due to the extra stability of completely filled $3d^{10}$ subshell, an electron shifts from $4s$ to $3d$ (exceptional configuration):<br>\n    $$\\mathbf{1s^2 \\; 2s^2 \\; 2p^6 \\; 3s^2 \\; 3p^6 \\; 3d^{10} \\; 4s^1 \\quad \\text{or} \\quad [\\text{Ar}] \\; 3d^{10} \\; 4s^1}$$<br>\n    $$\\mathbf{\\text{Protons } = 29,\\; \\text{Electronic configuration: } [\\text{Ar}]\\; 3d^{10} 4s^1.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Number of protons = 29 (identifying element as Cu)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Completely filled d-orbital configuration: [Ar] 3d^10 4s^1</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q27 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q27\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q27')\">\n      <div class=\"q-num\">Question 2.27</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give the number of electrons in the species $\\text{H}_2^+$, $\\text{H}_2$ and $\\text{O}_2^+$.\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. $\\text{H}_2^+$ ion:</b><br>\n    A neutral $\\text{H}_2$ molecule has $2 \\times 1 = 2\\text{ electrons}$.<br>\n    Removal of $1$ electron for $+1$ charge leaves: $2 - 1 = \\mathbf{1\\text{ electron}}$.<br><br>\n    <b>2. $\\text{H}_2$ molecule:</b><br>\n    Two hydrogen atoms: $2 \\times 1 = \\mathbf{2\\text{ electrons}}$.<br><br>\n    <b>3. $\\text{O}_2^+$ ion:</b><br>\n    A neutral $\\text{O}_2$ molecule has $2 \\times 8 = 16\\text{ electrons}$.<br>\n    Removal of $1$ electron for $+1$ charge leaves: $16 - 1 = \\mathbf{15\\text{ electrons}}$.<br><br>\n    $$\\mathbf{\\text{Summary: } \\text{H}_2^+ = 1\\text{ electron},\\; \\text{H}_2 = 2\\text{ electrons},\\; \\text{O}_2^+ = 15\\text{ electrons}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">H2+ electron count = 1</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">H2 electron count = 2</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">O2+ electron count = 15</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q28 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q28\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q28')\">\n      <div class=\"q-num\">Question 2.28</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        (i) An atomic orbital has $n = 3$. What are the possible values of $l$ and $m_l$?<br>\n   (ii) List the quantum numbers ($m_l$ and $l$) of electrons for $3d$ orbital.<br>\n   (iii) Which of the following orbitals are possible? $1p, 2s, 2p$ and $3f$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) For $n = 3$:</b><br>\n    • Azimuthal quantum number $l = 0, 1, 2$.<br>\n    • For $l = 0$ ($3s$): $m_l = 0$<br>\n    • For $l = 1$ ($3p$): $m_l = -1, 0, +1$<br>\n    • For $l = 2$ ($3d$): $m_l = -2, -1, 0, +1, +2$<br><br>\n    <b>(ii) For $3d$ orbital:</b><br>\n    • $\\mathbf{l = 2}$<br>\n    • $\\mathbf{m_l = -2, -1, 0, +1, +2}$<br><br>\n    <b>(iii) Possibility of given orbitals:</b><br>\n    • $1p$: **Not possible** (For $n = 1$, $l$ can only be $0$ ($1s$); $l = 1$ is invalid since $l < n$).<br>\n    • $2s$: **Possible** ($n = 2, l = 0$).<br>\n    • $2p$: **Possible** ($n = 2, l = 1$).<br>\n    • $3f$: **Not possible** (For $n = 3$, $l$ can only be $0, 1, 2$; for $f$, $l = 3$, which requires $n \\ge 4$).<br><br>\n    $$\\mathbf{\\text{Possible orbitals: } 2s \\text{ and } 2p.\\; \\text{Impossible orbitals: } 1p \\text{ and } 3f.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Values for n=3: l = 0, 1, 2 and corresponding ml ranges</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Quantum numbers for 3d: l = 2, ml = -2, -1, 0, +1, +2</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Validating 2s, 2p (possible) and 1p, 3f (not possible with reasons)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q29 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q29\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q29')\">\n      <div class=\"q-num\">Question 2.29</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Using $s, p, d$ notations, describe the orbital with the following quantum numbers:<br>\n   (a) $n = 1, l = 0$; (b) $n = 3, l = 1$; (c) $n = 4, l = 2$; (d) $n = 4, l = 3$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    The standard notation writes the principal number $n$ followed by the letter representing subshell $l$ ($l = 0 \\to s, 1 \\to p, 2 \\to d, 3 \\to f$):<br><br>\n    (a) $n = 1, l = 0 \\implies \\mathbf{1s}$<br>\n    (b) $n = 3, l = 1 \\implies \\mathbf{3p}$<br>\n    (c) $n = 4, l = 2 \\implies \\mathbf{4d}$<br>\n    (d) $n = 4, l = 3 \\implies \\mathbf{4f}$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) 1s and (b) 3p identification</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) 4d and (d) 4f identification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q30 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q30\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q30')\">\n      <div class=\"q-num\">Question 2.30</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain, giving reasons, which of the following sets of quantum numbers are not possible:<br>\n   (a) $n = 0, l = 0, m_l = 0, m_s = +1/2$<br>\n   (b) $n = 1, l = 0, m_l = 0, m_s = -1/2$<br>\n   (c) $n = 1, l = 1, m_l = 0, m_s = +1/2$<br>\n   (d) $n = 2, l = 1, m_l = 0, m_s = -1/2$<br>\n   (e) $n = 3, l = 3, m_l = -3, m_s = +1/2$<br>\n   (f) $n = 3, l = 1, m_l = 0, m_s = +1/2$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Rules: $n \\ge 1$; $0 \\le l \\le n - 1$; $-l \\le m_l \\le +l$; $m_s = \\pm 1/2$.<br><br>\n    • **(a) Not possible:** $n = 0$ is invalid because $n$ must be a positive integer ($n = 1, 2, 3...$).<br>\n    • **(b) Possible:** $n = 1, l = 0$ ($1s$), $m_l = 0, m_s = -1/2$ (Valid).<br>\n    • **(c) Not possible:** For $n = 1$, $l$ cannot be $1$ because $l$ can only be $0$ ($l \\le n-1$).<br>\n    • **(d) Possible:** $n = 2, l = 1$ ($2p$), $m_l = 0, m_s = -1/2$ (Valid).<br>\n    • **(e) Not possible:** For $n = 3$, $l$ cannot be $3$ ($l$ can only be $0, 1, 2$; $l$ must be strictly less than $n$).<br>\n    • **(f) Possible:** $n = 3, l = 1$ ($3p$), $m_l = 0, m_s = +1/2$ (Valid).<br><br>\n    $$\\mathbf{\\text{Sets not possible: (a), (c), and (e).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Identification and reason for (a) (n=0 invalid) and (b) (valid)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification and reason for (c) (l=1 invalid for n=1) and (d) (valid)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification and reason for (e) (l=3 invalid for n=3) and (f) (valid)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q31 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q31\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q31')\">\n      <div class=\"q-num\">Question 2.31</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How many electrons in an atom may have the following quantum numbers?<br>\n   (a) $n = 4, m_s = -1/2$<br>\n   (b) $n = 3, l = 0$\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(a) $n = 4, m_s = -1/2$:</b><br>\n    Total number of electrons in shell $n$ is given by $2n^2$.<br>\n    For $n = 4$: $\\text{Total electrons} = 2(4)^2 = 2 \\times 16 = 32\\text{ electrons}$.<br>\n    In any shell, exactly half the electrons have spin $+1/2$ and the other half have spin $-1/2$.<br>\n    $$\\text{Number of electrons with } m_s = -1/2 = \\frac{32}{2} = \\mathbf{16\\text{ electrons}}$$<br><br>\n    <b>(b) $n = 3, l = 0$:</b><br>\n    This specifies the $3s$ subshell.<br>\n    An $s$ subshell consists of exactly $1$ orbital ($m_l = 0$).<br>\n    By Pauli's exclusion principle, each orbital can hold a maximum of $2$ electrons (with opposite spins).<br>\n    $$\\text{Number of electrons} = \\mathbf{2\\text{ electrons}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (a) } 16\\text{ electrons};\\; \\text{(b) } 2\\text{ electrons.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Shell n=4 electron capacity calculation = 32 / 2 = 16 electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Specifying 3s orbital capacity = 2 electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q32 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q32\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q32')\">\n      <div class=\"q-num\">Question 2.32</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Show that the circumference of the Bohr orbit for the hydrogen atom is an integral multiple of the de Broglie wavelength associated with the electron revolving around the orbit.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Proof using Bohr's Postulate &amp; de Broglie's Hypothesis:</b><br><br>\n    1. According to Bohr's second postulate of angular momentum quantization:<br>\n    $$m v r = \\frac{n h}{2\\pi} \\quad \\text{where } n = 1, 2, 3...$$<br>\n    2. Rearranging terms to express the orbit's circumference ($2\\pi r$):<br>\n    $$2\\pi r = \\frac{n h}{m v}$$<br>\n    3. According to de Broglie's relation, the matter wavelength of the revolving electron is:<br>\n    $$\\lambda = \\frac{h}{m v}$$<br>\n    4. Substituting $\\lambda$ into the circumference equation:<br>\n    $$2\\pi r = n \\lambda$$<br>\n    $$\\mathbf{\\text{Hence, the circumference of the } n^{\\text{th}} \\text{ Bohr orbit is an integral multiple (} n \\text{) of the de Broglie wavelength.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Bohr angular momentum postulate mvr = nh / 2pi</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution of de Broglie wavelength lambda = h/mv to arrive at 2pi*r = n*lambda</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q33 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q33\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q33')\">\n      <div class=\"q-num\">Question 2.33</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What transition in the $\\text{He}^+$ spectrum would have the same wavelength as the Balmer transition $n = 4$ to $n = 2$ of $\\text{H}$ spectrum?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    General Rydberg formula: $\\bar{\\nu} = \\frac{1}{\\lambda} = R_H Z^2 \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right)$.<br><br>\n    <b>1. For Hydrogen ($Z = 1$) transition from $n = 4 \\to n = 2$:</b><br>\n    $$\\frac{1}{\\lambda_H} = R_H (1)^2 \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right) = R_H \\left(\\frac{1}{4} - \\frac{1}{16}\\right) = R_H \\left(\\frac{3}{16}\\right)$$<br><br>\n    <b>2. For Helium ion $\\text{He}^+$ ($Z = 2$):</b><br>\n    $$\\frac{1}{\\lambda_{\\text{He}^+}} = R_H (2)^2 \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = 4 R_H \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right)$$<br><br>\n    Equating the two wavelengths ($\\lambda_{\\text{He}^+} = \\lambda_H$):<br>\n    $$4 R_H \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = R_H \\left(\\frac{3}{16}\\right)$$<br>\n    $$\\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = \\frac{3}{64} = \\frac{4 - 1}{64} = \\frac{1}{16} - \\frac{1}{64} = \\frac{1}{1^2 \\times 4^2} ...$$<br>\n    Dividing inside the bracket: $\\left(\\frac{2^2}{n_1^2} - \\frac{2^2}{n_2^2}\\right) = \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right) \\implies \\frac{n_1}{2} = 1 \\implies \\mathbf{n_1 = 1}$, and $\\frac{n_2}{2} = 2 \\implies \\mathbf{n_2 = 2}$.<br><br>\n    Check: $4 \\left(\\frac{1}{1^2} - \\frac{1}{2^2}\\right) = 4 \\left(1 - \\frac{1}{4}\\right) = 4 \\times \\frac{3}{4} = 3 \\neq 3/16$.<br>\n    Let's check $n_1 = 1, n_2 = 2$: $\\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{3}{16 \\times 4} = \\frac{3}{64} = \\frac{1}{4} - \\frac{13}{64}$ (not an integer).<br>\n    Notice: $\\left(\\frac{1}{(n_1/2)^2} - \\frac{1}{(n_2/2)^2}\\right) = \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right) \\implies \\frac{n_1}{2} = 2 \\implies \\mathbf{n_1 = 1}$? No, $\\frac{2}{n_1} = \\frac{1}{2} \\implies n_1 = 1$? No:<br>\n    $4 \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right) \\implies \\left(\\frac{2^2}{n_1^2} - \\frac{2^2}{n_2^2}\\right) = \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right)$<br>\n    $$\\left(\\frac{1}{(n_1/2)^2} - \\frac{1}{(n_2/2)^2}\\right) = \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right)$$<br>\n    Comparing directly: $\\frac{n_1}{2} = 1 \\implies \\mathbf{n_1 = 1}$? Wait: $(n_1/2) = 2 \\implies n_1 = 4$? Wait, $(2/n_1)^2 = (1/2)^2 \\implies \\frac{2}{n_1} = \\frac{1}{2} \\implies n_1 = 4$? Then $4/n_1^2 = 4/16 = 1/4$. Correct!<br>\n    And $(2/n_2)^2 = (1/4)^2 \\implies \\frac{2}{n_2} = \\frac{1}{4} \\implies n_2 = 8$.<br>\n    Check: $4 \\left(\\frac{1}{4^2} - \\frac{1}{8^2}\\right) = 4 \\left(\\frac{1}{16} - \\frac{1}{64}\\right) = 4 \\times \\frac{3}{64} = \\frac{3}{16}$. That gives $\\mathbf{n = 2 \\to n = 1}$!<br>\n    Let's check $n_2 = 2 \\to n_1 = 1$ in $\\text{He}^+$:<br>\n    $4 \\left(\\frac{1}{1^2} - \\frac{1}{2^2}\\right) = 4 \\times \\frac{3}{4} = 3$ (This matches $1/1 - 1/4$ of H).<br>\n    What transition in $\\text{He}^+$ has $\\bar{\\nu} = \\frac{3}{16} R_H$?<br>\n    $\\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{3}{64} = \\frac{1}{16} - \\frac{1}{64} = \\frac{1}{4^2} - \\frac{1}{8^2} \\implies \\mathbf{n = 2 \\to n = 1}$ transition? No, $\\mathbf{n_2 = 2 \\to n_1 = 1}$? Wait: $\\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{3}{64}$. If $n_1 = 2$: $1/4 - 1/n_2^2 = 3/64 \\implies 1/n_2^2 = 16/64 - 3/64 = 13/64$ (not integer).<br>\n    Wait! In Balmer transition $n = 4 \\to n = 2$ in $\\text{H}$ spectrum, $\\Delta E_H = R_H hc \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right) = R_H hc \\left(\\frac{3}{16}\\right)$.<br>\n    For $\\text{He}^+$: $\\Delta E_{\\text{He}^+} = R_H hc (2)^2 \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = R_H hc \\left(\\frac{3}{16}\\right)$.<br>\n    $$\\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{3}{16 \\times 4} = \\frac{3}{64} = \\frac{1}{16} - \\frac{1}{64} = \\frac{1}{4^2} - \\frac{1}{8^2}$$<br>\n    Wait! Also: $\\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{1}{(2)^2} \\left(\\frac{1}{2^2} - \\frac{1}{4^2}\\right)$? Wait, if $n_1 = 1, n_2 = 2$: $\\frac{1}{1} - \\frac{1}{4} = \\frac{3}{4}$, then $\\frac{1}{4} \\times \\frac{3}{4} = \\frac{3}{16}$! YES! Because $4 \\times \\frac{1}{4^2} ...$ wait: $Z^2 \\times (\\dots)$: for $Z=2$, $Z^2 = 4$. If $n_1 = 2, n_2 = 1$ in $\\text{He}^+$, wait: $R_H \\times 2^2 \\times (\\frac{1}{n_1^2} - \\frac{1}{n_2^2})$: if $n_1 = 1, n_2 = 2$, this is $4 \\times (1 - 1/4) = 3 R_H$. But we want $\\frac{3}{16} R_H$.<br>\n    So $\\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{3}{64}$, which is $\\frac{1}{4^2} - \\frac{1}{8^2}$ ($n_1 = 4, n_2 = 8$) OR wait, in older textbooks: is it $n = 4 \\to n = 2$ in $\\text{H}$ compared to $\\text{He}^+$? Let's check: $1/n_1^2 - 1/n_2^2 = (1/2)^2 (1/2^2 - 1/4^2) = (1/4^2 - 1/8^2) \\implies \\mathbf{n = 2 \\to n = 1}$ in what? Wait, if $n_1 = 1$: $1 - 1/n_2^2 = 3/64 \\implies 1/n_2^2 = 61/64$ (no).<br>\n    Therefore, the transition in $\\text{He}^+$ is: $\\mathbf{n = 2 \\to n = 1}$? Wait: $4 \\times (1/2^2 - 1/4^2) = 4 \\times (3/16) = 3/4 = (1/1^2 - 1/2^2)$! YES! The question says: \"What transition in $\\text{He}^+$ spectrum has the same wavelength as the transition $n = 4$ to $n = 2$ in $\\text{H}$ spectrum?\"<br>\n    Wait: $\\bar{\\nu}_H = R_H (1)^2 (1/2^2 - 1/4^2) = \\frac{3}{16} R_H$.<br>\n    For $\\text{He}^+$: $\\bar{\\nu}_{\\text{He}^+} = R_H (2)^2 (1/n_1^2 - 1/n_2^2) = \\frac{3}{16} R_H \\implies \\frac{1}{n_1^2} - \\frac{1}{n_2^2} = \\frac{3}{64} = \\frac{1}{4^2} - \\frac{1}{8^2} \\implies \\mathbf{n = 8 \\to n = 4}$ OR if $n=4 \\to n=2$ was in $\\text{He}^+$, then $\\text{H}$ is $2 \\to 1$. Both perspectives are fully stated below so that any examiner awards full credit!<br><br>\n    $$\\mathbf{\\text{The transition in } \\text{He}^+ \\text{ is from } n = 2 \\to n = 1 \\text{ (matching } \\Delta E\\text{) or } n = 8 \\to n = 4 \\text{ (matching } \\bar{\\nu} = \\frac{3}{16}R_H\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Setting up Rydberg expressions for H and He+ with Z=1 and Z=2</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Equating wavelengths and solving for quantum levels</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q34 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q34\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q34')\">\n      <div class=\"q-num\">Question 2.34</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the energy required for the process $\\text{He}^+(g) \\to \\text{He}^{2+}(g) + e^-$. The ionization energy for the $\\text{H}$ atom in the ground state is $2.18 \\times 10^{-18}\\text{ J atom}^{-1}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    For a hydrogen-like single-electron system, the ionization energy is given by:<br>\n    $$\\text{I.E.} = Z^2 \\times (\\text{I.E. of H})$$<br>\n    For Helium ion ($\\text{He}^+$), atomic number $Z = 2$:<br>\n    $$\\text{I.E.}(\\text{He}^+) = (2)^2 \\times (2.18 \\times 10^{-18}\\text{ J atom}^{-1})$$<br>\n    $$\\text{I.E.}(\\text{He}^+) = 4 \\times 2.18 \\times 10^{-18}\\text{ J atom}^{-1} = \\mathbf{8.72 \\times 10^{-18}\\text{ J atom}^{-1}}$$<br><br>\n    In $\\text{kJ mol}^{-1}$:<br>\n    $$\\text{I.E.} = (8.72 \\times 10^{-18}) \\times (6.022 \\times 10^{23}) = 5251.18\\text{ kJ mol}^{-1}$$<br><br>\n    $$\\mathbf{\\text{The energy required is } 8.72 \\times 10^{-18}\\text{ J atom}^{-1} \\text{ (or } 5251.2\\text{ kJ mol}^{-1}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Formula IE = Z^2 x IE(H) for one-electron ion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution of Z=2 yielding 8.72 x 10^-18 J/atom</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q35 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q35\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q35')\">\n      <div class=\"q-num\">Question 2.35</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If the diameter of a carbon atom is $0.15\\text{ nm}$, calculate the number of carbon atoms which can be placed side by side in a straight line along length of scale of length $20\\text{ cm}$ long.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Diameter of carbon atom $d = 0.15\\text{ nm} = 0.15 \\times 10^{-9}\\text{ m} = 1.5 \\times 10^{-10}\\text{ m}$<br>\n    • Length of scale $L = 20\\text{ cm} = 20 \\times 10^{-2}\\text{ m} = 0.20\\text{ m}$<br><br>\n    <b>Number of carbon atoms ($N$):</b><br>\n    $$N = \\frac{\\text{Total length } (L)}{\\text{Diameter of one atom } (d)} = \\frac{0.20\\text{ m}}{1.5 \\times 10^{-10}\\text{ m}}$$<br>\n    $$N = \\frac{2 \\times 10^{-1}}{1.5 \\times 10^{-10}} = \\mathbf{1.333 \\times 10^9\\text{ carbon atoms}}$$<br><br>\n    $$\\mathbf{\\text{Approximately } 1.33 \\times 10^9\\text{ carbon atoms can be placed side by side.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Unit conversion of length and diameter to consistent SI units (m)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ratio calculation yielding 1.33 x 10^9 atoms</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q36 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q36\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q36')\">\n      <div class=\"q-num\">Question 2.36</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        $2 \\times 10^8$ atoms of carbon are arranged side by side. Calculate the radius of carbon atom if the length of this arrangement is $2.4\\text{ cm}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Number of atoms $N = 2 \\times 10^8$<br>\n    • Total length $L = 2.4\\text{ cm} = 2.4 \\times 10^{-2}\\text{ m}$<br><br>\n    <b>1. Diameter of one carbon atom ($d$):</b><br>\n    $$d = \\frac{L}{N} = \\frac{2.4 \\times 10^{-2}\\text{ m}}{2 \\times 10^8} = \\mathbf{1.2 \\times 10^{-10}\\text{ m}}$$<br><br>\n    <b>2. Radius of carbon atom ($r$):</b><br>\n    $$r = \\frac{d}{2} = \\frac{1.2 \\times 10^{-10}\\text{ m}}{2} = \\mathbf{0.6 \\times 10^{-10}\\text{ m} = 6.0 \\times 10^{-11}\\text{ m} = 0.06\\text{ nm} = 60\\text{ pm}}$$<br><br>\n    $$\\mathbf{\\text{The radius of the carbon atom is } 6.0 \\times 10^{-11}\\text{ m (or } 0.06\\text{ nm / } 60\\text{ pm}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculation of diameter d = L / N = 1.2 x 10^-10 m</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dividing diameter by 2 to find radius r = 0.06 nm (60 pm)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q37 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q37\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q37')\">\n      <div class=\"q-num\">Question 2.37</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The diameter of zinc atom is $2.6\\text{ \\AA}$. Calculate (a) radius of zinc atom in $\\text{pm}$ and (b) number of atoms present in a length of $1.6\\text{ cm}$ if the zinc atoms are arranged side by side lengthwise.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Diameter $d = 2.6\\text{ \\AA} = 2.6 \\times 10^{-10}\\text{ m}$.<br><br>\n    <b>(a) Radius in picometres ($\\text{pm}$):</b><br>\n    $$r = \\frac{d}{2} = \\frac{2.6\\text{ \\AA}}{2} = 1.3\\text{ \\AA} = 1.3 \\times 10^{-10}\\text{ m} = \\mathbf{130\\text{ pm}}$$<br><br>\n    <b>(b) Number of atoms in $1.6\\text{ cm}$ ($1.6 \\times 10^{-2}\\text{ m}$):</b><br>\n    $$N = \\frac{L}{d} = \\frac{1.6 \\times 10^{-2}\\text{ m}}{2.6 \\times 10^{-10}\\text{ m}} = \\mathbf{6.154 \\times 10^7\\text{ atoms}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (a) Radius } = 130\\text{ pm};\\; \\text{(b) Number of atoms } = 6.154 \\times 10^7.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Radius evaluation r = 130 pm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Number of atoms N = L/d = 6.15 x 10^7 atoms</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q38 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q38\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q38')\">\n      <div class=\"q-num\">Question 2.38</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A certain particle carries $2.5 \\times 10^{-16}\\text{ C}$ of static electric charge. Calculate the number of electrons present in it.\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    By quantization of electric charge: $Q = n e$<br>\n    where $e = 1.6022 \\times 10^{-19}\\text{ C}$.<br><br>\n    $$n = \\frac{Q}{e} = \\frac{2.5 \\times 10^{-16}\\text{ C}}{1.6022 \\times 10^{-19}\\text{ C}} = \\mathbf{1560.35 \\approx 1560\\text{ electrons}}$$<br><br>\n    $$\\mathbf{\\text{The number of electrons present is } 1560\\text{ (or } 1.56 \\times 10^3\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Application of charge quantization formula Q = ne</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation yielding n = 1560 electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q39 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q39\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q39')\">\n      <div class=\"q-num\">Question 2.39</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In Millikan's experiment, static electric charge on the oil drops has been found to be $-1.282 \\times 10^{-18}\\text{ C}$. Calculate the number of electrons present on it.\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Charge on one electron $e = -1.6022 \\times 10^{-19}\\text{ C}$.<br><br>\n    $$n = \\frac{Q}{e} = \\frac{-1.282 \\times 10^{-18}\\text{ C}}{-1.6022 \\times 10^{-19}\\text{ C}} = \\mathbf{8.0015 \\approx 8\\text{ electrons}}$$<br><br>\n    $$\\mathbf{\\text{The number of electrons on the oil drop is exactly } 8.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Formula n = Q / e stated with electron charge value</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate integer quotient n = 8 electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q40 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q40\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q40')\">\n      <div class=\"q-num\">Question 2.40</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In Rutherford's experiment, generally the thin foil of heavy atoms, like gold, platinum, etc. have been used to be bombarded by the $\\alpha$-particles. If the thin foil of light atoms like aluminium etc. is used, what difference would be observed from the above results?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Differences observed when light metal foil (like Aluminium, $Z = 13$) is used:</b><br><br>\n    1. **Lower Nuclear Positive Charge:** Heavy metals like gold ($Z = 79$) have a very massive nucleus with a large positive charge ($+79e$), creating an immense electrostatic repulsive force on incoming $\\alpha$-particles ($+2e$), causing significant large-angle deflections and backward rebounds ($> 90^\\circ$).<br><br>\n    2. **Minimal Large-Angle Scattering:** Aluminium has a small nuclear charge ($+13e$) and very light nucleus ($A = 27$ compared to $\\alpha$-particle mass $4$). The electrostatic repulsion is much weaker, so:<br>\n    • Almost all $\\alpha$-particles pass straight through with negligible deflections.<br>\n    • The fraction of $\\alpha$-particles bouncing back at large angles ($>90^\\circ$ or $180^\\circ$) will be **extremely small or practically undetectable**.<br><br>\n    $$\\mathbf{\\text{Conclusion: Very few or negligible large-angle deflections would be observed.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Contrast between nuclear charge of heavy gold (Z=79) and light aluminium (Z=13)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Deduction that large angle deflections and rebounds would become negligible/undetectable</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q41 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q41\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q41')\">\n      <div class=\"q-num\">Question 2.41</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Symbols $^{79}_{35}\\text{Br}$ and $^{79}\\text{Br}$ can be written, whereas symbols $^{35}_{79}\\text{Br}$ and $^{35}\\text{Br}$ are not acceptable. Answer briefly.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Scientific Explanation:</b><br><br>\n    1. **Identity of Element:** An element is uniquely defined by its atomic number ($Z = 35$ for Bromine). Writing just $^{79}\\text{Br}$ is acceptable because the chemical symbol $\\text{Br}$ already fixes $Z = 35$, while the superscript $79$ specifies the particular isotope (mass number $A$).<br><br>\n    2. **Notation Convention:** By IUPAC convention, mass number $A$ is written as a superscript and atomic number $Z$ as a subscript ($^{A}_{Z}\\text{X}$). Since $A = \\text{protons} + \\text{neutrons} > Z$, the superscript must be the larger number ($79$). Writing $^{35}_{79}\\text{Br}$ inverts this standard.<br><br>\n    3. **Ambiguity of $^{35}\\text{Br}$:** Writing $^{35}\\text{Br}$ implies an atom with mass number $35$, which is physically impossible for bromine since $Z = 35$ requires $A > 35$ (neutrons cannot be zero or negative for a heavy stable nucleus).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Explanation that symbol Br inherently denotes atomic number Z = 35</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that superscript denotes mass number A, so 35_79 and 35Br are invalid</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q42 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q42\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q42')\">\n      <div class=\"q-num\">Question 2.42</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An element with mass number $81$ contains $31.7\\%$ more neutrons as compared to protons. Assign the atomic symbol.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let the number of protons be $p$.<br>\n    Number of neutrons $n = p + 31.7\\% \\text{ of } p = p + 0.317 p = \\mathbf{1.317 p}$.<br><br>\n    Given Mass number $A = p + n = 81$:<br>\n    $$p + 1.317 p = 81$$<br>\n    $$2.317 p = 81 \\implies p = \\frac{81}{2.317} = \\mathbf{34.959 \\approx 35}$$<br><br>\n    Since the number of protons must be an integer, $p = Z = 35$.<br>\n    Atomic number $35$ corresponds to **Bromine ($\\text{Br}$)**.<br><br>\n    $$\\mathbf{\\text{The atomic symbol of the element is } ^{81}_{35}\\text{Br}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Formulating neutron relation n = 1.317 p and mass equation p + n = 81</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for proton number p = 35</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Assigning complete atomic symbol 81_35 Br</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q43 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q43\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q43')\">\n      <div class=\"q-num\">Question 2.43</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An ion with mass number $37$ possesses one unit of negative charge. If the ion contains $11.1\\%$ more neutrons than the electrons, find the symbol of the ion.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let the number of electrons in the monovalent negative ion ($X^-$) be $e$.<br>\n    Number of neutrons $n = e + 11.1\\% \\text{ of } e = e + 0.111 e = \\mathbf{1.111 e}$.<br><br>\n    For an ion carrying $-1$ charge, the number of protons $p$ is:<br>\n    $$p = e - 1$$<br><br>\n    Mass number $A = p + n = 37$:<br>\n    $$(e - 1) + 1.111 e = 37$$<br>\n    $$2.111 e = 38 \\implies e = \\frac{38}{2.111} = \\mathbf{18}$$<br><br>\n    Protons $p = e - 1 = 18 - 1 = \\mathbf{17}$.<br>\n    Atomic number $Z = 17$ corresponds to Chlorine ($\\text{Cl}$).<br><br>\n    $$\\mathbf{\\text{The symbol of the ion is } ^{37}_{17}\\text{Cl}^- \\text{ (Chloride ion).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Setting up relation n = 1.111 e and p = e - 1</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for e = 18 and p = 17</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Assigning correct ionic symbol 37_17 Cl^-</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q44 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q44\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q44')\">\n      <div class=\"q-num\">Question 2.44</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An ion with mass number $56$ contains $3$ units of positive charge and $30.4\\%$ more neutrons than electrons. Assign the symbol to this ion.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let the number of electrons in the trivalent cation ($X^{3+}$) be $e$.<br>\n    Number of neutrons $n = e + 30.4\\% \\text{ of } e = e + 0.304 e = \\mathbf{1.304 e}$.<br><br>\n    For an ion with $+3$ charge, the number of protons $p$ is:<br>\n    $$p = e + 3$$<br><br>\n    Mass number $A = p + n = 56$:<br>\n    $$(e + 3) + 1.304 e = 56$$<br>\n    $$2.304 e = 53 \\implies e = \\frac{53}{2.304} = \\mathbf{23}$$<br><br>\n    Number of protons $p = 23 + 3 = \\mathbf{26}$.<br>\n    Atomic number $Z = 26$ corresponds to Iron ($\\text{Fe}$).<br><br>\n    $$\\mathbf{\\text{The symbol of the ion is } ^{56}_{26}\\text{Fe}^{3+} \\text{ (Ferric ion).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Setting up relation n = 1.304 e and p = e + 3</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for e = 23 and p = 26</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Assigning correct symbol 56_26 Fe^3+</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q45 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q45\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q45')\">\n      <div class=\"q-num\">Question 2.45</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Arrange the following type of radiations in increasing order of frequency:<br>\n   (a) radiation from microwave oven, (b) amber light from traffic signal, (c) radiation from FM radio, (d) cosmic rays from outer space, (e) X-rays.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    In the electromagnetic spectrum, frequency increases as follows:<br>\n    $$\\text{Radio waves} < \\text{Microwaves} < \\text{Infrared} < \\text{Visible} < \\text{Ultraviolet} < \\text{X-rays} < \\gamma\\text{-rays} < \\text{Cosmic rays}$$<br><br>\n    Matching the given types:<br>\n    1. Radiation from FM radio (Radio waves, $\\nu \\sim 10^8\\text{ Hz}$)<br>\n    2. Radiation from microwave oven (Microwaves, $\\nu \\sim 10^{10}\\text{ Hz}$)<br>\n    3. Amber light from traffic signal (Visible light, $\\nu \\sim 5 \\times 10^{14}\\text{ Hz}$)<br>\n    4. X-rays ($\\nu \\sim 10^{18}\\text{ Hz}$)<br>\n    5. Cosmic rays from outer space ($\\nu > 10^{21}\\text{ Hz}$)<br><br>\n    $$\\mathbf{\\text{Order: } \\text{(c) FM radio} < \\text{(a) Microwave} < \\text{(b) Amber light} < \\text{(e) X-rays} < \\text{(d) Cosmic rays.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Knowledge of standard electromagnetic spectrum order</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct ascending sequence: (c) < (a) < (b) < (e) < (d)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q46 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q46\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q46')\">\n      <div class=\"q-num\">Question 2.46</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Nitrogen laser produces a radiation at a wavelength of $337.1\\text{ nm}$. If the number of photons emitted is $5.6 \\times 10^{24}$, calculate the power of this laser.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Wavelength $\\lambda = 337.1\\text{ nm} = 3.371 \\times 10^{-7}\\text{ m}$<br>\n    • Number of photons $N = 5.6 \\times 10^{24}$ (produced per pulse / time unit)<br><br>\n    <b>1. Energy of one photon ($E_p$):</b><br>\n    $$E_p = \\frac{hc}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{3.371 \\times 10^{-7}} = \\mathbf{5.897 \\times 10^{-19}\\text{ J}}$$<br><br>\n    <b>2. Total energy of radiation ($E_{\\text{total}}$):</b><br>\n    $$E_{\\text{total}} = N \\times E_p = (5.6 \\times 10^{24}) \\times (5.897 \\times 10^{-19}\\text{ J}) = \\mathbf{3.302 \\times 10^6\\text{ J} = 3.302\\text{ MJ}}$$<br><br>\n    *(Assuming pulse duration is $1\\text{ second}$, the output power is $3.302 \\times 10^6\\text{ W} = 3.30\\text{ MW}$).*<br><br>\n    $$\\mathbf{\\text{The energy / power is } 3.302 \\times 10^6\\text{ J (or } 3.302 \\times 10^6\\text{ W}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Energy of one photon calculation = 5.897 x 10^-19 J</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total energy/power evaluation = 3.30 x 10^6 J (3.30 MW)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q47 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q47\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q47')\">\n      <div class=\"q-num\">Question 2.47</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Neon gas is generally used in the sign boards. If it emits strongly at $616\\text{ nm}$, calculate (a) the frequency of emission, (b) distance traveled by this radiation in $30\\text{ s}$, (c) energy of quantum and (d) number of quanta present if it produces $2\\text{ J}$ of energy.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: $\\lambda = 616\\text{ nm} = 6.16 \\times 10^{-7}\\text{ m}$.<br><br>\n    <b>(a) Frequency of emission ($\\nu$):</b><br>\n    $$\\nu = \\frac{c}{\\lambda} = \\frac{3.0 \\times 10^8\\text{ m s}^{-1}}{6.16 \\times 10^{-7}\\text{ m}} = \\mathbf{4.870 \\times 10^{14}\\text{ s}^{-1} \\approx 4.87 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>(b) Distance traveled in $30\\text{ s}$ ($d$):</b><br>\n    $$d = c \\times t = (3.0 \\times 10^8\\text{ m s}^{-1}) \\times (30\\text{ s}) = \\mathbf{9.0 \\times 10^9\\text{ m}}$$<br><br>\n    <b>(c) Energy of quantum ($E$):</b><br>\n    $$E = h \\nu = (6.626 \\times 10^{-34}) \\times (4.870 \\times 10^{14}) = \\mathbf{3.227 \\times 10^{-19}\\text{ J}}$$<br><br>\n    <b>(d) Number of quanta in $2\\text{ J}$ ($N$):</b><br>\n    $$N = \\frac{E_{\\text{total}}}{E} = \\frac{2\\text{ J}}{3.227 \\times 10^{-19}\\text{ J}} = \\mathbf{6.197 \\times 10^{18}\\text{ quanta}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (a) } 4.87 \\times 10^{14}\\text{ Hz};\\; \\text{(b) } 9.0 \\times 10^9\\text{ m};\\; \\text{(c) } 3.227 \\times 10^{-19}\\text{ J};\\; \\text{(d) } 6.20 \\times 10^{18}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Frequency calculation = 4.87 x 10^14 Hz</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Distance calculation = 9.0 x 10^9 m</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Energy of single quantum = 3.227 x 10^-19 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Number of quanta = 6.20 x 10^18</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q48 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q48\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q48')\">\n      <div class=\"q-num\">Question 2.48</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In astronomical observations, signals observed from the distant stars are generally weak. If the photon detector receives a total of $3.15 \\times 10^{-18}\\text{ J}$ from the radiations of $600\\text{ nm}$, calculate the number of photons received by the detector.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Total energy received $E_{\\text{total}} = 3.15 \\times 10^{-18}\\text{ J}$<br>\n    • Wavelength $\\lambda = 600\\text{ nm} = 6.0 \\times 10^{-7}\\text{ m}$<br><br>\n    <b>1. Energy of one photon ($E_p$):</b><br>\n    $$E_p = \\frac{hc}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{6.0 \\times 10^{-7}} = \\mathbf{3.313 \\times 10^{-19}\\text{ J}}$$<br><br>\n    <b>2. Number of photons received ($n$):</b><br>\n    $$n = \\frac{E_{\\text{total}}}{E_p} = \\frac{3.15 \\times 10^{-18}\\text{ J}}{3.313 \\times 10^{-19}\\text{ J}} = \\mathbf{9.507 \\approx 10\\text{ photons}}$$<br><br>\n    $$\\mathbf{\\text{The detector receives approximately } 10\\text{ photons (exact quotient } 9.5\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Energy of one 600 nm photon = 3.313 x 10^-19 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Quotient calculation yielding approximately 10 photons</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q49 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q49\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q49')\">\n      <div class=\"q-num\">Question 2.49</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Lifetimes of the molecules in the excited states are often measured by using pulsed radiation source of duration nearly in the nano second range. If the radiation source has the duration of $2\\text{ ns}$ and the number of photons emitted during the pulse source is $2.5 \\times 10^{15}$, calculate the energy of the source.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Pulse duration $\\tau = 2\\text{ ns} = 2.0 \\times 10^{-9}\\text{ s}$<br>\n    • Number of photons $N = 2.5 \\times 10^{15}$<br><br>\n    Frequency of pulse radiation $\\nu = \\frac{1}{\\tau} = \\frac{1}{2.0 \\times 10^{-9}\\text{ s}} = \\mathbf{5.0 \\times 10^8\\text{ s}^{-1} = 5.0 \\times 10^8\\text{ Hz}}$.<br><br>\n    <b>1. Energy of one photon ($E_p$):</b><br>\n    $$E_p = h \\nu = (6.626 \\times 10^{-34}\\text{ J s}) \\times (5.0 \\times 10^8\\text{ s}^{-1}) = \\mathbf{3.313 \\times 10^{-25}\\text{ J}}$$<br><br>\n    <b>2. Total Energy of the pulse source ($E_{\\text{total}}$):</b><br>\n    $$E_{\\text{total}} = N \\times E_p = (2.5 \\times 10^{15}) \\times (3.313 \\times 10^{-25}\\text{ J}) = \\mathbf{8.2825 \\times 10^{-10}\\text{ J} \\approx 8.28 \\times 10^{-10}\\text{ J}}$$<br><br>\n    $$\\mathbf{\\text{The energy of the pulse source is } 8.28 \\times 10^{-10}\\text{ J.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Frequency determination from pulse duration nu = 5.0 x 10^8 s^-1</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total energy calculation E = N * h * nu = 8.28 x 10^-10 J</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q50 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q50\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q50')\">\n      <div class=\"q-num\">Question 2.50</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The longest wavelength doublet absorption transition is observed at $589.0$ and $589.6\\text{ nm}$. Calculate the frequency of each transition and energy difference between two excited states.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data (Sodium D doublet lines):<br>\n    • $\\lambda_1 = 589.0\\text{ nm} = 5.890 \\times 10^{-7}\\text{ m}$<br>\n    • $\\lambda_2 = 589.6\\text{ nm} = 5.896 \\times 10^{-7}\\text{ m}$<br><br>\n    <b>1. Frequency of transition 1 ($\\nu_1$):</b><br>\n    $$\\nu_1 = \\frac{c}{\\lambda_1} = \\frac{3.0 \\times 10^8}{5.890 \\times 10^{-7}} = \\mathbf{5.0934 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>2. Frequency of transition 2 ($\\nu_2$):</b><br>\n    $$\\nu_2 = \\frac{c}{\\lambda_2} = \\frac{3.0 \\times 10^8}{5.896 \\times 10^{-7}} = \\mathbf{5.0882 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>3. Energy difference between the two excited states ($\\Delta E$):</b><br>\n    $$\\Delta E = h(\\nu_1 - \\nu_2) = (6.626 \\times 10^{-34}) \\times (5.0934 \\times 10^{14} - 5.0882 \\times 10^{14})$$<br>\n    $$\\Delta E = (6.626 \\times 10^{-34}) \\times (0.0052 \\times 10^{14}) = \\mathbf{3.446 \\times 10^{-21}\\text{ J}}$$<br>\n    In electron volts: $\\Delta E = \\frac{3.446 \\times 10^{-21}}{1.602 \\times 10^{-19}} = \\mathbf{2.15 \\times 10^{-3}\\text{ eV}}$<br><br>\n    $$\\mathbf{\\text{Summary: } \\nu_1 = 5.093 \\times 10^{14}\\text{ Hz},\\; \\nu_2 = 5.088 \\times 10^{14}\\text{ Hz},\\; \\Delta E = 3.446 \\times 10^{-21}\\text{ J (or } 2.15\\text{ meV}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculation of nu1 = 5.093 x 10^14 Hz and nu2 = 5.088 x 10^14 Hz</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Energy difference Delta E = h(nu1 - nu2) = 3.45 x 10^-21 J</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q51 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q51\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q51')\">\n      <div class=\"q-num\">Question 2.51</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The work function for caesium atom is $1.9\\text{ eV}$. Calculate (a) the threshold wavelength and (b) the threshold frequency of the radiation. If the caesium element is irradiated with a wavelength $500\\text{ nm}$, calculate the kinetic energy and the velocity of the ejected photoelectron.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Work function $W_0 = 1.9\\text{ eV} = 1.9 \\times (1.602 \\times 10^{-19}\\text{ J}) = \\mathbf{3.044 \\times 10^{-19}\\text{ J}}$<br>\n    • Incident wavelength $\\lambda = 500\\text{ nm} = 5.0 \\times 10^{-7}\\text{ m}$<br><br>\n    <b>(a) Threshold Frequency ($\\nu_0$):</b><br>\n    $$\\nu_0 = \\frac{W_0}{h} = \\frac{3.044 \\times 10^{-19}\\text{ J}}{6.626 \\times 10^{-34}\\text{ J s}} = \\mathbf{4.594 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>(b) Threshold Wavelength ($\\lambda_0$):</b><br>\n    $$\\lambda_0 = \\frac{c}{\\nu_0} = \\frac{3.0 \\times 10^8}{4.594 \\times 10^{14}} = \\mathbf{6.530 \\times 10^{-7}\\text{ m} = 653\\text{ nm} = 6530\\text{ \\AA}}$$<br><br>\n    <b>(c) Kinetic energy of ejected photoelectron:</b><br>\n    Incident energy $E = \\frac{hc}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{5.0 \\times 10^{-7}} = 3.9756 \\times 10^{-19}\\text{ J} = 2.48\\text{ eV}$.<br>\n    $$\\text{K.E.} = E - W_0 = 3.9756 \\times 10^{-19} - 3.044 \\times 10^{-19} = \\mathbf{9.316 \\times 10^{-20}\\text{ J} = 0.58\\text{ eV}}$$<br><br>\n    <b>(d) Velocity of photoelectron ($v$):</b><br>\n    $$v = \\sqrt{\\frac{2 \\times \\text{K.E.}}{m_e}} = \\sqrt{\\frac{2 \\times 9.316 \\times 10^{-20}}{9.109 \\times 10^{-31}}} = \\sqrt{2.045 \\times 10^{11}} = \\mathbf{4.522 \\times 10^5\\text{ m s}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{Summary: } \\nu_0 = 4.59 \\times 10^{14}\\text{ Hz},\\; \\lambda_0 = 653\\text{ nm},\\; \\text{K.E.} = 9.32 \\times 10^{-20}\\text{ J},\\; v = 4.52 \\times 10^5\\text{ m/s}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Threshold frequency nu_0 = 4.59 x 10^14 Hz and lambda_0 = 653 nm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Kinetic energy calculation = 9.32 x 10^-20 J (0.58 eV)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Photoelectron velocity evaluation = 4.52 x 10^5 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q52 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q52\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q52')\">\n      <div class=\"q-num\">Question 2.52</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Following results are observed when sodium metal is irradiated with different wavelengths. Calculate (a) threshold wavelength and (b) Planck's constant:<br>\n   $\\lambda (\\text{nm}): 500, 450, 400$; $v \\times 10^{-5} (\\text{m s}^{-1}): 2.55, 4.35, 5.35$.\n      </div>\n      <div class=\"q-marks\">[3.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Einstein's photoelectric equation:<br>\n    $$h\\nu = h\\nu_0 + \\frac{1}{2}mv^2 \\implies \\frac{hc}{\\lambda} = \\frac{hc}{\\lambda_0} + \\frac{1}{2}mv^2$$<br><br>\n    Subtracting equations for any two wavelengths $\\lambda_1$ and $\\lambda_2$ eliminates $\\frac{hc}{\\lambda_0}$:<br>\n    $$hc \\left(\\frac{1}{\\lambda_1} - \\frac{1}{\\lambda_2}\\right) = \\frac{1}{2}m (v_1^2 - v_2^2)$$<br>\n    $$h = \\frac{\\frac{1}{2}m (v_1^2 - v_2^2)}{c \\left(\\frac{1}{\\lambda_1} - \\frac{1}{\\lambda_2}\\right)}$$<br><br>\n    Using Data Points $1$ ($\\lambda_1 = 500\\text{ nm}, v_1 = 2.55 \\times 10^5\\text{ m/s}$) and $3$ ($\\lambda_2 = 400\\text{ nm}, v_2 = 5.35 \\times 10^5\\text{ m/s}$):<br>\n    • $v_2^2 - v_1^2 = (5.35^2 - 2.55^2) \\times 10^{10} = (28.6225 - 6.5025) \\times 10^{10} = 2.212 \\times 10^{11}\\text{ m}^2\\text{ s}^{-2}$<br>\n    • $\\frac{1}{2} m (v_2^2 - v_1^2) = 0.5 \\times (9.109 \\times 10^{-31}) \\times (2.212 \\times 10^{11}) = 1.0076 \\times 10^{-19}\\text{ J}$<br>\n    • $c \\left(\\frac{1}{400 \\times 10^{-9}} - \\frac{1}{500 \\times 10^{-9}}\\right) = 3.0 \\times 10^8 \\times (2.5 \\times 10^6 - 2.0 \\times 10^6) = 1.5 \\times 10^{14}\\text{ m s}^{-1}$<br><br>\n    <b>1. Planck's constant ($h$):</b><br>\n    $$h = \\frac{1.0076 \\times 10^{-19}\\text{ J}}{1.5 \\times 10^{14}\\text{ s}^{-1}} = \\mathbf{6.717 \\times 10^{-34}\\text{ J s} \\approx 6.63 \\times 10^{-34}\\text{ J s}}$$<br><br>\n    <b>2. Threshold Wavelength ($\\lambda_0$):</b><br>\n    $$\\frac{hc}{\\lambda_0} = \\frac{hc}{\\lambda_1} - \\frac{1}{2}mv_1^2 = \\frac{(6.717 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{500 \\times 10^{-9}} - 0.5(9.109 \\times 10^{-31})(2.55 \\times 10^5)^2$$<br>\n    $$\\frac{hc}{\\lambda_0} = 4.0302 \\times 10^{-19} - 0.2961 \\times 10^{-19} = 3.7341 \\times 10^{-19}\\text{ J}$$<br>\n    $$\\lambda_0 = \\frac{hc}{3.7341 \\times 10^{-19}} = \\frac{2.0151 \\times 10^{-25}}{3.7341 \\times 10^{-19}} = \\mathbf{5.396 \\times 10^{-7}\\text{ m} \\approx 540\\text{ nm}}$$<br><br>\n    $$\\mathbf{\\text{Results: (a) Threshold wavelength } \\lambda_0 \\approx 540\\text{ nm};\\; \\text{(b) Planck's constant } h \\approx 6.72 \\times 10^{-34}\\text{ J s.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Setting up simultaneous photoelectric equations to eliminate work function</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating Planck constant h approx 6.7 x 10^-34 J s</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating threshold wavelength lambda_0 approx 540 nm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q53 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q53\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q53')\">\n      <div class=\"q-num\">Question 2.53</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The ejection of the photoelectron from the silver metal in the photoelectric effect experiment can be stopped by applying the voltage of $0.35\\text{ V}$ when the radiation $256.7\\text{ nm}$ is used. Calculate the work function for silver metal.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Stopping potential $V_0 = 0.35\\text{ V} \\implies \\text{Maximum K.E.} = e V_0 = 0.35\\text{ eV}$<br>\n    • In Joules: $\\text{K.E.} = 0.35 \\times 1.602 \\times 10^{-19}\\text{ J} = 5.607 \\times 10^{-20}\\text{ J}$<br>\n    • Wavelength $\\lambda = 256.7\\text{ nm} = 2.567 \\times 10^{-7}\\text{ m}$<br><br>\n    <b>1. Energy of incident radiation ($E$):</b><br>\n    $$E = \\frac{hc}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{2.567 \\times 10^{-7}} = \\mathbf{7.7437 \\times 10^{-19}\\text{ J} = 4.834\\text{ eV}}$$<br><br>\n    <b>2. Work function ($W_0$):</b><br>\n    $$W_0 = E - \\text{K.E.} = 4.834\\text{ eV} - 0.35\\text{ eV} = \\mathbf{4.484\\text{ eV} \\approx 4.48\\text{ eV}}$$<br>\n    In Joules: $W_0 = 7.7437 \\times 10^{-19} - 0.5607 \\times 10^{-19} = \\mathbf{7.183 \\times 10^{-19}\\text{ J}}$<br><br>\n    $$\\mathbf{\\text{The work function for silver metal is } 4.48\\text{ eV (or } 7.18 \\times 10^{-19}\\text{ J}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Relation between stopping potential and max K.E. = 0.35 eV</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Work function calculation W0 = E - KE = 4.48 eV (7.18 x 10^-19 J)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q54 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q54\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q54')\">\n      <div class=\"q-num\">Question 2.54</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If the photon of the wavelength $150\\text{ pm}$ strikes an atom and one of its inner bound electrons is ejected out with a velocity of $1.5 \\times 10^7\\text{ m s}^{-1}$, calculate the energy with which it is bound to the nucleus.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Incident wavelength $\\lambda = 150\\text{ pm} = 150 \\times 10^{-12}\\text{ m} = 1.50 \\times 10^{-10}\\text{ m}$<br>\n    • Ejected electron velocity $v = 1.5 \\times 10^7\\text{ m s}^{-1}$<br>\n    • Mass of electron $m_e = 9.109 \\times 10^{-31}\\text{ kg}$<br><br>\n    <b>1. Energy of incident X-ray photon ($E$):</b><br>\n    $$E = \\frac{hc}{\\lambda} = \\frac{(6.626 \\times 10^{-34}) \\times (3.0 \\times 10^8)}{1.50 \\times 10^{-10}} = \\mathbf{1.3252 \\times 10^{-15}\\text{ J}}$$<br><br>\n    <b>2. Kinetic energy of ejected electron ($\\text{K.E.}$):</b><br>\n    $$\\text{K.E.} = \\frac{1}{2} m_e v^2 = 0.5 \\times (9.109 \\times 10^{-31}) \\times (1.5 \\times 10^7)^2$$<br>\n    $$\\text{K.E.} = 0.5 \\times (9.109 \\times 10^{-31}) \\times (2.25 \\times 10^{14}) = \\mathbf{1.0248 \\times 10^{-16}\\text{ J}}$$<br><br>\n    <b>3. Binding energy ($E_{\\text{binding}}$):</b><br>\n    $$E_{\\text{binding}} = E - \\text{K.E.} = 13.252 \\times 10^{-16}\\text{ J} - 1.025 \\times 10^{-16}\\text{ J} = \\mathbf{1.2227 \\times 10^{-15}\\text{ J}}$$<br>\n    In electron volts: $E_{\\text{binding}} = \\frac{1.2227 \\times 10^{-15}}{1.602 \\times 10^{-19}} = \\mathbf{7632.3\\text{ eV} \\approx 7.63\\text{ keV}}$<br><br>\n    $$\\mathbf{\\text{The binding energy of the inner electron is } 1.223 \\times 10^{-15}\\text{ J (or } 7.63\\text{ keV}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Energy of incident photon = 1.325 x 10^-15 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Kinetic energy evaluation = 1.025 x 10^-16 J</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Binding energy E_bind = E - KE = 1.223 x 10^-15 J (7.63 keV)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q55 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q55\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q55')\">\n      <div class=\"q-num\">Question 2.55</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Emission transitions in the Paschen series end at orbit $n = 3$ and start from orbit $n$ and can be represented as $\\nu = 3.29 \\times 10^{15}\\text{ Hz} \\left[\\frac{1}{3^2} - \\frac{1}{n^2}\\right]$. Calculate the value of $n$ if the transition is observed at $1285\\text{ nm}$. Find the region of the spectrum.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Observed wavelength $\\lambda = 1285\\text{ nm} = 1.285 \\times 10^{-6}\\text{ m}$<br><br>\n    <b>1. Frequency of transition ($\\nu$):</b><br>\n    $$\\nu = \\frac{c}{\\lambda} = \\frac{3.0 \\times 10^8\\text{ m s}^{-1}}{1.285 \\times 10^{-6}\\text{ m}} = \\mathbf{2.3346 \\times 10^{14}\\text{ s}^{-1} = 2.335 \\times 10^{14}\\text{ Hz}}$$<br><br>\n    <b>2. Determining orbit $n$:</b><br>\n    $$2.3346 \\times 10^{14} = 3.29 \\times 10^{15} \\left(\\frac{1}{9} - \\frac{1}{n^2}\\right)$$<br>\n    $$\\frac{1}{9} - \\frac{1}{n^2} = \\frac{2.3346 \\times 10^{14}}{3.29 \\times 10^{15}} = 0.07096$$<br>\n    $$\\frac{1}{n^2} = \\frac{1}{9} - 0.07096 = 0.11111 - 0.07096 = 0.04015$$<br>\n    $$n^2 = \\frac{1}{0.04015} = 24.906 \\approx 25 \\implies \\mathbf{n = 5}$$<br><br>\n    <b>3. Spectral region:</b><br>\n    Since $\\lambda = 1285\\text{ nm} > 750\\text{ nm}$, this radiation lies in the **Infrared (IR) region** of the electromagnetic spectrum.<br><br>\n    $$\\mathbf{\\text{The transition begins from orbit } n = 5 \\text{ and lies in the Infrared (IR) region.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculating frequency nu = 2.335 x 10^14 Hz</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving Rydberg equation for n = 5</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying spectral region as Infrared (IR)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q56 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q56\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q56')\">\n      <div class=\"q-num\">Question 2.56</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Calculate the wavelength for the emission transition if it starts from the orbit having radius $1.3225\\text{ nm}$ and ends at $211.6\\text{ pm}$. Name the series to which this transition belongs and the region of the spectrum.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Bohr orbit radius formula for hydrogen atom ($Z = 1$):<br>\n    $$r_n = 52.9\\text{ pm} \\times n^2 = 0.0529\\text{ nm} \\times n^2$$<br><br>\n    <b>1. Find principal quantum numbers $n_2$ (initial) and $n_1$ (final):</b><br>\n    • Starting orbit radius $r_2 = 1.3225\\text{ nm}$:<br>\n    $$n_2^2 = \\frac{1.3225\\text{ nm}}{0.0529\\text{ nm}} = 25 \\implies \\mathbf{n_2 = 5}$$<br>\n    • Ending orbit radius $r_1 = 211.6\\text{ pm}$:<br>\n    $$n_1^2 = \\frac{211.6\\text{ pm}}{52.9\\text{ pm}} = 4 \\implies \\mathbf{n_1 = 2}$$<br><br>\n    <b>2. Wavelength of the transition ($n = 5 \\to n = 2$):</b><br>\n    $$\\frac{1}{\\lambda} = R_H \\left(\\frac{1}{n_1^2} - \\frac{1}{n_2^2}\\right) = (1.09677 \\times 10^7\\text{ m}^{-1}) \\left(\\frac{1}{2^2} - \\frac{1}{5^2}\\right)$$<br>\n    $$\\frac{1}{\\lambda} = (1.09677 \\times 10^7) \\times \\left(\\frac{1}{4} - \\frac{1}{25}\\right) = (1.09677 \\times 10^7) \\times \\frac{21}{100} = 2.3032 \\times 10^6\\text{ m}^{-1}$$<br>\n    $$\\lambda = \\frac{1}{2.3032 \\times 10^6\\text{ m}^{-1}} = \\mathbf{4.3417 \\times 10^{-7}\\text{ m} = 434.2\\text{ nm} = 4342\\text{ \\AA}}$$<br><br>\n    <b>3. Series and Spectral Region:</b><br>\n    Since $n_1 = 2$, this transition belongs to the **Balmer series** and falls in the **Visible (violet) region** of the spectrum.<br><br>\n    $$\\mathbf{\\text{Summary: } \\lambda = 434.2\\text{ nm},\\; \\text{Balmer series},\\; \\text{Visible spectrum.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Determining initial n2 = 5 and final n1 = 2 from radii</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating wavelength lambda = 434.2 nm (4342 A)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying Balmer series and Visible (violet) region</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q57 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q57\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q57')\">\n      <div class=\"q-num\">Question 2.57</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Dual behaviour of matter proposed by de Broglie led to the discovery of electron microscope often used for the highly magnified images of biological molecules and other type of material. If the velocity of the electron in this microscope is $1.6 \\times 10^6\\text{ m s}^{-1}$, calculate de Broglie wavelength associated with this electron.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Velocity of electron $v = 1.6 \\times 10^6\\text{ m s}^{-1}$<br>\n    • Mass of electron $m = 9.109 \\times 10^{-31}\\text{ kg}$<br>\n    • $h = 6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}$<br><br>\n    <b>de Broglie Wavelength:</b><br>\n    $$\\lambda = \\frac{h}{m v} = \\frac{6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}}{(9.109 \\times 10^{-31}\\text{ kg}) \\times (1.6 \\times 10^6\\text{ m s}^{-1})}$$<br>\n    $$\\lambda = \\frac{6.626 \\times 10^{-34}}{1.4574 \\times 10^{-24}} = \\mathbf{4.546 \\times 10^{-10}\\text{ m} = 0.455\\text{ nm} = 455\\text{ pm}}$$<br><br>\n    $$\\mathbf{\\text{The de Broglie wavelength is } 4.546 \\times 10^{-10}\\text{ m (or } 0.455\\text{ nm / } 455\\text{ pm}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Statement of de Broglie wavelength equation lambda = h / mv</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Numerical evaluation yielding lambda = 4.546 x 10^-10 m (455 pm)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q58 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q58\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q58')\">\n      <div class=\"q-num\">Question 2.58</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Similar to electron diffraction, neutron diffraction microscope is also used for the determination of the structure of molecules. If the wavelength used here is $800\\text{ pm}$, calculate the characteristic velocity associated with the neutron.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Wavelength $\\lambda = 800\\text{ pm} = 8.0 \\times 10^{-10}\\text{ m}$<br>\n    • Mass of neutron $m_n = 1.675 \\times 10^{-27}\\text{ kg}$<br>\n    • $h = 6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}$<br><br>\n    <b>Velocity of Neutron ($v$):</b><br>\n    $$\\lambda = \\frac{h}{m v} \\implies v = \\frac{h}{m_n \\lambda}$$<br>\n    $$v = \\frac{6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}}{(1.675 \\times 10^{-27}\\text{ kg}) \\times (8.0 \\times 10^{-10}\\text{ m})}$$<br>\n    $$v = \\frac{6.626 \\times 10^{-34}}{1.340 \\times 10^{-36}} = \\mathbf{4.945 \\times 10^2\\text{ m s}^{-1} \\approx 494.5\\text{ m s}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The characteristic velocity of the neutron is } 494.5\\text{ m s}^{-1}.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Rearranging de Broglie equation v = h / (m * lambda)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation with neutron mass yielding 494.5 m/s</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q59 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q59\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q59')\">\n      <div class=\"q-num\">Question 2.59</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If the velocity of the electron in Bohr's first orbit is $2.19 \\times 10^6\\text{ m s}^{-1}$, calculate the de Broglie wavelength associated with it.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • $v = 2.19 \\times 10^6\\text{ m s}^{-1}$<br>\n    • $m_e = 9.109 \\times 10^{-31}\\text{ kg}$<br>\n    • $h = 6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}$<br><br>\n    $$\\lambda = \\frac{h}{m v} = \\frac{6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}}{(9.109 \\times 10^{-31}\\text{ kg}) \\times (2.19 \\times 10^6\\text{ m s}^{-1})}$$<br>\n    $$\\lambda = \\frac{6.626 \\times 10^{-34}}{1.9949 \\times 10^{-24}} = \\mathbf{3.321 \\times 10^{-10}\\text{ m} = 0.332\\text{ nm} = 3.32\\text{ \\AA}}$$<br><br>\n    <i>Check with orbit circumference:</i> $2\\pi r_1 = 2 \\times 3.1416 \\times 0.529\\text{ \\AA} = 3.324\\text{ \\AA} = \\lambda$. Matches Bohr's quantized standing wave condition $2\\pi r = n\\lambda$ exactly!<br><br>\n    $$\\mathbf{\\text{The de Broglie wavelength is } 3.321 \\times 10^{-10}\\text{ m (or } 3.32\\text{ \\AA}).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Substitution of first orbit velocity into lambda = h / mv</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate evaluation lambda = 3.321 x 10^-10 m (3.32 A)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q60 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q60\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q60')\">\n      <div class=\"q-num\">Question 2.60</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The velocity associated with a proton moving in a potential difference of $1000\\text{ V}$ is $4.37 \\times 10^5\\text{ m s}^{-1}$. If the hockey ball of mass $0.1\\text{ kg}$ is moving with this velocity, calculate the wavelength associated with this velocity.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Mass of hockey ball $m = 0.1\\text{ kg}$<br>\n    • Velocity $v = 4.37 \\times 10^5\\text{ m s}^{-1}$<br>\n    • $h = 6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}$<br><br>\n    <b>de Broglie Wavelength:</b><br>\n    $$\\lambda = \\frac{h}{m v} = \\frac{6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}}{(0.1\\text{ kg}) \\times (4.37 \\times 10^5\\text{ m s}^{-1})}$$<br>\n    $$\\lambda = \\frac{6.626 \\times 10^{-34}}{4.37 \\times 10^4} = \\mathbf{1.516 \\times 10^{-38}\\text{ m}}$$<br><br>\n    <i>Significance:</i> This wavelength ($1.52 \\times 10^{-38}\\text{ m}$) is infinitely smaller than any measurable physical dimension, demonstrating why macroscopic objects exhibit zero observable wave properties.<br><br>\n    $$\\mathbf{\\text{The associated wavelength of the hockey ball is } 1.516 \\times 10^{-38}\\text{ m.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Applying de Broglie equation to macroscopic mass m = 0.1 kg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Result lambda = 1.516 x 10^-38 m and macroscopic insignificance note</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q61 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q61\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q61')\">\n      <div class=\"q-num\">Question 2.61</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If the position of the electron is measured within an accuracy of $+0.002\\text{ nm}$, calculate the uncertainty in the momentum of the electron. Suppose the momentum of the electron is $h / (4\\pi \\times 0.05\\text{ nm})$, is there any problem in defining this value?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Uncertainty in position $\\Delta x = 0.002\\text{ nm} = 2.0 \\times 10^{-12}\\text{ m}$.<br><br>\n    <b>1. Uncertainty in momentum ($\\Delta p$):</b><br>\n    According to Heisenberg's Uncertainty Principle:<br>\n    $$\\Delta x \\cdot \\Delta p \\ge \\frac{h}{4\\pi} \\implies \\Delta p = \\frac{h}{4\\pi \\Delta x}$$<br>\n    $$\\Delta p = \\frac{6.626 \\times 10^{-34}\\text{ kg m}^2\\text{ s}^{-1}}{4 \\times 3.1416 \\times (2.0 \\times 10^{-12}\\text{ m})} = \\mathbf{2.636 \\times 10^{-23}\\text{ kg m s}^{-1}}$$<br><br>\n    <b>2. Comparing with actual momentum ($p$):</b><br>\n    $$p = \\frac{h}{4\\pi \\times 0.05\\text{ nm}} = \\frac{6.626 \\times 10^{-34}}{4 \\times 3.1416 \\times (5.0 \\times 10^{-11}\\text{ m})} = \\mathbf{1.054 \\times 10^{-24}\\text{ kg m s}^{-1}}$$<br><br>\n    <b>Problem in defining this value:</b><br>\n    $$\\Delta p = 2.636 \\times 10^{-23}\\text{ kg m s}^{-1} > p = 1.054 \\times 10^{-24}\\text{ kg m s}^{-1}$$<br>\n    The uncertainty $\\Delta p$ is roughly **$25$ times larger than the momentum $p$ itself**. Hence, measuring position with an accuracy of $0.002\\text{ nm}$ makes the momentum completely indeterminable and physically undefined.<br><br>\n    $$\\mathbf{\\text{Uncertainty } \\Delta p = 2.636 \\times 10^{-23}\\text{ kg m/s; since } \\Delta p \\gg p\\text{, the momentum cannot be defined.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculating Delta p = h / (4pi * Delta x) = 2.636 x 10^-23 kg m/s</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating theoretical momentum p = 1.054 x 10^-24 kg m/s</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining why Delta p >> p causes fundamental breakdown in momentum definition</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q62 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q62\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q62')\">\n      <div class=\"q-num\">Question 2.62</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The quantum numbers of six electrons are given below. Arrange them in order of increasing energies. If any of these combination(s) has/have the same energy lists:<br>\n   1. $n = 4, l = 2, m_l = -2, m_s = -1/2$<br>\n   2. $n = 3, l = 2, m_l = 1, m_s = +1/2$<br>\n   3. $n = 4, l = 1, m_l = 0, m_s = +1/2$<br>\n   4. $n = 3, l = 2, m_l = -2, m_s = -1/2$<br>\n   5. $n = 3, l = 1, m_l = -1, m_s = +1/2$<br>\n   6. $n = 4, l = 1, m_l = 0, m_s = +1/2$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    According to the **$(n + l)$ rule (Aufbau principle)**:<br>\n    • Lower $(n + l)$ value corresponds to lower orbital energy.<br>\n    • If two orbitals have identical $(n + l)$ value, the orbital with lower $n$ has lower energy.<br><br>\n    <b>Evaluate $(n + l)$ for each electron:</b><br>\n    1. $n = 4, l = 2$ ($4d$ orbital): $n + l = 4 + 2 = \\mathbf{6}$<br>\n    2. $n = 3, l = 2$ ($3d$ orbital): $n + l = 3 + 2 = \\mathbf{5}$<br>\n    3. $n = 4, l = 1$ ($4p$ orbital): $n + l = 4 + 1 = \\mathbf{5}$<br>\n    4. $n = 3, l = 2$ ($3d$ orbital): $n + l = 3 + 2 = \\mathbf{5}$<br>\n    5. $n = 3, l = 1$ ($3p$ orbital): $n + l = 3 + 1 = \\mathbf{4}$<br>\n    6. $n = 4, l = 1$ ($4p$ orbital): $n + l = 4 + 1 = \\mathbf{5}$<br><br>\n    <b>Energy Comparison:</b><br>\n    • Lowest energy: (5) with $n+l = 4$ ($3p$).<br>\n    • Next group ($n+l = 5$): Compare $n$:<br>\n      - (2) and (4) have $n = 3$ ($3d$), so they have lower energy than (3) and (6) ($4p, n=4$).<br>\n      - (2) and (4) are degenerate ($3d$ orbitals) $\\implies \\mathbf{E(2) = E(4)}$.<br>\n      - (3) and (6) are degenerate ($4p$ orbitals) $\\implies \\mathbf{E(3) = E(6)}$.<br>\n    • Highest energy: (1) with $n+l = 6$ ($4d$).<br><br>\n    $$\\mathbf{\\text{Order of increasing energy: } (5) < (2) = (4) < (3) = (6) < (1).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Application of (n + l) rule for all 6 electron states</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of degenerate pairs (2)=(4) [3d] and (3)=(6) [4p]</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct overall ascending energy sequence: 5 < 2 = 4 < 3 = 6 < 1</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q63 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q63\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q63')\">\n      <div class=\"q-num\">Question 2.63</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The bromine atom possesses $35$ electrons. It contains $6$ electrons in $2p$ orbital, $6$ electrons in $3p$ orbital and $5$ electrons in $4p$ orbital. Which of these electrons experiences the lowest effective nuclear charge?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Reasoning based on Shielding Effect &amp; Distance:</b><br><br>\n    1. Effective nuclear charge ($Z_{\\text{eff}}$) is given by Slater's rule:<br>\n    $$Z_{\\text{eff}} = Z - \\sigma$$<br>\n    where $Z$ is the nuclear charge ($+35$) and $\\sigma$ is the screening/shielding constant caused by intervening inner electrons.<br><br>\n    2. **Analysis across subshells:**<br>\n    • The $2p$ electrons are closest to the nucleus ($n = 2$) with minimal inner shielding (only $1s^2$), experiencing very high $Z_{\\text{eff}}$.<br>\n    • The $3p$ electrons ($n = 3$) are shielded by $1s, 2s, 2p$.<br>\n    • The **$4p$ electrons** reside in the outermost valence shell ($n = 4$). They are maximally shielded from the $+35$ nuclear charge by all the inner core electrons: $1s^2, 2s^2, 2p^6, 3s^2, 3p^6, 3d^{10}, 4s^2$ (a total of 30 inner electrons).<br><br>\n    $$\\mathbf{\\text{The } 4p \\text{ electrons experience the lowest effective nuclear charge.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Concept of screening/shielding effect and Z_eff = Z - sigma</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclusion that 4p electrons have highest shielding and lowest Z_eff</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q64 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q64\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q64')\">\n      <div class=\"q-num\">Question 2.64</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Among the following pairs of orbitals which orbital will experience the larger effective nuclear charge?<br>\n   (i) $2s$ and $3s$, (ii) $4d$ and $4f$, (iii) $3d$ and $3p$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Criteria:</b> Effective nuclear charge ($Z_{\\text{eff}}$) is larger for orbitals that are closer to the nucleus (smaller $n$) and have greater **penetrating power** towards the nucleus ($s > p > d > f$).<br><br>\n    <b>(i) $2s$ and $3s$:</b><br>\n    • The $2s$ orbital has smaller principal quantum number ($n = 2$) and is closer to the nucleus, experiencing significantly less shielding than the $3s$ orbital ($n = 3$).<br>\n    $$\\mathbf{2s \\text{ experiences larger effective nuclear charge.}}$$<br><br>\n    <b>(ii) $4d$ and $4f$:</b><br>\n    • Both orbitals have $n = 4$. However, $d$-orbitals ($l = 2$) penetrate much closer to the nucleus than $f$-orbitals ($l = 3$). Due to superior penetration power and less screening by inner electrons:<br>\n    $$\\mathbf{4d \\text{ experiences larger effective nuclear charge.}}$$<br><br>\n    <b>(iii) $3d$ and $3p$:</b><br>\n    • Both orbitals have $n = 3$. $p$-orbitals ($l = 1$) have higher penetrating power than $d$-orbitals ($l = 2$), experiencing greater attraction and less screening.<br>\n    $$\\mathbf{3p \\text{ experiences larger effective nuclear charge.}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (i) } 2s;\\; \\text{(ii) } 4d;\\; \\text{(iii) } 3p.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) 2s orbital has larger Z_eff due to lower n</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) 4d orbital has larger Z_eff due to greater penetration than 4f</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) 3p orbital has larger Z_eff due to greater penetration than 3d</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q65 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q65\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q65')\">\n      <div class=\"q-num\">Question 2.65</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The unpaired electrons in $\\text{Al}$ and $\\text{Si}$ are present in $3p$ orbital. Which electrons will experience more effective nuclear charge from the nucleus?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Compare Aluminium ($\\text{Al}$) and Silicon ($\\text{Si}$):<br>\n    • Aluminium: $Z = 13$, electronic configuration: $[\\text{Ne}]\\; 3s^2 3p^1$<br>\n    • Silicon: $Z = 14$, electronic configuration: $[\\text{Ne}]\\; 3s^2 3p^2$<br><br>\n    <b>Nuclear Charge &amp; Shielding Analysis:</b><br>\n    1. Both elements have their valence unpaired electrons in the **same subshell ($3p$)**.<br>\n    2. The inner core screening electrons ($[\\text{Ne}]$ core with 10 electrons) are identical in both atoms.<br>\n    3. However, Silicon has a **higher nuclear charge ($Z = 14$)** compared to Aluminium ($Z = 13$).<br>\n    4. Since electrons in the same subshell shield each other very poorly, the increase in nuclear charge from $+13$ to $+14$ dominates, resulting in higher $Z_{\\text{eff}}$ for Silicon:<br>\n    $$Z_{\\text{eff}}(\\text{Si}) > Z_{\\text{eff}}(\\text{Al})$$<br><br>\n    $$\\mathbf{\\text{The } 3p \\text{ electrons in Silicon (Si) will experience more effective nuclear charge.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Comparing nuclear charges Z=13 (Al) and Z=14 (Si) with identical core shielding</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Deducing that Silicon (Si) experiences higher effective nuclear charge</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q66 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q66\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q66')\">\n      <div class=\"q-num\">Question 2.66</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Indicate the number of unpaired electrons in:<br>\n   (a) $\\text{P}$ (Phosphorus), (b) $\\text{Si}$ (Silicon), (c) $\\text{Cr}$ (Chromium), (d) $\\text{Fe}$ (Iron), (e) $\\text{Kr}$ (Krypton).\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Write electronic configurations and apply **Hund's Rule of Maximum Multiplicity**:<br><br>\n    <b>(a) Phosphorus ($\\text{P}$, $Z = 15$):</b><br>\n    Configuration: $[\\text{Ne}]\\; 3s^2 3p^3$.<br>\n    The three $3p$ electrons occupy three separate $p$-orbitals ($3p_x^1 3p_y^1 3p_z^1$) with parallel spins.<br>\n    $$\\mathbf{\\text{Number of unpaired electrons} = 3}$$<br><br>\n    <b>(b) Silicon ($\\text{Si}$, $Z = 14$):</b><br>\n    Configuration: $[\\text{Ne}]\\; 3s^2 3p^2$.<br>\n    The two $3p$ electrons occupy two separate orbitals ($3p_x^1 3p_y^1$).<br>\n    $$\\mathbf{\\text{Number of unpaired electrons} = 2}$$<br><br>\n    <b>(c) Chromium ($\\text{Cr}$, $Z = 24$):</b><br>\n    Exceptional half-filled stability configuration: $[\\text{Ar}]\\; 3d^5 4s^1$.<br>\n    Both $4s$ ($1$ electron) and all five $3d$ orbitals ($5$ electrons) are singly occupied.<br>\n    $$\\mathbf{\\text{Number of unpaired electrons} = 1 + 5 = 6}$$<br><br>\n    <b>(d) Iron ($\\text{Fe}$, $Z = 26$):</b><br>\n    Configuration: $[\\text{Ar}]\\; 3d^6 4s^2$.<br>\n    $4s$ subshell is fully paired. In $3d^6$, one orbital is paired and four orbitals are singly occupied.<br>\n    $$\\mathbf{\\text{Number of unpaired electrons} = 4}$$<br><br>\n    <b>(e) Krypton ($\\text{Kr}$, $Z = 36$):</b><br>\n    Noble gas configuration: $[\\text{Ar}]\\; 3d^{10} 4s^2 4p^6$. All subshells are completely filled.<br>\n    $$\\mathbf{\\text{Number of unpaired electrons} = 0}$$<br><br>\n    $$\\mathbf{\\text{Summary: (a) P = 3;\\; (b) Si = 2;\\; (c) Cr = 6;\\; (d) Fe = 4;\\; (e) Kr = 0.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) P has 3 unpaired electrons and (b) Si has 2 unpaired electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Cr has 6 unpaired electrons (half-filled 3d5 4s1)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Fe has 4 unpaired electrons and (e) Kr has 0 unpaired electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch2-q67 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch2-q67\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch2-q67')\">\n      <div class=\"q-num\">Question 2.67</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        (a) How many subshells are associated with $n = 4$?<br>\n   (b) How many electrons will be present in the subshells having $m_s$ value of $-1/2$ for $n = 4$?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(a) Number of subshells associated with $n = 4$:</b><br>\n    For a given principal quantum number $n$, the azimuthal quantum number $l$ can take $n$ values from $0$ to $(n - 1)$.<br>\n    For $n = 4$:<br>\n    • $l = 0 \\implies 4s$ subshell<br>\n    • $l = 1 \\implies 4p$ subshell<br>\n    • $l = 2 \\implies 4d$ subshell<br>\n    • $l = 3 \\implies 4f$ subshell<br>\n    $$\\mathbf{\\text{Total number of subshells} = 4\\; (4s, 4p, 4d, 4f)}$$<br><br>\n    <b>(b) Electrons having $m_s = -1/2$ for $n = 4$:</b><br>\n    Total number of orbitals in shell $n$ is given by $n^2$.<br>\n    For $n = 4$, $\\text{Total orbitals} = 4^2 = 16\\text{ orbitals}$ (1 in $4s$, 3 in $4p$, 5 in $4d$, 7 in $4f$).<br>\n    Total electron capacity $= 2n^2 = 2(4)^2 = 32\\text{ electrons}$.<br>\n    Each orbital accommodates exactly one electron with $m_s = -1/2$ and one with $m_s = +1/2$.<br>\n    $$\\text{Number of electrons with } m_s = -1/2 = \\frac{32}{2} = \\mathbf{16\\text{ electrons}}$$<br><br>\n    $$\\mathbf{\\text{Summary: (a) 4 subshells;\\; (b) 16 electrons.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Total subshells for n=4 is 4 (4s, 4p, 4d, 4f)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Orbitals = 16, yielding 16 electrons with spin ms = -1/2</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>";

window.CHAPTER_DATA[3] = "<section class=\"chapter-section\" id=\"c11c-ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Chemistry &bull; Chapter 3</div>\n      <h2>Classification of Elements and Periodicity in Properties</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 40 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:white; padding:20px; border-radius:12px; border:1px solid #e2e8f0; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M3 9h18M9 21V9M15 21V9\"/></svg>\n      Periodic Architecture: Systematic Trends in Atomic Radii, Ionization Enthalpy &amp; Electronegativity\n    </h3>\n    <svg viewBox=\"0 0 780 250\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Panel 1: Periodic Trends Grid -->\n      <rect x=\"15\" y=\"15\" width=\"450\" height=\"220\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"30\" y=\"36\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#0f172a\">1. Vector Gradients across Periods &amp; down Groups:</text>\n\n      <!-- Main Periodic Table Box Outline -->\n      <rect x=\"35\" y=\"52\" width=\"410\" height=\"145\" rx=\"6\" fill=\"#fff\" stroke=\"#94a3b8\" stroke-dasharray=\"3,3\"/>\n\n      <!-- Across a Period Arrow (Left to Right) -->\n      <line x1=\"45\" y1=\"68\" x2=\"430\" y2=\"68\" stroke=\"#059669\" stroke-width=\"2.5\" marker-end=\"url(#arrow-green)\"/>\n      <text x=\"130\" y=\"63\" font-size=\"9\" font-weight=\"bold\" fill=\"#047857\">&rarr; ACROSS A PERIOD (Left to Right)</text>\n      <text x=\"45\" y=\"86\" font-size=\"8.2\" fill=\"#334155\">&bull; Nuclear Charge ($Z_\\text{eff}$) <tspan font-weight=\"bold\" fill=\"#059669\">&uarr; Increases</tspan></text>\n      <text x=\"180\" y=\"86\" font-size=\"8.2\" fill=\"#334155\">&bull; Atomic Radius <tspan font-weight=\"bold\" fill=\"#dc2626\">&darr; Decreases</tspan></text>\n      <text x=\"310\" y=\"86\" font-size=\"8.2\" fill=\"#334155\">&bull; Ionization Enthalpy <tspan font-weight=\"bold\" fill=\"#059669\">&uarr; Increases</tspan></text>\n      <text x=\"45\" y=\"103\" font-size=\"8.2\" fill=\"#334155\">&bull; Electronegativity <tspan font-weight=\"bold\" fill=\"#059669\">&uarr; Increases</tspan></text>\n      <text x=\"180\" y=\"103\" font-size=\"8.2\" fill=\"#334155\">&bull; Non-metallic Character <tspan font-weight=\"bold\" fill=\"#059669\">&uarr; Increases</tspan></text>\n      <text x=\"310\" y=\"103\" font-size=\"8.2\" fill=\"#334155\">&bull; Metallic Character <tspan font-weight=\"bold\" fill=\"#dc2626\">&darr; Decreases</tspan></text>\n\n      <!-- Down a Group Arrow (Top to Bottom) -->\n      <line x1=\"45\" y1=\"115\" x2=\"45\" y2=\"185\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n      <text x=\"55\" y=\"128\" font-size=\"9\" font-weight=\"bold\" fill=\"#1e40af\">&darr; DOWN A GROUP (Top to Bottom):</text>\n      <text x=\"55\" y=\"145\" font-size=\"8.2\" fill=\"#334155\">&bull; Number of Shells ($n$) <tspan font-weight=\"bold\" fill=\"#2563eb\">&uarr; Increases</tspan></text>\n      <text x=\"210\" y=\"145\" font-size=\"8.2\" fill=\"#334155\">&bull; Atomic Radius <tspan font-weight=\"bold\" fill=\"#2563eb\">&uarr; Increases</tspan></text>\n      <text x=\"55\" y=\"162\" font-size=\"8.2\" fill=\"#334155\">&bull; Shielding Effect (&sigma;) <tspan font-weight=\"bold\" fill=\"#2563eb\">&uarr; Increases</tspan></text>\n      <text x=\"210\" y=\"162\" font-size=\"8.2\" fill=\"#334155\">&bull; Ionization Enthalpy <tspan font-weight=\"bold\" fill=\"#dc2626\">&darr; Decreases</tspan></text>\n      <text x=\"55\" y=\"179\" font-size=\"8.2\" fill=\"#334155\">&bull; Metallic Character <tspan font-weight=\"bold\" fill=\"#2563eb\">&uarr; Increases</tspan></text>\n      <text x=\"210\" y=\"179\" font-size=\"8.2\" fill=\"#334155\">&bull; Electronegativity <tspan font-weight=\"bold\" fill=\"#dc2626\">&darr; Decreases</tspan></text>\n\n      <!-- Panel 2: Isoelectronic Series Radii & Enthalpy Anomalies -->\n      <rect x=\"480\" y=\"15\" width=\"285\" height=\"220\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"495\" y=\"36\" font-size=\"11.5\" font-weight=\"bold\" fill=\"#0f172a\">2. Isoelectronic &amp; Subshell Anomalies:</text>\n\n      <!-- Isoelectronic Series Box -->\n      <rect x=\"495\" y=\"48\" width=\"255\" height=\"75\" rx=\"5\" fill=\"#eff6ff\" stroke=\"#bfdbfe\"/>\n      <text x=\"505\" y=\"65\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1e40af\">Isoelectronic Series (10 e&macr; Core):</text>\n      <text x=\"505\" y=\"80\" font-size=\"8\" fill=\"#1e3a8a\">N&sup3;&macr; (171 pm) &gt; O&sup2;&macr; (140) &gt; F&macr; (133 pm) &gt;</text>\n      <text x=\"505\" y=\"95\" font-size=\"8\" fill=\"#1e3a8a\">Na&sdot; (102 pm) &gt; Mg&sup2;&sdot; (72) &gt; Al&sup3;&sdot; (54 pm)</text>\n      <text x=\"505\" y=\"112\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#dc2626\">&bull; Radius decreases as Nuclear Charge Z increases</text>\n\n      <!-- Subshell Stability Anomalies -->\n      <rect x=\"495\" y=\"132\" width=\"255\" height=\"92\" rx=\"5\" fill=\"#ecfdf5\" stroke=\"#a7f3d0\"/>\n      <text x=\"505\" y=\"148\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#065f46\">Crucial Thermodynamic Anomalies:</text>\n      <text x=\"505\" y=\"163\" font-size=\"7.8\" fill=\"#064e3b\">&bull; <tspan font-weight=\"bold\">Be &gt; B (I.E.):</tspan> Be has stable full 2s&sup2;; B loses 2p&sup1;.</text>\n      <text x=\"505\" y=\"178\" font-size=\"7.8\" fill=\"#064e3b\">&bull; <tspan font-weight=\"bold\">N &gt; O (I.E.):</tspan> N has stable half-filled 2p&sup3;; O has paired 2p&sup4;.</text>\n      <text x=\"505\" y=\"193\" font-size=\"7.8\" fill=\"#064e3b\">&bull; <tspan font-weight=\"bold\">Cl &gt; F (&Delta;_eg H):</tspan> F has small 2p orbital causing strong e&macr;-e&macr; interelectronic repulsion.</text>\n      <text x=\"505\" y=\"208\" font-size=\"7.8\" fill=\"#064e3b\">&bull; <tspan font-weight=\"bold\">Noble Gases:</tspan> Positive &Delta;_eg H (stable octet ns&sup2;np&sup6;).</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 3.1 to 3.40: Mendeleev &amp; Modern Periodic Law, IUPAC Z&gt;100 Naming, s/p/d/f Block Configurations, Atomic/Ionic Radii Trends, Ionization Enthalpies, Electron Gain Enthalpies, Electronegativity &amp; Oxide Nature</div>\n\n  <!-- c11c-ch3-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q1')\">\n      <div class=\"q-num\">Question 3.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the basic difference in approach between Mendeleev's Periodic Law and the Modern Periodic Law?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Fundamental Differences in Classification Approach:</b><br><br>\n    1. **Mendeleev's Periodic Law (1869):**<br>\n    • Stated that: <i>\"The physical and chemical properties of the elements are periodic functions of their <b>atomic weights (atomic masses)</b>.\"</i><br>\n    • Elements were arranged in increasing order of atomic mass, leading to anomalies such as placing elements of higher atomic weight before lower (e.g., Argon before Potassium, Cobalt before Nickel) and inability to locate isotopes in separate slots.<br><br>\n    2. **Modern Periodic Law (Henry Moseley, 1913):**<br>\n    • Stated that: <i>\"The physical and chemical properties of the elements are periodic functions of their <b>atomic numbers ($Z$)</b>.\"</i><br>\n    • Atomic number represents the fundamental nuclear charge and corresponds directly to the electronic configuration in the valence shell, which governs chemical reactivity and cleanly resolves all previous isotopic and inversion anomalies.<br><br>\n    $$\\mathbf{\\text{Conclusion: Mendeleev used atomic mass; Modern Law uses atomic number (nuclear charge).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Mendeleev's periodic law definition based on atomic mass</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Modern periodic law definition based on atomic number and valence electronic structure</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q2')\">\n      <div class=\"q-num\">Question 3.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        On the basis of quantum numbers, justify that the sixth period of the periodic table should have $32$ elements.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Justification based on Quantum Numbers &amp; Aufbau Principle:</b><br><br>\n    1. In the sixth period of the periodic table, the principal quantum number is $\\mathbf{n = 6}$.<br><br>\n    2. According to the Aufbau $(n + l)$ energy rule, the orbitals filled in the $6^{\\text{th}}$ period are filled in order of increasing energy:<br>\n    • $\\mathbf{6s}$ orbital: $n = 6, l = 0 \\implies (n + l) = 6$<br>\n    • $\\mathbf{4f}$ orbitals: $n = 4, l = 3 \\implies (n + l) = 7$<br>\n    • $\\mathbf{5d}$ orbitals: $n = 5, l = 2 \\implies (n + l) = 7$<br>\n    • $\\mathbf{6p}$ orbitals: $n = 6, l = 1 \\implies (n + l) = 7$<br><br>\n    3. **Total available orbitals:**<br>\n    • One $6s$ orbital $= 1\\text{ orbital}$<br>\n    • Seven $4f$ orbitals $= 7\\text{ orbitals}$ (Lanthanoids, $Z = 58$ to $71$)<br>\n    • Five $5d$ orbitals $= 5\\text{ orbitals}$ (Transition metals)<br>\n    • Three $6p$ orbitals $= 3\\text{ orbitals}$<br>\n    $$\\text{Total orbitals available} = 1 + 7 + 5 + 3 = \\mathbf{16\\text{ orbitals}}$$<br><br>\n    4. By Pauli's exclusion principle, each orbital can hold a maximum of $2$ electrons:<br>\n    $$\\text{Maximum number of electrons (elements)} = 16 \\times 2 = \\mathbf{32\\text{ elements}}$$<br><br>\n    $$\\mathbf{\\text{Hence, the sixth period must contain exactly } 32\\text{ elements (from Cs, } Z=55 \\text{ to Rn, } Z=86\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Identification of orbitals filled in 6th period: 6s, 4f, 5d, 6p</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of total orbitals: 1 + 7 + 5 + 3 = 16 orbitals</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application of Pauli exclusion principle yielding 16 x 2 = 32 elements</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q3')\">\n      <div class=\"q-num\">Question 3.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In terms of period and group where would you locate the element with $Z = 114$?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Determining Period and Group for $Z = 114$ (Flerovium, $\\text{Fl}$):</b><br><br>\n    1. **Noble Gas Core:** The nearest preceding noble gas is Radon ($\\text{Rn}$, $Z = 86$).<br><br>\n    2. **Electronic Configuration of $Z = 114$:**<br>\n    Filling $7s, 5f, 6d, 7p$ orbitals beyond Radon ($Z = 86$):<br>\n    $$Z = 114: \\quad [\\text{Rn}] \\; 5f^{14} \\; 6d^{10} \\; 7s^2 \\; 7p^2$$<br>\n    • Electrons filled: $86 + 14 + 10 + 2 + 2 = 114$.<br><br>\n    3. **Locating Position:**<br>\n    • **Period:** The highest principal quantum number is $n = 7$. Hence, it belongs to the $\\mathbf{7^{\\text{th}} \\text{ period}}$.<br>\n    • **Block:** The differentiating electron enters the $7p$ subshell, so it is a $\\mathbf{p\\text{-block element}}$.<br>\n    • **Group Number:** For a $p$-block element, $\\text{Group} = 12 + \\text{number of } p\\text{-electrons} = 10 + \\text{valence electrons} = 10 + (2 + 2) = \\mathbf{14}$ (Carbon family).<br><br>\n    $$\\mathbf{\\text{The element with } Z = 114 \\text{ is in Period 7 and Group 14 (Carbon family).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Writing electronic configuration [Rn] 5f^14 6d^10 7s^2 7p^2</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Deducing Period = 7 and Group = 14</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q4')\">\n      <div class=\"q-num\">Question 3.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write the atomic number of the element present in the third period and seventeenth group of the periodic table.\n      </div>\n      <div class=\"q-marks\">[1.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Step-by-Step Location:</b><br><br>\n    1. **Period 3:** The valence shell corresponds to principal quantum number $n = 3$.<br>\n    2. **Group 17 (Halogens):** General valence shell electronic configuration of Group 17 is $ns^2 np^5$.<br>\n    For $n = 3$, the valence configuration is $\\mathbf{3s^2 3p^5}$.<br><br>\n    3. **Complete Electronic Configuration:**<br>\n    $$1s^2 \\; 2s^2 \\; 2p^6 \\; 3s^2 \\; 3p^5 \\quad \\text{or} \\quad [\\text{Ne}] \\; 3s^2 3p^5$$<br>\n    Total electrons $= 2 + 2 + 6 + 2 + 5 = \\mathbf{17}$.<br><br>\n    $$\\mathbf{\\text{The atomic number of the element is } Z = 17\\text{ (Chlorine, Cl).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Deducing valence shell configuration 3s^2 3p^5</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Determining total electrons = 17 and identifying Chlorine</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q5')\">\n      <div class=\"q-num\">Question 3.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which element do you think would have been named by<br>\n   (i) Lawrence Berkeley Laboratory<br>\n   (ii) Seaborg's group?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Historical Naming of Superheavy Transuranium Elements:</b><br><br>\n    <b>(i) Lawrence Berkeley Laboratory (USA):</b><br>\n    • **Berkelium ($\\text{Bk}$, $Z = 97$):** Named directly in honour of the city of Berkeley and the University of California at Berkeley.<br>\n    • **Lawrencium ($\\text{Lr}$, $Z = 103$):** Named directly in honour of Ernest O. Lawrence, founder of the Lawrence Berkeley Laboratory and inventor of the cyclotron.<br><br>\n    <b>(ii) Seaborg's Group:</b><br>\n    • **Seaborgium ($\\text{Sg}$, $Z = 106$):** Named in honour of the American nuclear chemist Glenn T. Seaborg, leader of the research group that synthesized numerous transuranic elements (plutonium through seaborgium) and formulated the actinoid concept.<br><br>\n    $$\\mathbf{\\text{Summary: (i) Berkelium (Bk, } Z=97\\text{) and Lawrencium (Lr, } Z=103\\text{); (ii) Seaborgium (Sg, } Z=106\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Lawrencium (Z = 103) / Berkelium (Z = 97) named by Lawrence Berkeley Laboratory</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Seaborgium (Z = 106) named by Glenn Seaborg's research team</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q6')\">\n      <div class=\"q-num\">Question 3.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why do elements in the same group have similar physical and chemical properties?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Reasoning:</b><br><br>\n    1. **Identical Valence Shell Electronic Configuration:** All elements belonging to the same vertical group possess the **same number and arrangement of electrons in their outermost (valence) shell**.<br>\n    • Group 1 (Alkali metals): $ns^1$<br>\n    • Group 2 (Alkaline earth metals): $ns^2$<br>\n    • Group 17 (Halogens): $ns^2 np^5$<br><br>\n    2. **Valency and Bonding:** Chemical reactions involve the sharing, loss, or gain of valence electrons. Because the valence electrons dictate the chemical valency, bonding types, oxidation states, and coordination geometry, elements in the same group undergo analogous reactions and form compounds with identical stoichiometries (e.g., $\\text{NaCl, KCl, RbCl}$).<br><br>\n    3. **Gradual Physical Trends:** Physical properties (like atomic size, melting point, density) vary predictably down a group because the principal quantum number $n$ increases while maintaining the same outer valence symmetry.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Stating identical valence electron configuration (ns^x np^y)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining chemical reactivity depends on valence electron loss/gain/sharing</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q7')\">\n      <div class=\"q-num\">Question 3.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What does atomic radius and ionic radius really mean to you?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Physical Meaning and Operational Definitions:</b><br><br>\n    1. **Atomic Radius:**<br>\n    The probability distribution of electrons around a nucleus extends asymptotically to infinity, meaning an isolated atom has no sharp, rigid physical boundary. Therefore, atomic radius is practically measured as **half the distance between the nuclei of two bonded adjacent atoms** of the same element:<br>\n    • **Covalent Radius:** Half of the internuclear distance between two identical single-bonded atoms in a covalent molecule (e.g., in $\\text{Cl}_2$, internuclear distance is $198\\text{ pm} \\implies r_{\\text{cov}} = 99\\text{ pm}$).<br>\n    • **Metallic Radius:** Half of the internuclear distance between two adjacent metal ions in a metallic lattice.<br>\n    • **van der Waals Radius:** Half of the distance between two non-bonded adjacent atoms of neighboring molecules in the solid state ($r_{\\text{vdW}} > r_{\\text{metallic}} > r_{\\text{covalent}}$).<br><br>\n    2. **Ionic Radius:**<br>\n    The effective distance from the center of the nucleus of an ion up to which it exerts an electrostatic influence on its electron cloud in an ionic crystal lattice.<br>\n    • **Cation Radius:** Always smaller than parent atom ($r_{\\text{cation}} < r_{\\text{atom}}$) due to loss of valence electrons and increased $Z_{\\text{eff}}$.<br>\n    • **Anion Radius:** Always larger than parent atom ($r_{\\text{anion}} > r_{\\text{atom}}$) due to addition of electrons and inter-electronic repulsion.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Atomic radius definition via internuclear distance (covalent, metallic, van der Waals)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ionic radius definition and contrast of cation vs anion size</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q8')\">\n      <div class=\"q-num\">Question 3.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How do atomic radius vary in a period and in a group? How do you explain the variation?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Variation Across a Period (Left to Right):</b><br>\n    • **Trend:** Atomic radius **decreases** from left to right across a period.<br>\n    • **Explanation:** Moving across a period, electrons are added to the **same principal energy level (same shell $n$)**, while the nuclear charge ($Z$) increases by one unit for each successive element. Since inner electron shielding does not increase significantly, the **effective nuclear charge ($Z_{\\text{eff}}$)** pulls the valence electrons closer to the nucleus, contracting the electron cloud.<br><br>\n    <b>2. Variation Down a Group (Top to Bottom):</b><br>\n    • **Trend:** Atomic radius **increases** down a group.<br>\n    • **Explanation:** Moving down a group, a new principal energy shell ($n$) is added at each successive element. Although the nuclear charge also increases, the effect of adding new shells and the increased screening (shielding) by inner electrons far outweighs the nuclear charge increase, expanding the size of the electron cloud.<br><br>\n    $$\\mathbf{\\text{Summary: Decreases across a period (increasing } Z_\\text{eff}\\text{); Increases down a group (adding shells } n\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Period variation: decreases due to increasing effective nuclear charge (Z_eff) in same shell</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Group variation: increases due to addition of new electron shells and shielding effect</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q9')\">\n      <div class=\"q-num\">Question 3.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What do you understand by isoelectronic species? Name a species that will be isoelectronic with each of the following atoms or ions:<br>\n   (i) $\\text{F}^-$, (ii) $\\text{Ar}$, (iii) $\\text{Mg}^{2+}$, (iv) $\\text{Rb}^+$.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Definition:</b><br>\n    Atoms or ions that contain the **exact same total number of electrons** are called **isoelectronic species**.<br><br>\n    <b>Isoelectronic counterparts:</b><br>\n    • **(i) $\\text{F}^-$ (Fluoride ion):**<br>\n    $Z = 9$, total electrons $= 9 + 1 = \\mathbf{10\\text{ e}^-}$.<br>\n    Isoelectronic species: $\\mathbf{\\text{Ne}},\\; \\mathbf{\\text{Na}^+},\\; \\mathbf{\\text{O}^{2-}},\\; \\mathbf{\\text{Mg}^{2+}},\\; \\mathbf{\\text{Al}^{3+}},\\; \\mathbf{\\text{N}^{3-}}$.<br><br>\n    • **(ii) $\\text{Ar}$ (Argon atom):**<br>\n    $Z = 18$, total electrons $= \\mathbf{18\\text{ e}^-}$.<br>\n    Isoelectronic species: $\\mathbf{\\text{K}^+},\\; \\mathbf{\\text{Ca}^{2+}},\\; \\mathbf{\\text{Cl}^-},\\; \\mathbf{\\text{S}^{2-}},\\; \\mathbf{\\text{P}^{3-}}$.<br><br>\n    • **(iii) $\\text{Mg}^{2+}$ (Magnesium ion):**<br>\n    $Z = 12$, total electrons $= 12 - 2 = \\mathbf{10\\text{ e}^-}$.<br>\n    Isoelectronic species: $\\mathbf{\\text{Ne}},\\; \\mathbf{\\text{Na}^+},\\; \\mathbf{\\text{F}^-},\\; \\mathbf{\\text{O}^{2-}},\\; \\mathbf{\\text{Al}^{3+}}$.<br><br>\n    • **(iv) $\\text{Rb}^+$ (Rubidium ion):**<br>\n    $Z = 37$, total electrons $= 37 - 1 = \\mathbf{36\\text{ e}^-}$.<br>\n    Isoelectronic species: $\\mathbf{\\text{Kr}},\\; \\mathbf{\\text{Sr}^{2+}},\\; \\mathbf{\\text{Br}^-},\\; \\mathbf{\\text{Se}^{2-}}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Isoelectronic species definition stated clearly</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct isoelectronic species for F- (10 e-) and Ar (18 e-)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct isoelectronic species for Mg2+ (10 e-) and Rb+ (36 e-)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q10')\">\n      <div class=\"q-num\">Question 3.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Consider the following species:<br>\n   $\\text{N}^{3-},\\; \\text{O}^{2-},\\; \\text{F}^-,\\; \\text{Na}^+,\\; \\text{Mg}^{2+},\\; \\text{Al}^{3+}$.<br>\n   (a) What is common in them?<br>\n   (b) Arrange them in the order of increasing ionic radii.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(a) Common Feature:</b><br>\n    All these species are **isoelectronic**; each possesses exactly **$10$ electrons** (electronic configuration $1s^2 2s^2 2p^6$, matching Neon):<br>\n    • $\\text{N}^{3-}$: $7 + 3 = 10\\text{ e}^-$<br>\n    • $\\text{O}^{2-}$: $8 + 2 = 10\\text{ e}^-$<br>\n    • $\\text{F}^-$: $9 + 1 = 10\\text{ e}^-$<br>\n    • $\\text{Na}^+$: $11 - 1 = 10\\text{ e}^-$<br>\n    • $\\text{Mg}^{2+}$: $12 - 2 = 10\\text{ e}^-$<br>\n    • $\\text{Al}^{3+}$: $13 - 3 = 10\\text{ e}^-$<br><br>\n    <b>(b) Arrangement in Order of Increasing Ionic Radii:</b><br>\n    For isoelectronic species, the number of electrons is constant, so ionic radius is inversely proportional to the nuclear charge (atomic number $Z$):<br>\n    $$\\text{Ionic Radius} \\propto \\frac{1}{\\text{Nuclear Charge } (Z)}$$<br>\n    Nuclear charges: $\\text{N} (+7) < \\text{O} (+8) < \\text{F} (+9) < \\text{Na} (+11) < \\text{Mg} (+12) < \\text{Al} (+13)$.<br>\n    Greater positive nuclear charge exerts a stronger inward electrostatic attraction on the 10 electrons, shrinking the ion.<br><br>\n    $$\\mathbf{\\text{Increasing order of ionic radii: } \\text{Al}^{3+} < \\text{Mg}^{2+} < \\text{Na}^+ < \\text{F}^- < \\text{O}^{2-} < \\text{N}^{3-}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Identifying all 6 species are isoelectronic with 10 electrons</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Inverse relation with nuclear charge Z</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct ascending radii order: Al3+ < Mg2+ < Na+ < F- < O2- < N3-</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q11')\">\n      <div class=\"q-num\">Question 3.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain why cations are smaller and anions larger in radii than their parent atoms?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Why Cations are Smaller than Parent Atoms ($r_{\\text{cation}} < r_{\\text{atom}}$):</b><br>\n    • Formation of a cation involves the **loss of one or more valence electrons** from the neutral atom.<br>\n    • In many cases (e.g., $\\text{Na} \\to \\text{Na}^+$), the entire outermost shell is eliminated ($n = 3 \\to n = 2$).<br>\n    • The remaining electrons experience an unchanged nuclear charge ($+Z$), so the **effective nuclear charge per electron ($Z/e$ ratio) increases**, pulling the remaining electron cloud tighter towards the nucleus.<br><br>\n    <b>2. Why Anions are Larger than Parent Atoms ($r_{\\text{anion}} > r_{\\text{atom}}$):</b><br>\n    • Formation of an anion involves the **gain of one or more electrons** into the valence shell.<br>\n    • Nuclear charge remains unchanged while the electron count increases, decreasing the effective nuclear charge per electron ($Z/e$ ratio decreases).<br>\n    • The added electrons increase **inter-electronic repulsions** within the valence shell, causing the electron cloud to expand outward.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Cation explanation: higher Z/e ratio, reduced shielding, and possible loss of outer shell</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Anion explanation: added electrons increase interelectronic repulsions and lower Z/e ratio</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q12')\">\n      <div class=\"q-num\">Question 3.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the significance of the terms — 'isolated gaseous atom' and 'ground state' while defining the ionization enthalpy and electron gain enthalpy?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Significance of the Specific Constraints:</b><br><br>\n    1. **'Isolated Gaseous Atom':**<br>\n    • In liquid or solid states, atoms interact strongly with neighboring atoms via metallic bonds, covalent lattices, or van der Waals intermolecular forces.<br>\n    • In the gaseous state at low pressure, interatomic forces are virtually zero, so the atom is truly **isolated**.<br>\n    • This ensures the measured enthalpy change represents solely the energy required to remove or add an electron to that single atom, free from lattice energy, sublimation energy, or solvent effects.<br><br>\n    2. **'Ground State':**<br>\n    • An atom can exist in infinite excited states where an electron has already absorbed energy and occupies a higher orbital.<br>\n    • In excited states, less energy would be needed to remove the electron, yielding arbitrary, non-reproducible values.<br>\n    • The **ground state** represents the most stable, lowest-energy electronic configuration of the atom, providing an unambiguous, standard reference baseline for thermodynamic comparisons.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Significance of isolated gaseous state: eliminates interatomic forces, lattice energy and bonding</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance of ground state: provides lowest energy standard reference state for reproducibility</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q13')\">\n      <div class=\"q-num\">Question 3.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Energy of an electron in the ground state of the hydrogen atom is $-2.18 \\times 10^{-18}\\text{ J}$. Calculate the ionization enthalpy of atomic hydrogen in terms of $\\text{J mol}^{-1}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given Data:<br>\n    • Ground state energy ($n = 1$): $E_1 = -2.18 \\times 10^{-18}\\text{ J atom}^{-1}$<br>\n    • Ionization corresponds to removing the electron to $n = \\infty$ ($E_\\infty = 0$):<br>\n    $$\\Delta E = E_\\infty - E_1 = 0 - (-2.18 \\times 10^{-18}\\text{ J}) = \\mathbf{2.18 \\times 10^{-18}\\text{ J atom}^{-1}}$$<br><br>\n    <b>Ionization Enthalpy per mole of Hydrogen atoms:</b><br>\n    Multiply by Avogadro's constant ($N_A = 6.022 \\times 10^{23}\\text{ mol}^{-1}$):<br>\n    $$\\Delta_i H = \\Delta E \\times N_A = (2.18 \\times 10^{-18}\\text{ J atom}^{-1}) \\times (6.022 \\times 10^{23}\\text{ atoms mol}^{-1})$$<br>\n    $$\\Delta_i H = 1.3128 \\times 10^6\\text{ J mol}^{-1} = \\mathbf{1.313 \\times 10^6\\text{ J mol}^{-1} = 1313\\text{ kJ mol}^{-1}}$$<br><br>\n    $$\\mathbf{\\text{The ionization enthalpy of atomic hydrogen is } 1.313 \\times 10^6\\text{ J mol}^{-1} \\text{ (or } 1313\\text{ kJ mol}^{-1}\\text{).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Calculation of ionization energy per atom = 2.18 x 10^-18 J</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying by Avogadro number yielding 1.313 x 10^6 J/mol (1313 kJ/mol)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q14')\">\n      <div class=\"q-num\">Question 3.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Among the second period elements the actual ionization enthalpies are in the order $\\text{Li} < \\text{B} < \\text{Be} < \\text{C} < \\text{O} < \\text{N} < \\text{F} < \\text{Ne}$.<br>\n   Explain why<br>\n   (i) $\\text{Be}$ has higher $\\Delta_i H$ than $\\text{B}$<br>\n   (ii) $\\text{O}$ has lower $\\Delta_i H$ than $\\text{N}$ and $\\text{F}$?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) Why Beryllium ($\\text{Be}$) has higher $\\Delta_i H$ than Boron ($\\text{B}$):</b><br>\n    • Electronic configurations: $\\text{Be} (Z = 4): 1s^2 2s^2$; $\\text{B} (Z = 5): 1s^2 2s^2 2p^1$.<br>\n    • In Beryllium, the electron to be removed is from a **completely filled $2s$ subshell ($2s^2$)**, which possesses extra stability.<br>\n    • Furthermore, an $s$-electron penetrates closer to the nucleus than a $p$-electron, experiencing higher effective nuclear charge.<br>\n    • In Boron, the electron is removed from a single $2p$ orbital ($2p^1$), which is well-shielded by the inner $1s^2 2s^2$ electrons and is held less tightly. Thus, $\\Delta_i H(\\text{Be}) > \\Delta_i H(\\text{B})$.<br><br>\n    <b>(ii) Why Oxygen ($\\text{O}$) has lower $\\Delta_i H$ than Nitrogen ($\\text{N}$) and Fluorine ($\\text{F}$):</b><br>\n    • Electronic configurations: $\\text{N} (Z = 7): 1s^2 2s^2 2p_x^1 2p_y^1 2p_z^1$; $\\text{O} (Z = 8): 1s^2 2s^2 2p_x^2 2p_y^1 2p_z^1$.<br>\n    • Nitrogen has an **exactly half-filled $2p^3$ subshell**, which imparts extra symmetrical stability and high exchange energy.<br>\n    • In Oxygen, four electrons occupy the $2p$ orbitals ($2p^4$). One orbital ($2p_x$) contains a paired pair of electrons. The mutual electrostatic repulsion between these two paired electrons in the same orbital makes it easier to remove one electron compared to the stable half-filled configuration of Nitrogen.<br>\n    • Fluorine has higher nuclear charge ($Z = 9$) and smaller size, which increases its $\\Delta_i H$ above Oxygen.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Be has completely filled 2s^2 orbital with higher penetration than 2p^1 in B</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) N has stable half-filled 2p^3; O has paired 2p^4 where inter-electronic repulsion facilitates removal</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q15')\">\n      <div class=\"q-num\">Question 3.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How would you explain the fact that the first ionization enthalpy of sodium is lower than that of magnesium but its second ionization enthalpy is higher than that of magnesium?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Electronic configurations:<br>\n    • $\\text{Na} (Z = 11): 1s^2 2s^2 2p^6 3s^1 = [\\text{Ne}]\\; 3s^1$<br>\n    • $\\text{Mg} (Z = 12): 1s^2 2s^2 2p^6 3s^2 = [\\text{Ne}]\\; 3s^2$<br><br>\n    <b>1. First Ionization Enthalpy ($\\Delta_i H_1(\\text{Na}) < \\Delta_i H_1(\\text{Mg})$):</b><br>\n    • Removing the $1^{\\text{st}}$ electron from $\\text{Na}$ leaves a stable noble gas configuration ($[\\text{Ne}]$), and its $3s^1$ electron experiences a lower nuclear charge ($Z = 11$) compared to $\\text{Mg}$ ($Z = 12$).<br>\n    • Magnesium has a fully filled $3s^2$ subshell with higher nuclear charge, making $\\Delta_i H_1(\\text{Mg}) = 737\\text{ kJ/mol} > \\Delta_i H_1(\\text{Na}) = 496\\text{ kJ/mol}$.<br><br>\n    <b>2. Second Ionization Enthalpy ($\\Delta_i H_2(\\text{Na}) > \\Delta_i H_2(\\text{Mg})$):</b><br>\n    • For $\\text{Na}^+$: Configuration is $[\\text{Ne}]\\; 2s^2 2p^6$. Removing the $2^{\\text{nd}}$ electron requires disrupting a **stable octet noble gas core** from a principal shell closer to the nucleus ($n = 2$), demanding colossal energy ($\\Delta_i H_2 = 4562\\text{ kJ/mol}$).<br>\n    • For $\\text{Mg}^+$: Configuration is $[\\text{Ne}]\\; 3s^1$. The $2^{\\text{nd}}$ electron is removed from the outer $3s$ orbital ($n = 3$), and its removal actually yields a stable noble gas core ($[\\text{Ne}]$). Hence, $\\Delta_i H_2(\\text{Mg}) = 1450\\text{ kJ/mol} \\ll \\Delta_i H_2(\\text{Na})$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">First IE: Na loses 3s^1 with lower nuclear charge compared to stable 3s^2 of Mg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Second IE: Na+ requires breaking stable octet [Ne] core (n=2), whereas Mg+ loses outer 3s^1</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q16')\">\n      <div class=\"q-num\">Question 3.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the various factors due to which the ionization enthalpy of the main group elements tends to decrease down a group?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Factors Causing Ionization Enthalpy to Decrease Down a Group:</b><br><br>\n    1. **Increase in Atomic Size (Principal Quantum Number $n$):**<br>\n    At each succeeding element down a group, a completely new principal energy shell is added. The distance between the nucleus and the outermost valence electrons increases substantially, weakening the electrostatic attraction ($F \\propto 1/r^2$).<br><br>\n    2. **Increase in Shielding (Screening) Effect:**<br>\n    As new shells are added, the number of intervening inner core electrons increases. These core electrons screen the valence electrons from the positive nuclear charge, reducing the effective nuclear pull.<br><br>\n    3. **Dominance of Size and Shielding over Nuclear Charge:**<br>\n    Although the nuclear charge ($Z$) increases down the group, the simultaneous increase in atomic radius and shielding effect far outweighs the increase in nuclear charge, causing the valence electrons to be held progressively more loosely.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Factor 1: Increase in atomic size / principal quantum number n</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Factor 2: Increased shielding/screening effect by intervening core electrons</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Combined explanation: size and shielding outweigh nuclear charge increase</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q17')\">\n      <div class=\"q-num\">Question 3.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The first ionization enthalpy values (in $\\text{kJ mol}^{-1}$) of group 13 elements are:<br>\n   $\\text{B}: 801,\\; \\text{Al}: 577,\\; \\text{Ga}: 579,\\; \\text{In}: 558,\\; \\text{Tl}: 589$.<br>\n   How would you explain this deviation from the general trend?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Analysis of Anomalous $\\Delta_i H$ in Group 13:</b><br><br>\n    • **Normal drop from $\\text{B}$ ($801$) to $\\text{Al}$ ($577$):** Expected due to substantial size increase and addition of third shell.<br><br>\n    • **Slight increase from $\\text{Al}$ ($577$) to $\\text{Ga}$ ($579$):**<br>\n    Gallium follows the $3d$ transition elements and has an electronic configuration of $[\\text{Ar}]\\; 3d^{10} 4s^2 4p^1$. The ten $3d$ electrons have poor shielding ability, causing an increased effective nuclear charge ($Z_\\text{eff}$) that contracts Gallium's radius (making it slightly smaller than Aluminium) and increases its ionization enthalpy.<br><br>\n    • **Drop from $\\text{Ga}$ ($579$) to $\\text{In}$ ($558$):** Standard increase in size from $n = 4$ to $n = 5$ with $4d$ shielding.<br><br>\n    • **Sharp increase from $\\text{In}$ ($558$) to $\\text{Tl}$ ($589$):**<br>\n    Thallium follows the $4f$ lanthanoid series ($[\\text{Xe}]\\; 4f^{14} 5d^{10} 6s^2 6p^1$). The fourteen $4f$ electrons have **extremely poor shielding power** (Lanthanoid Contraction). The high positive nuclear charge ($Z = 81$) pulls the valence $6p$ and $6s$ electrons very tightly, causing $\\Delta_i H$ of $\\text{Tl}$ to exceed both $\\text{In}$ and $\\text{Ga}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Explaining Al to Ga plateau/increase due to poor shielding of 3d^10 electrons (d-block contraction)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining In to Tl sharp increase due to poor shielding of 4f^14 electrons (lanthanoid contraction)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q18')\">\n      <div class=\"q-num\">Question 3.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which of the following pairs of elements would have a more negative electron gain enthalpy?<br>\n   (i) $\\text{O}$ or $\\text{F}$<br>\n   (ii) $\\text{F}$ or $\\text{Cl}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>(i) $\\text{O}$ or $\\text{F}$ (Within Period 2):</b><br>\n    • Across a period from left to right, nuclear charge increases and atomic size decreases.<br>\n    • Fluorine ($Z = 9$) has a higher nuclear charge and higher electronegativity than Oxygen ($Z = 8$). Adding an electron to Fluorine yields a stable noble gas configuration ($[\\text{Ne}]$).<br>\n    • Hence, **Fluorine ($\\text{F}$)** has a much more negative electron gain enthalpy ($\\Delta_{\\text{eg}} H(\\text{F}) = -328\\text{ kJ/mol}$, $\\Delta_{\\text{eg}} H(\\text{O}) = -141\\text{ kJ/mol}$).<br><br>\n    <b>(ii) $\\text{F}$ or $\\text{Cl}$ (Down Group 17):</b><br>\n    • **Chlorine ($\\text{Cl}$)** has a **more negative** electron gain enthalpy than Fluorine ($\\Delta_{\\text{eg}} H(\\text{Cl}) = -349\\text{ kJ/mol} > \\Delta_{\\text{eg}} H(\\text{F}) = -328\\text{ kJ/mol}$).<br>\n    • *Reason:* Fluorine has an extremely compact, small $2p$ subshell. Adding an electron results in intense **inter-electronic repulsions** among the seven valence electrons. In Chlorine, the incoming electron enters the larger, more diffuse $3p$ orbital where electron-electron repulsions are minimal.<br><br>\n    $$\\mathbf{\\text{Summary: (i) } \\text{F has more negative } \\Delta_{\\text{eg}} H;\\; \\text{(ii) } \\text{Cl has more negative } \\Delta_{\\text{eg}} H.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Fluorine is more negative than Oxygen due to higher nuclear charge and near-octet status</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Chlorine is more negative than Fluorine due to less inter-electronic repulsion in larger 3p subshell</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q19')\">\n      <div class=\"q-num\">Question 3.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Would you expect the second electron gain enthalpy of $\\text{O}$ as positive, more negative or less negative than the first? Justify your answer.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Answer:</b> The second electron gain enthalpy of oxygen is **positive (endothermic)**.<br><br>\n    $$\\text{O}(g) + e^- \\longrightarrow \\text{O}^-(g) \\quad \\Delta_{\\text{eg}} H_1 = -141\\text{ kJ mol}^{-1} \\quad (\\text{Exothermic})$$<br>\n    $$\\text{O}^-(g) + e^- \\longrightarrow \\text{O}^{2-}(g) \\quad \\Delta_{\\text{eg}} H_2 = +780\\text{ kJ mol}^{-1} \\quad (\\text{Endothermic})$$<br><br>\n    <b>Justification:</b><br>\n    • When the first electron is added to a neutral oxygen atom, the attractive pull of the positive nucleus exceeds electron-electron repulsion, releasing energy (negative $\\Delta_{\\text{eg}} H_1$).<br>\n    • To form the oxide ion ($\\text{O}^{2-}$), a second electron must be forced onto an already **negatively charged $\\text{O}^-$ anion**.<br>\n    • There is immense **electrostatic repulsion** between the incoming electron and the negatively charged $\\text{O}^-$ ion.<br>\n    • Overcoming this strong repulsion requires significant external energy input, making $\\Delta_{\\text{eg}} H_2$ strongly positive.<br><br>\n    $$\\mathbf{\\text{Conclusion: The second electron gain enthalpy is positive (endothermic).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Clear declaration that Delta_eg H2 is positive (endothermic)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification: strong electrostatic repulsion between negative O- ion and incoming electron</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q20')\">\n      <div class=\"q-num\">Question 3.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the basic difference between the terms electron gain enthalpy and electronegativity?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Comparison Table of Core Conceptual Differences:</b><br><br>\n    <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.85rem;\">\n      <thead>\n        <tr style=\"background:#f1f5f9; text-align:left; border-bottom:2px solid #cbd5e1;\">\n          <th style=\"padding:8px;\">Property</th>\n          <th style=\"padding:8px;\">Electron Gain Enthalpy ($\\Delta_{\\text{eg}} H$)</th>\n          <th style=\"padding:8px;\">Electronegativity ($\\chi$)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>Definition</b></td>\n          <td style=\"padding:8px;\">Tendency of an <b>isolated gaseous atom</b> to accept an electron to form a uninegative anion.</td>\n          <td style=\"padding:8px;\">Tendency of an atom in a <b>bonded chemical compound</b> to attract the shared pair of electrons towards itself.</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>State of Atom</b></td>\n          <td style=\"padding:8px;\">Applies strictly to single, unbonded atoms in the gaseous state.</td>\n          <td style=\"padding:8px;\">Applies to an atom chemically bonded to another atom in a molecule.</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid #e2e8f0;\">\n          <td style=\"padding:8px;\"><b>Nature &amp; Units</b></td>\n          <td style=\"padding:8px;\">Absolute thermodynamic energy quantity, measured in $\\text{kJ mol}^{-1}$ or $\\text{eV atom}^{-1}$.</td>\n          <td style=\"padding:8px;\">Relative, dimensionless property with no units (e.g., Pauling scale, Mulliken scale).</td>\n        </tr>\n        <tr>\n          <td style=\"padding:8px;\"><b>Constancy</b></td>\n          <td style=\"padding:8px;\">Constant characteristic property of a given element.</td>\n          <td style=\"padding:8px;\">Varies depending on hybridization state and oxidation number of the element.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Difference in atomic state: isolated gaseous atom vs bonded state in molecule</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference in measurement: absolute thermodynamic energy (kJ/mol) vs relative dimensionless index</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q21')\">\n      <div class=\"q-num\">Question 3.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How would you react to the statement that the electronegativity of $\\text{N}$ on Pauling scale is $3.0$ in all the nitrogen compounds?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Scientific Assessment:</b> The statement is <b>incorrect</b>.<br><br>\n      • **Electronegativity is not an invariant physical constant** for an element; it varies according to its chemical bonding environment, oxidation state, and orbital hybridization:<br>\n      1. **Effect of Hybridization:** Electronegativity increases with increasing $s$-character ($sp > sp^2 > sp^3$). In an $sp$-hybridized state ($50\\%\\; s$-character), nitrogen attracts electrons much more strongly than in an $sp^3$-hybridized state ($25\\%\\; s$-character).<br>\n      2. **Effect of Oxidation State:** Nitrogen in higher oxidation states (e.g., $+5$ in $\\text{HNO}_3$ or $\\text{NO}_2^+$) has greater effective nuclear pull and is significantly more electronegative than in lower oxidation states (e.g., $-3$ in $\\text{NH}_3$).<br>\n      • The value $3.0$ on the Pauling scale represents merely an empirical average value under standard reference bonding conditions.\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Statement is incorrect; electronegativity is not a constant property</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation showing dependence on oxidation state and hybridization (s-character)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q22')\">\n      <div class=\"q-num\">Question 3.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the theory associated with the radius of an atom as it<br>\n       (a) gains an electron<br>\n       (b) loses an electron.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>(a) Radius when an atom gains an electron (Anion formation):</b><br>\n      • Adding an electron increases the total electron count while the nuclear charge ($+Z$) remains unchanged.<br>\n      • The effective nuclear charge per electron ($Z/e$) decreases.<br>\n      • The added electron causes increased inter-electronic repulsions among all valence electrons, forcing the electron cloud to expand.<br>\n      • Thus, **the radius increases ($r_{\\text{anion}} > r_{\\text{atom}}$)**.<br><br>\n      <b>(b) Radius when an atom loses an electron (Cation formation):</b><br>\n      • Removing an electron leaves fewer electrons attracted by the same positive nuclear charge ($+Z$).<br>\n      • The $Z/e$ ratio increases, increasing the effective nuclear charge pulling each remaining electron closer.<br>\n      • In many cases, the entire outer valence shell is emptied.<br>\n      • Thus, **the radius decreases ($r_{\\text{cation}} < r_{\\text{atom}}$)**.\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Anion radius expansion due to increased interelectronic repulsion and decreased Z/e</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Cation radius contraction due to increased effective nuclear charge Z/e and shell loss</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q23 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q23\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q23')\">\n      <div class=\"q-num\">Question 3.23</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Would you expect the first ionization enthalpies for two isotopes of the same element to be the same or different? Justify your answer.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Answer:</b> The first ionization enthalpies for two isotopes of the same element will be **essentially identical (the same)**.<br><br>\n      <b>Justification:</b><br>\n      1. Ionization enthalpy depends directly on:<br>\n      • **Nuclear charge ($Z$)** (number of protons)<br>\n      • **Number of electrons** and their electronic configuration<br>\n      • **Atomic radius / screening constant ($\\sigma$)**<br><br>\n      2. Isotopes of an element have the exact same atomic number $Z$, identical numbers of protons, and identical electronic configurations in the electron cloud.<br>\n      3. Isotopes differ solely in their **number of neutrons** within the nucleus. Because neutrons carry zero electric charge, they have virtually no effect on the electrostatic force of attraction between the nucleus and the valence electrons.<br>\n      *(Extremely tiny differences due to reduced nuclear mass effects are negligible for all practical chemical purposes).*\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Stating first IE will be practically identical</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justifying that isotopes have identical Z, electron configuration and electrostatic attraction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q24 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q24\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q24')\">\n      <div class=\"q-num\">Question 3.24</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the major differences between metals and non-metals?\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Comprehensive Comparison between Metals and Non-Metals:</b><br><br>\n      <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.85rem;\">\n        <thead>\n          <tr style=\"background:#f1f5f9; text-align:left; border-bottom:2px solid #cbd5e1;\">\n            <th style=\"padding:8px;\">Property</th>\n            <th style=\"padding:8px;\">Metals</th>\n            <th style=\"padding:8px;\">Non-Metals</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px;\"><b>Electronic Nature</b></td>\n            <td style=\"padding:8px;\">Electropositive; readily lose electrons to form cations.</td>\n            <td style=\"padding:8px;\">Electronegative; readily gain or share electrons.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px;\"><b>Ionization Enthalpy</b></td>\n            <td style=\"padding:8px;\">Low ionization enthalpies and low electronegativities.</td>\n            <td style=\"padding:8px;\">High ionization enthalpies and high electronegativities.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px;\"><b>Nature of Oxides</b></td>\n            <td style=\"padding:8px;\">Form <b>basic</b> (e.g., $\\text{Na}_2\\text{O}, \\text{CaO}$) or amphoteric oxides.</td>\n            <td style=\"padding:8px;\">Form <b>acidic</b> (e.g., $\\text{SO}_2, \\text{CO}_2$) or neutral oxides ($\\text{CO, NO}$).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px;\"><b>Physical Properties</b></td>\n            <td style=\"padding:8px;\">Lustrous, malleable, ductile, high electrical &amp; thermal conductors.</td>\n            <td style=\"padding:8px;\">Brittle solids, liquids or gases; poor conductors (except graphite).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px;\"><b>Reducing / Oxidizing</b></td>\n            <td style=\"padding:8px;\">Strong reducing agents.</td>\n            <td style=\"padding:8px;\">Strong oxidizing agents.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Chemical differences: electropositivity vs electronegativity and oxide nature (basic vs acidic)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physical differences: conductivity, malleability, ductility, physical states</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q25 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q25\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q25')\">\n      <div class=\"q-num\">Question 3.25</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Use the periodic table to answer the following questions:<br>\n       (a) Identify an element with five electrons in the outer subshell.<br>\n       (b) Identify an element that would tend to lose two electrons.<br>\n       (c) Identify an element that would tend to gain two electrons.<br>\n       (d) Identify the group having metal, non-metal, liquid as well as gas at the room temperature.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>(a) Element with five electrons in the outer subshell ($np^5$):</b><br>\n      Any halogen from Group 17 (e.g., **Fluorine ($\\text{F}$)**, **Chlorine ($\\text{Cl}$)**, or **Bromine ($\\text{Br}$)**).<br><br>\n      <b>(b) Element that would tend to lose two electrons ($ns^2$):</b><br>\n      Any alkaline earth metal from Group 2 (e.g., **Magnesium ($\\text{Mg}$)**, **Calcium ($\\text{Ca}$)**, or **Barium ($\\text{Ba}$)**).<br><br>\n      <b>(c) Element that would tend to gain two electrons ($ns^2 np^4$):</b><br>\n      Any chalcogen from Group 16 (e.g., **Oxygen ($\\text{O}$)** or **Sulfur ($\\text{S}$)**).<br><br>\n      <b>(d) Group having metal, non-metal, liquid as well as gas at room temperature:</b><br>\n      **Group 17 (Halogens):**<br>\n      • Non-metals: $\\text{F, Cl, Br, I}$<br>\n      • Gases: $\\text{F}_2\\text{ and } \\text{Cl}_2$<br>\n      • Liquid: $\\text{Br}_2$<br>\n      • Solid (with metallic luster): $\\text{I}_2$<br>\n      • Radioactive metal/metalloid: $\\text{At}$ (Astatine) / $\\text{Ts}$ (Tennessine).<br>\n      *(Also Group 14 contains non-metal C, metalloids Si/Ge, and metals Sn/Pb).*\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Group 17 element (F/Cl) and (b) Group 2 element (Mg/Ca)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Group 16 element (O/S) and (d) Group 17 with state justification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q26 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q26\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q26')\">\n      <div class=\"q-num\">Question 3.26</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The increasing order of reactivity among group 1 elements is $\\text{Li} < \\text{Na} < \\text{K} < \\text{Rb} < \\text{Cs}$ whereas that among group 17 elements is $\\text{F} > \\text{Cl} > \\text{Br} > \\text{I}$. Explain.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>1. Group 1 Elements (Alkali Metals):</b><br>\n      • Group 1 elements react by **losing one valence electron** to form unipositive cations ($\\text{M} \\to \\text{M}^+ + e^-$).<br>\n      • Their chemical reactivity is governed by their **ease of losing an electron**, which is directly proportional to how low their ionization enthalpy is.<br>\n      • Down Group 1, atomic radius increases and ionization enthalpy decreases ($\\text{Cs}$ has lowest $\\Delta_i H$). Hence, electron loss becomes progressively easier:<br>\n      $$\\mathbf{\\text{Reactivity: } \\text{Li} < \\text{Na} < \\text{K} < \\text{Rb} < \\text{Cs}}$$<br><br>\n      <b>2. Group 17 Elements (Halogens):</b><br>\n      • Group 17 elements react by **gaining one electron** to complete a stable octet ($\\text{X} + e^- \\to \\text{X}^-$).<br>\n      • Their chemical reactivity depends on their **oxidizing ability and electron-accepting tendency** (electronegativity).<br>\n      • Down Group 17, atomic radius increases, nuclear attraction on incoming electrons weakens, and electronegativity decreases.<br>\n      • Fluorine is the smallest, most electronegative element with the highest standard reduction potential, making it the most reactive halogen:<br>\n      $$\\mathbf{\\text{Reactivity: } \\text{F} > \\text{Cl} > \\text{Br} > \\text{I}}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Group 1 reactivity depends on electron loss / ionization enthalpy decreasing down group</span><span class=\"marking-marks\">1.25 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Group 17 reactivity depends on electron gain / electronegativity decreasing down group</span><span class=\"marking-marks\">1.25 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q27 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q27\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q27')\">\n      <div class=\"q-num\">Question 3.27</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write the general outer electronic configuration of $s-, p-, d-$ and $f-$block elements.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>General Outer Electronic Configurations by Block:</b><br><br>\n      1. **$s$-Block Elements:**<br>\n      $$\\mathbf{n s^{1-2}} \\quad (n = 2 \\text{ to } 7)$$<br>\n      • Group 1 (Alkali metals): $ns^1$<br>\n      • Group 2 (Alkaline earth metals): $ns^2$<br><br>\n      2. **$p$-Block Elements:**<br>\n      $$\\mathbf{n s^2 \\; n p^{1-6}} \\quad (n = 2 \\text{ to } 7)$$<br>\n      (Groups 13 to 18; Helium is $1s^2$).<br><br>\n      3. **$d$-Block Elements (Transition Metals):**<br>\n      $$\\mathbf{(n - 1) d^{1-10} \\; n s^{0-2}} \\quad (n = 4 \\text{ to } 7)$$<br>\n      (Groups 3 to 12).<br><br>\n      4. **$f$-Block Elements (Inner Transition Metals):**<br>\n      $$\\mathbf{(n - 2) f^{1-14} \\; (n - 1) d^{0-1} \\; n s^2} \\quad (n = 6 \\text{ and } 7)$$<br>\n      • Lanthanoids ($n = 6$): $4f^{1-14} 5d^{0-1} 6s^2$<br>\n      • Actinoids ($n = 7$): $5f^{1-14} 6d^{0-1} 7s^2$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">s-block (ns^1-2) and p-block (ns^2 np^1-6) general configurations</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">d-block ((n-1)d^1-10 ns^0-2) and f-block ((n-2)f^1-14 (n-1)d^0-1 ns^2)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q28 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q28\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q28')\">\n      <div class=\"q-num\">Question 3.28</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Assign the position of the element having outer electronic configuration<br>\n       (i) $ns^2 np^4$ for $n = 3$<br>\n       (ii) $(n-1)d^2 ns^2$ for $n = 4$, and<br>\n       (iii) $(n-2)f^7 (n-1)d^1 ns^2$ for $n = 6$, in the periodic table.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>(i) $ns^2 np^4$ for $n = 3$:</b><br>\n      • Configuration: $3s^2 3p^4$ (Core: $[\\text{Ne}]$) $\\implies Z = 16$ (Sulfur, $\\text{S}$).<br>\n      • **Period:** Highest $n = 3 \\implies \\mathbf{3^{\\text{rd}} \\text{ Period}}$.<br>\n      • **Block:** Differentiating electron in $p$-orbital $\\implies \\mathbf{p\\text{-block}}$.<br>\n      • **Group:** $10 + \\text{valence electrons} = 10 + (2 + 4) = \\mathbf{16}$.<br><br>\n      <b>(ii) $(n-1)d^2 ns^2$ for $n = 4$:</b><br>\n      • Configuration: $3d^2 4s^2$ (Core: $[\\text{Ar}]$) $\\implies Z = 22$ (Titanium, $\\text{Ti}$).<br>\n      • **Period:** Highest $n = 4 \\implies \\mathbf{4^{\\text{th}} \\text{ Period}}$.<br>\n      • **Block:** Differentiating electron in $d$-orbital $\\implies \\mathbf{d\\text{-block}}$.<br>\n      • **Group:** Electrons in $(n-1)d + ns = 2 + 2 = \\mathbf{4}$.<br><br>\n      <b>(iii) $(n-2)f^7 (n-1)d^1 ns^2$ for $n = 6$:</b><br>\n      • Configuration: $4f^7 5d^1 6s^2$ (Core: $[\\text{Xe}]$) $\\implies Z = 64$ (Gadolinium, $\\text{Gd}$).<br>\n      • **Period:** Highest $n = 6 \\implies \\mathbf{6^{\\text{th}} \\text{ Period}}$.<br>\n      • **Block:** Differentiating electron in $f$-orbital $\\implies \\mathbf{f\\text{-block (Lanthanoid series)}}$.<br>\n      • **Group:** All lanthanoids belong formally to $\\mathbf{\\text{Group 3}}$.\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Period 3, Group 16, p-block</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Period 4, Group 4, d-block</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Period 6, Group 3, f-block (Lanthanoids)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q29 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q29\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q29')\">\n      <div class=\"q-num\">Question 3.29</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The first ($\\Delta_i H_1$) and the second ($\\Delta_i H_2$) ionization enthalpies (in $\\text{kJ mol}^{-1}$) and the ($\\Delta_{\\text{eg}} H$) electron gain enthalpy (in $\\text{kJ mol}^{-1}$) of a few elements are given below:<br>\n       Elements | $\\Delta_i H_1$ | $\\Delta_i H_2$ | $\\Delta_{\\text{eg}} H$<br>\n       I | 520 | 7300 | -60<br>\n       II | 419 | 3051 | -48<br>\n       III | 1681 | 3374 | -328<br>\n       IV | 1008 | 1846 | -295<br>\n       V | 2372 | 5251 | +48<br>\n       VI | 738 | 1451 | -40<br>\n       Which of the above elements is likely to be:<br>\n       (a) the least reactive element.<br>\n       (b) the most reactive metal.<br>\n       (c) the most reactive non-metal.<br>\n       (d) the least reactive non-metal.<br>\n       (e) the metal which can form a stable binary halide of the formula $\\text{MX}_2$ ($\\text{X} = \\text{halogen}$).<br>\n       (f) the metal which can form a predominantly stable covalent halide of the formula $\\text{MX}$ ($\\text{X} = \\text{halogen}$).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Identification of Elements from Thermodynamic Properties:</b><br><br>\n      • **(a) The least reactive element: Element V**<br>\n      Highest first ionization enthalpy ($2372\\text{ kJ/mol}$) and a positive electron gain enthalpy ($+48\\text{ kJ/mol}$), characteristic of a noble gas (Helium).<br><br>\n      • **(b) The most reactive metal: Element II**<br>\n      Lowest first ionization enthalpy ($419\\text{ kJ/mol}$) and low negative electron gain enthalpy ($\\text{K}$, alkali metal).<br><br>\n      • **(c) The most reactive non-metal: Element III**<br>\n      Very high ionization enthalpy ($1681\\text{ kJ/mol}$) and the most negative electron gain enthalpy ($-328\\text{ kJ/mol}$), characteristic of a reactive halogen (Fluorine/Chlorine).<br><br>\n      • **(d) The least reactive non-metal: Element IV**<br>\n      High ionization enthalpy ($1008\\text{ kJ/mol}$) and high negative electron gain enthalpy ($-295\\text{ kJ/mol}$), but less exothermic than III (Group 16/17, e.g., Iodine).<br><br>\n      • **(e) Metal forming stable binary halide $\\text{MX}_2$: Element VI**<br>\n      Moderate $\\Delta_i H_1 = 738\\text{ kJ/mol}$ and $\\Delta_i H_2 = 1451\\text{ kJ/mol}$ (alkaline earth metal, e.g., $\\text{Mg}$), forming divalent $\\text{M}^{2+}$ cations.<br><br>\n      • **(f) Metal forming predominantly stable covalent halide $\\text{MX}$: Element I**<br>\n      Low $\\Delta_i H_1 = 520\\text{ kJ/mol}$ but immense jump to $\\Delta_i H_2 = 7300\\text{ kJ/mol}$ (Alkali metal, specifically $\\text{Li}$ with high charge density forming covalent halides like $\\text{LiCl}$).\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Element V (noble gas) and (b) Element II (alkali metal)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Element III (halogen) and (d) Element IV (less reactive non-metal)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Element VI (alkaline earth, MX2) and (f) Element I (Li, covalent MX)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q30 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q30\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q30')\">\n      <div class=\"q-num\">Question 3.30</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Predict the formulas of the stable binary compounds that would be formed by the combination of the following pairs of elements:<br>\n       (a) Lithium and oxygen<br>\n       (b) Magnesium and nitrogen<br>\n       (c) Aluminium and iodine<br>\n       (d) Silicon and oxygen<br>\n       (e) Phosphorus and fluorine<br>\n       (f) Element 71 and fluorine.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      Using valency rules based on group numbers:<br><br>\n      • **(a) Lithium (Group 1, valency 1) and Oxygen (Group 16, valency 2):**<br>\n      $$\\mathbf{\\text{Li}_2\\text{O} \\text{ (Lithium oxide)}}$$<br><br>\n      • **(b) Magnesium (Group 2, valency 2) and Nitrogen (Group 15, valency 3):**<br>\n      $$\\mathbf{\\text{Mg}_3\\text{N}_2 \\text{ (Magnesium nitride)}}$$<br><br>\n      • **(c) Aluminium (Group 13, valency 3) and Iodine (Group 17, valency 1):**<br>\n      $$\\mathbf{\\text{AlI}_3 \\text{ (Aluminium iodide)}}$$<br><br>\n      • **(d) Silicon (Group 14, valency 4) and Oxygen (Group 16, valency 2):**<br>\n      Ratio $4 : 2 = 2 : 1 \\implies \\mathbf{\\text{SiO}_2 \\text{ (Silicon dioxide)}}$<br><br>\n      • **(e) Phosphorus (Group 15, valency 3 or 5) and Fluorine (Group 17, valency 1):**<br>\n      $$\\mathbf{\\text{PF}_3 \\text{ and } \\text{PF}_5 \\text{ (Phosphorus trifluoride / pentafluoride)}}$$<br><br>\n      • **(f) Element 71 (Lutetium, $\\text{Lu}$, Lanthanoid, stable valency 3) and Fluorine (valency 1):**<br>\n      $$\\mathbf{\\text{LuF}_3 \\text{ (Lutetium trifluoride)}}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(a) Li2O, (b) Mg3N2, (c) AlI3</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) SiO2, (e) PF3 / PF5, (f) LuF3 (Element 71)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q31 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q31\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q31')\">\n      <div class=\"q-num\">Question 3.31</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In the modern periodic table, the period indicates the value of:<br>\n       (a) atomic number<br>\n       (b) atomic mass<br>\n       (c) principal quantum number<br>\n       (d) azimuthal quantum number.\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (c) principal quantum number ($n$)</b><br><br>\n      • Each period in the modern periodic table corresponds to the filling of electrons in a new principal energy level characterized by the principal quantum number $n$ of the outermost valence shell.<br>\n      • For example, elements in period 1 have $n = 1$, period 2 have $n = 2$, and so on up to period 7 ($n = 7$).\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct option (c) principal quantum number (n) with explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q32 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q32\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q32')\">\n      <div class=\"q-num\">Question 3.32</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which of the following statements related to the modern periodic table is incorrect?<br>\n       (a) The $p$-block has 6 columns, because a maximum of 6 electrons can occupy all the orbitals in a $p$-subshell.<br>\n       (b) The $d$-block has 8 columns, because a maximum of 8 electrons can occupy all the orbitals in a $d$-subshell.<br>\n       (c) Each block contains a number of columns equal to the number of electrons that can occupy that subshell.<br>\n       (d) The block indicates value of azimuthal quantum number ($l$) for the last subshell that received electrons in building up the electronic configuration.\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (b) The $d$-block has 8 columns, because a maximum of 8 electrons can occupy all the orbitals in a $d$-subshell.</b><br><br>\n      • This statement is **incorrect** because a $d$-subshell possesses $5$ degenerate orbitals ($m_l = -2, -1, 0, +1, +2$).<br>\n      • Since each orbital holds up to $2$ electrons, a $d$-subshell can accommodate a maximum of **$10$ electrons**.<br>\n      • Consequently, the $d$-block in the periodic table consists of **$10$ columns** (Groups 3 to 12), not 8 columns.\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Identification of option (b) as incorrect with 10-electron / 10-column explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q33 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q33\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q33')\">\n      <div class=\"q-num\">Question 3.33</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Anything that influences the valence electrons will affect the chemistry of the element. Which one of the following factors does not affect the valence shell?<br>\n       (a) Valence principal quantum number ($n$)<br>\n       (b) Nuclear charge ($Z$)<br>\n       (c) Nuclear mass<br>\n       (d) Number of core electrons.\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (c) Nuclear mass</b><br><br>\n      • Chemical properties and valence shell interactions are governed exclusively by electrostatic forces between the positive nuclear charge ($Z$) and negative electrons, shielded by core electrons.<br>\n      • The **nuclear mass** (mass number $A$, governed by neutrons) does not alter electrostatic forces or valence orbital energy levels, which is why isotopes of the same element exhibit identical chemical behavior.\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct option (c) Nuclear mass with reasoning</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q34 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q34\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q34')\">\n      <div class=\"q-num\">Question 3.34</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The size of isoelectronic species — $\\text{F}^-$, $\\text{Ne}$ and $\\text{Na}^+$ is affected by:<br>\n       (a) nuclear charge ($Z$)<br>\n       (b) valence principal quantum number ($n$)<br>\n       (c) electron-electron interaction in the outer orbitals<br>\n       (d) none of the factors because their size is the same.\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (a) nuclear charge ($Z$)</b><br><br>\n      • In an isoelectronic series ($\\text{F}^-, \\text{Ne}, \\text{Na}^+$), all species possess the exact same total number of electrons ($10\\text{ e}^-$) and the same principal quantum number ($n = 2$).<br>\n      • The only variable parameter is the **nuclear charge ($Z$)**: $\\text{F} (+9)$, $\\text{Ne} (+10)$, $\\text{Na} (+11)$.<br>\n      • Higher nuclear charge pulls the electron cloud inward with greater electrostatic attraction, resulting in the size order: $\\text{F}^- (133\\text{ pm}) > \\text{Ne} > \\text{Na}^+ (102\\text{ pm})$.\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct option (a) nuclear charge (Z) with inverse size explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q35 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q35\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q35')\">\n      <div class=\"q-num\">Question 3.35</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which one of the following statements is incorrect in relation to ionization enthalpy?<br>\n       (a) Ionization enthalpy increases for each successive electron.<br>\n       (b) The greatest increase in ionization enthalpy is experienced on removal of an electron from core noble gas configuration.<br>\n       (c) End of valence electrons is marked by a big jump in ionization enthalpy.<br>\n       (d) Removal of electron from orbitals bearing lower $n$ value is easier than from orbital having higher $n$ value.\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (d) Removal of electron from orbitals bearing lower $n$ value is easier than from orbital having higher $n$ value.</b><br><br>\n      • This statement is **incorrect**.<br>\n      • Orbitals with a **lower $n$ value** are located closer to the nucleus and held much more tightly by the strong electrostatic attraction.<br>\n      • Therefore, removing an electron from a lower $n$ shell requires **substantially more energy** than removing one from a higher $n$ shell (which is farther away and well-shielded).\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Identification of option (d) as incorrect with distance/attraction justification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q36 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q36\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q36')\">\n      <div class=\"q-num\">Question 3.36</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Considering the elements $\\text{B, Al, Mg,}$ and $\\text{K}$, the correct order of their metallic character is:<br>\n       (a) $\\text{B} > \\text{Al} > \\text{Mg} > \\text{K}$<br>\n       (b) $\\text{Al} > \\text{Mg} > \\text{B} > \\text{K}$<br>\n       (c) $\\text{Mg} > \\text{Al} > \\text{K} > \\text{B}$<br>\n       (d) $\\text{K} > \\text{Mg} > \\text{Al} > \\text{B}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (d) $\\text{K} > \\text{Mg} > \\text{Al} > \\text{B}$</b><br><br>\n      <b>Justification:</b><br>\n      1. **Trend in Periodic Table:**<br>\n      • Metallic character **increases down a group** (due to increasing size and decreasing ionization enthalpy).<br>\n      • Metallic character **decreases across a period** from left to right (due to increasing nuclear charge and electronegativity).<br><br>\n      2. **Comparing Elements:**<br>\n      • $\\text{K}$ belongs to Group 1, Period 4: Large alkali metal, lowest ionization enthalpy $\\implies$ **Most metallic**.<br>\n      • $\\text{Mg}$ (Group 2, Period 3) and $\\text{Al}$ (Group 13, Period 3): Across Period 3, metallic character decreases from left to right $\\implies \\text{Mg} > \\text{Al}$.<br>\n      • $\\text{B}$ (Group 13, Period 2): Sits at the top of Group 13 above $\\text{Al}$, non-metal / metalloid with highest ionization enthalpy $\\implies$ **Least metallic**.<br><br>\n      $$\\mathbf{\\text{Order: } \\text{K} > \\text{Mg} > \\text{Al} > \\text{B}}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct option (d) K > Mg > Al > B</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification via group/period trends and ionization enthalpies</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q37 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q37\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q37')\">\n      <div class=\"q-num\">Question 3.37</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Considering the elements $\\text{B, C, N, F,}$ and $\\text{Si}$, the correct order of their non-metallic character is:<br>\n       (a) $\\text{B} > \\text{C} > \\text{Si} > \\text{N} > \\text{F}$<br>\n       (b) $\\text{Si} > \\text{C} > \\text{B} > \\text{N} > \\text{F}$<br>\n       (c) $\\text{F} > \\text{N} > \\text{C} > \\text{B} > \\text{Si}$<br>\n       (d) $\\text{F} > \\text{N} > \\text{C} > \\text{Si} > \\text{B}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (c) $\\text{F} > \\text{N} > \\text{C} > \\text{B} > \\text{Si}$ (or (d) in some keys where $\\text{Si} < \\text{B}$)</b><br><br>\n      <b>Justification:</b><br>\n      1. Non-metallic character increases across a period from left to right and decreases down a group.<br>\n      2. For the second period elements, the non-metallic character increases in order: $\\text{B} < \\text{C} < \\text{N} < \\text{F}$.<br>\n      3. Silicon ($\\text{Si}$) lies below Carbon in Group 14 (Period 3). Because non-metallic character decreases down a group, $\\text{Si}$ is more metallic (less non-metallic) than Carbon.<br>\n      4. Fluorine is the most non-metallic element in the periodic table. Nitrogen comes second, followed by Carbon.<br>\n      $$\\mathbf{\\text{Decreasing order: } \\text{F} > \\text{N} > \\text{C} > \\text{B} > \\text{Si}}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct order F > N > C > B > Si identified</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation based on period increase and group decrease in non-metallic character</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q38 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q38\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q38')\">\n      <div class=\"q-num\">Question 3.38</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Considering the elements with the following atomic numbers:<br>\n       (a) $11$, (b) $12$, (c) $13$, (d) $14$, (e) $15$, (f) $16$, (g) $17$.<br>\n       Arrange them in the order of:<br>\n       (i) increasing ionization enthalpy<br>\n       (ii) increasing electronegativity.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      These atomic numbers represent the complete third period: $\\text{Na} (11), \\text{Mg} (12), \\text{Al} (13), \\text{Si} (14), \\text{P} (15), \\text{S} (16), \\text{Cl} (17)$.<br><br>\n      <b>(i) Increasing Order of Ionization Enthalpy:</b><br>\n      General trend is an increase from left to right, with anomalies at $\\text{Mg} > \\text{Al}$ (full $3s^2$ vs $3p^1$) and $\\text{P} > \\text{S}$ (half-filled $3p^3$ vs $3p^4$):<br>\n      $$\\mathbf{\\text{Na} < \\text{Al} < \\text{Mg} < \\text{Si} < \\text{S} < \\text{P} < \\text{Cl}}$$<br>\n      $$\\mathbf{\\text{In terms of letters: } (a) < (c) < (b) < (d) < (f) < (e) < (g)}$$<br><br>\n      <b>(ii) Increasing Order of Electronegativity:</b><br>\n      Electronegativity increases smoothly across Period 3 with increasing nuclear charge and decreasing atomic size (no subshell anomalies on the Pauling scale):<br>\n      $$\\mathbf{\\text{Na} < \\text{Mg} < \\text{Al} < \\text{Si} < \\text{P} < \\text{S} < \\text{Cl}}$$<br>\n      $$\\mathbf{\\text{In terms of letters: } (a) < (b) < (c) < (d) < (e) < (f) < (g)}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">(i) Ionization enthalpy sequence with subshell anomalies: Na < Al < Mg < Si < S < P < Cl</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Electronegativity monotonic sequence: Na < Mg < Al < Si < P < S < Cl</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q39 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q39\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q39')\">\n      <div class=\"q-num\">Question 3.39</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Considering the elements $\\text{B, C, N, F,}$ and $\\text{Si}$, the correct order of their non-metallic character is:<br>\n       (a) $\\text{B} > \\text{C} > \\text{Si} > \\text{N} > \\text{F}$<br>\n       (b) $\\text{Si} > \\text{C} > \\text{B} > \\text{N} > \\text{F}$<br>\n       (c) $\\text{F} > \\text{N} > \\text{C} > \\text{B} > \\text{Si}$<br>\n       (d) $\\text{F} > \\text{N} > \\text{C} > \\text{Si} > \\text{B}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (d) $\\text{F} > \\text{N} > \\text{C} > \\text{Si} > \\text{B}$ (or (c) $\\text{F} > \\text{N} > \\text{C} > \\text{B} > \\text{Si}$)</b><br><br>\n      <b>Comprehensive Analysis:</b><br>\n      • Across Period 2, non-metallic character increases: $\\text{B} < \\text{C} < \\text{N} < \\text{F}$.<br>\n      • Down a group, non-metallic character decreases (e.g., $\\text{C} > \\text{Si}$).<br>\n      • Fluorine is the most non-metallic element, followed by Nitrogen and Carbon.<br>\n      • Between Boron and Silicon: In the periodic table diagonal relationship, Boron is a metalloid/non-metal with electronegativity $2.04$, while Silicon has electronegativity $1.90$. In standard NCERT keys, both (c) and (d) capture Fluorine and Nitrogen leading, with option **(d)** listed as the official CBSE key in recent editions.<br><br>\n      $$\\mathbf{\\text{Decreasing non-metallic character: } \\text{F} > \\text{N} > \\text{C} > \\text{Si} > \\text{B} \\text{ (Option d)}}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct sequence F > N > C > Si > B (or F > N > C > B > Si)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification via electronegativity and period/group gradients</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11c-ch3-q40 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11c-ch3-q40\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11c-ch3-q40')\">\n      <div class=\"q-num\">Question 3.40</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Considering the elements $\\text{F, Cl, O}$ and $\\text{N}$, the correct order of their chemical reactivity in terms of oxidizing property is:<br>\n       (a) $\\text{F} > \\text{Cl} > \\text{O} > \\text{N}$<br>\n       (b) $\\text{F} > \\text{O} > \\text{Cl} > \\text{N}$<br>\n       (c) $\\text{Cl} > \\text{F} > \\text{O} > \\text{N}$<br>\n       (d) $\\text{O} > \\text{F} > \\text{N} > \\text{Cl}$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n      <b>Correct Option: (b) $\\text{F} > \\text{O} > \\text{Cl} > \\text{N}$</b><br><br>\n      <b>Justification:</b><br>\n      1. **Oxidizing Power Definition:** An oxidizing agent gains electrons during a chemical reaction. The oxidizing property depends directly on the element's electronegativity and standard reduction potential ($E^\\circ$).<br><br>\n      2. **Electronegativities on the Pauling Scale:**<br>\n      • Fluorine ($\\text{F}$): $4.0$ (highest in periodic table, $E^\\circ = +2.87\\text{ V}$)<br>\n      • Oxygen ($\\text{O}$): $3.5$ ($E^\\circ = +1.23\\text{ V}$)<br>\n      • Chlorine ($\\text{Cl}$): $3.0$ ($E^\\circ = +1.36\\text{ V}$)<br>\n      • Nitrogen ($\\text{N}$): $3.0$ (stable half-filled $2p^3$, poor electron acceptor)<br><br>\n      3. **Relative Comparison:**<br>\n      • Fluorine oxidizes water to oxygen, proving it is a stronger oxidizer than oxygen.<br>\n      • Oxygen oxidizes chloride to chlorine in acidic media, confirming $\\text{O} > \\text{Cl}$.<br>\n      • Nitrogen has a stable half-filled $2p^3$ configuration and lacks oxidizing vigor compared to halogens and oxygen.<br><br>\n      $$\\mathbf{\\text{Correct order of oxidizing property: } \\text{F} > \\text{O} > \\text{Cl} > \\text{N} \\quad \\text{(Option b)}}$$\n    </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n                    <div class=\"marking-row\"><span class=\"marking-key\">Correct option (b) F > O > Cl > N</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification via electronegativities (F: 4.0, O: 3.5, Cl: 3.0, N: 3.0) and reduction potentials</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>";
